  bodyIK:{label:'Body / arms IK / limb solving', re:/full[- ]body|body ik|arm ik|leg ik|two[- ]bone|shoulder|elbow|pelvis|torso|knee|waist|limb|\bfbt\b|skeleton solve|joint estimation/i},
