  melee:{label:'Melee / physical combat', re:/melee|saber|knife|crowbar|punch|swing|strike|parry|blade|damage trace|hitbox|swept/i},
  physicalInteraction:{label:'Physical interaction / object manipulation', re:/physical interaction|grab|grabbing|drag|throw|pickup|button|lever|door|touch|proximity|body[- ]zone|inventory|object interaction|interact|ladder|climb/i},
  gestureInteraction:{label:'Spatial gesture recognition', re:/gesture|swipe|push\/pull|force push|force pull|near (the )?head|behind (the )?shoulder|body-relative|spatial intent|radial selector/i},
  ui:{label:'VR UI / HUD / pointer interaction', re:/\bui\b|hud|gui|menu|overlay|quad layer|pointer|reticle|crosshair|keyboard|hotbar|wrist ui|screen layer|screen-space/i},
  locomotion:{label:'Locomotion / roomscale / climbing', re:/locomotion|roomscale|movement|teleport|snap turn|smooth turn|crouch|prone|sneak|crawl|climb|ladder|swim|jump|grounding|collision solver/i},
