  haptics:{label:'Haptics / physical feedback', re:/haptic|vibrat|feedback|bhaptics|protube|rumble|hilt kick/i},
  nativeAuthority:{label:'Native gameplay authority / integration boundary', re:/native.*author|gameplay authority|existing .*system|original .*system|original .*weapon|retain(s|ed)? .*native|remain(s|ed)? authoritative|reuse(s|d)? .*native|calls? .*native|feeds? .*native|state machine|traceattack|applymultidamage/i},
  sourceEvidence:{label:'Source files / symbols / evidence', re:/important source files|source audit files|source files|key symbols|important functions|verified from source|verified from documentation|evidence boundaries|source-backed|supplied source/i},
