    "game": "Hytale",
    "engineFamily": "Hytale client",
    "renderAPI": "Game renderer plus injected OpenVR camera path and UI scaling hook",
    "injectionMethod": "Windows x64 native injector/dashboard with MinHook-based UI hook and a live camera/coordinate hook",
    "platform": "PC VR / Windows",
    "status": "alpha",
