    "id": "pattern_jkxr_two_hand_weapon_solver",
    "type": "pattern",
    "title": "JKXR — contextual support-grip solver for firearms and sabers",
    "game": "",
    "engineFamily": "OpenJK / Raven weapons",
    "renderAPI": "OpenXR controller poses",
