    "id": "seed_mw5_uevr_plugins_case",
    "type": "case_study",
    "title": "MechWarrior 5 — MechWarriorVR UEVR plugin stack",
    "game": "MechWarrior 5: Mercenaries",
    "engineFamily": "Unreal Engine / UEVR",
    "renderAPI": "UEVR + Unreal D3D rendering hooks",
    "injectionMethod": "UEVR profile plus native C++ plugins for camera, HUD, head aim and haptics",
