    "id": "pattern_rdrvr_physical_reload_native_state",
    "type": "pattern",
    "title": "RDRVR — physical reload gesture with weapon-specific native state transitions",
    "game": "",
    "engineFamily": "Native weapon / inventory state",
    "renderAPI": "D3D12 + OpenXR controllers",
    "injectionMethod": "Gesture recognizers plus reload/switch hooks",
    "platform": "PC VR / native PC game modding",
    "status": "proven",
