    "title": "Separate 1:1 roomscale anchor from render-camera compensation — L4D2VR reference",
    "game": "Left 4 Dead 2",
    "engineFamily": "Source Engine",
    "renderAPI": "Direct3D 9",
    "injectionMethod": "Native camera and movement hooks",
    "platform": "PC VR",
    "status": "proven",
