    "id": "pattern_l4d2vr_thread_boundary_tracking_commands",
    "type": "pattern",
    "title": "Bridge high-rate tracking to game-thread interaction through explicit samples — L4D2VR reference",
    "game": "Left 4 Dead 2",
    "engineFamily": "Source Engine",
    "renderAPI": "Direct3D 9",
    "injectionMethod": "Native tracking and CreateMove integration",
    "platform": "PC VR",
    "status": "proven",
