    "id": "pattern_l4d2vr_queued_pose_waiter_timing",
    "type": "pattern",
    "title": "Decouple SteamVR pose waits from the queued Source render thread — L4D2VR reference",
    "game": "Left 4 Dead 2",
    "engineFamily": "Source Engine / SteamVR Input and Compositor",
