    "id": "pattern_cyberpunk_data_driven_physical_reload",
    "type": "pattern",
    "title": "CyberpunkVR — generic physical reload state machine with per-weapon geometry and mechanism adapters",
    "game": "Cyberpunk 2077",
    "engineFamily": "REDengine 4; native VR retrofit methodology",
    "renderAPI": "DirectX 12 + OpenXR",
