    "sourceLinks": "https://github.com/jbusfield/SN2_UEVR, https://github.com/jbusfield/SN2_UEVR/blob/main/scripts/main.lua, https://github.com/jbusfield/SN2_UEVR/releases",
    "submittedBy": "source-audit",
