CODE_AUDITS["pattern_rdrvr_dual_wield_independent_weapon_instances"] = "VERIFIED FROM THE SUPPLIED RDRVR SOURCE: src/core/dual.cpp resolves the secondary firearm from the native weapon-manager slots and checks that the candidate is not the current weapon, is a live/loaded prop with firearm tuning, and is not a melee item. A secondary slot carries object identity plus generation/tick bookkeeping so delayed trigger work cannot blindly act on a stale weapon after swaps. Launch handling distinguishes the secondary firearm from the primary barrel ray; copy-sidearm mode transforms the copied sidearm launch point/direction using its own transform and tracks clip/ammo, muzzle flash and native bookkeeping. Transfer lesson: represent each hand-held weapon as a separately validated native instance with its own pose, ammo, launch path and lifecycle token. Do not emulate dual wield by firing the primary twice or by reusing the primary muzzle. UNKNOWN: exhaustive behavior across every weapon-wheel transition and online/multiplayer edge case was not runtime tested.";
CODE_AUDITS["pattern_rdrvr_manual_action_gate_and_native_ammo_commit"] = "VERIFIED FROM THE SUPPLIED RDRVR SOURCE: src/core/actions.cpp maintains weapon-family readiness state and reacts to the game's actual clip-count change rather than treating trigger input alone as proof of a shot. Separate action sequences cover revolver/break-action opening, lever down/up, pump back/forward, bolt lift/back/forward/down, breech open/load/close and semi-auto shotgun rack-after-empty behavior. Blocked trigger edges produce click/haptic feedback and require release/rearm; Dead Eye/state transitions reset the machine. src/core/holster.cpp gates spatial ammo insertion on a valid weapon, clip capacity, reserve ammo, action state, and non-reload/non-Dead-Eye state, then src/core/reload.cpp queues the game's ACTOR_ADD_WEAPON_AMMO native operation to commit ammo through the engine. Reload hooks classify call sites and suppress only selected VR-conflicting requests, preserving unrelated native action/network paths. Transfer lesson: physical reload is a validated transaction: visual pickup/gesture is intent; native ammo mutation is commit; the weapon's native action state remains authoritative. README/source does not establish a universal manual magazine-pistol reload; that remains limited/unsupported in this snapshot.";
CODE_AUDITS["pattern_rdrvr_hand_velocity_projectile_launch"] = "VERIFIED FROM THE SUPPLIED RDRVR SOURCE: src/core/gestures.cpp stores recent hand-velocity samples and requires a qualifying peak (default threshold 1.5 m/s over the recent 800 ms window) before treating release as a throw. It maps hand velocity through the game-camera heading and applies the configured throw gain; the path is intentionally separate from firearm muzzle aiming. src/core/aim.cpp keeps the native hk_launch path while adapting eligible local-player throwable launch origin/velocity, and its comments distinguish tested behavior from unsupported assumptions. Weapon-ID filtering limits the throwable path; the bow is explicitly excluded from the hitscan-style barrel-direction correction because its trajectory is arc-based. Quick-throw and grip-held-release options alter the game's clip/release timing rather than replacing the game's projectile system. Transfer lesson: validate a short velocity history, map it into the game's world frame, clamp/tune it, and feed the game's authoritative projectile launch; keep thrown physics and hitscan gun aim as distinct paths. Runtime testing across every throwable was not performed.";

async function loadDB(){
  // Always start from the source-audited registry bundled with the page.
  // The only browser-local overlay retained is vote state.
  DB = SEED.slice();
  render();
  try{
    let raw = null;
    if(window.storage && typeof window.storage.get === 'function'){
      const res = await window.storage.get(STORAGE_KEY, true);
      raw = res && res.value ? res.value : null;
    } else {
      raw = localStorage.getItem(STORAGE_KEY);
    }
    if(raw){
      applyOverlay(JSON.parse(raw));
      render();
    }
  }catch(e){
    console.warn('VRegistry: local overlay could not be loaded.', e);
  }
}

function applyOverlay(overlay){
  const votes = overlay.votes || {};
  DB = SEED.map(e => votes[e.id]!=null ? {...e, votes:votes[e.id]} : e);
}

async function saveDB(){
  const seedIds = new Set(SEED.map(e=>e.id));
  const votes = {};
  DB.forEach(e=>{ if(seedIds.has(e.id)) votes[e.id] = e.votes||0; });
  const payload = JSON.stringify({votes});
  try{
    if(window.storage && typeof window.storage.set === 'function'){
      await window.storage.set(STORAGE_KEY, payload, true);
    } else {
      localStorage.setItem(STORAGE_KEY, payload);
    }
  }catch(e){
    showToast('Could not save this local change in your browser.');
  }
}

function showToast(msg){
  const el = document.createElement('div');
  el.className = 'toast';
  el.textContent = msg;
  document.body.appendChild(el);
  setTimeout(()=>el.remove(), 2600);
}

function uniqueVals(field){
  const s = new Set(DB.map(e=>e[field]).filter(Boolean));
  return Array.from(s).sort();
}

// Keep the registry's underlying source labels precise, but expose broad,
// useful categories in the sidebar so the facet list stays manageable.
function engineCategory(v){
  const x=(v||'').toLowerCase();
  if(x.includes('unreal') || x.includes('vengeance')) return 'Unreal Engine';
  if(x.includes('unity')) return 'Unity';
  if(x.includes('source engine') || x.includes('source sdk')) return 'Source Engine';
  if(x.includes('id tech') || x.includes('idtech') || x.includes('gzdoom') || x.includes('quake')) return 'id Tech / Quake';
  if(x.includes('openmw') || x.includes('world of warcraft') || x.includes('bethesda')) return 'Open-world / RPG engines';
  if(x.includes('rage') || x.includes('redengine') || x.includes('anvil')) return 'AAA proprietary engines';
  if(x.includes('cryengine')) return 'CryEngine';
  if(x.includes('godot')) return 'Godot';
  return 'Other / custom engines';
}

function apiCategory(v){
  const x=(v||'').toLowerCase();
  if(x.includes('uevr')) return 'UEVR';
  if(x.includes('unity')) return 'Unity VR';
  if(x.includes('openxr') || x.includes('openvr') || x.includes('steamvr') || x.includes('oculus')) return 'OpenXR / OpenVR / runtime';
  if(x.includes('vulkan')) return 'Vulkan';
  if(x.includes('direct3d') || x.includes('directx') || x.includes('d3d') || x.includes('dxgi') || x.includes('dx11') || x.includes('dx12')) return 'DirectX / D3D';
  if(x.includes('opengl') || x.includes('gles') || x.includes('openscenegraph')) return 'OpenGL / GLES';
  if(x.includes('emulator')) return 'Emulator / translation layer';
  return 'Native / other';
}

// High-level integration taxonomy for the sidebar. The raw `injectionMethod` field remains
// deliberately detailed in each expanded entry; this function only answers the simpler
// question: "How does the VR layer get into / alongside the game?"
function injectionCategory(v){
  const x=(v||'').toLowerCase();
  if(!x) return 'Unknown / unspecified';
  if(x.includes('no game injection') || x.includes('no runtime injection') || x.includes('external process') || x.includes('client-side') || x.includes('client side'))
    return 'External / no game injection';
  if(x.includes('source-level') || x.includes('source patch') || x.includes('source rewrite') || x.includes('source project') || x.includes('engine fork') || x.includes('standalone engine') || x.includes('dedicated vr executable') || x.includes('port derived from') || x.includes('user-assembled'))
    return 'Source-level / engine fork';
  if(x.includes('uevr') || x.includes('bepinex') || x.includes('melonloader') || x.includes('scripthook') || x.includes('f4se') || x.includes('f4se(vr)') || x.includes('dalamud') || x.includes('mod-loader') || x.includes('mod loader') || x.includes('plugin'))
    return 'Mod/plugin framework';
  if(x.includes('reshade') || x.includes('api layer') || x.includes('renderer compatibility') || x.includes('rendering backend') || x.includes('dxgi') || x.includes('openxr') && x.includes('layer'))
    return 'API / rendering layer';
  if(x.includes('dll') || x.includes('proxy') || x.includes('inline') || x.includes('hook') || x.includes('patch') || x.includes('trampoline') || x.includes('aob') || x.includes('iat') || x.includes('in-process'))
    return 'Native runtime hooks';
  return 'Other / custom runtime integration';
}


function readFilterStateFromURL(){
  try{
    const p=new URLSearchParams(window.location.search);
    const type=p.get('type'); const engine=p.get('engine'); const api=p.get('api'); const injection=p.get('integration'); const feature=p.get('feature'); const q=p.get('q');
    if(['all','pattern','case_study'].includes(type)) filters.type=type;
    if(engine) filters.engine=engine;
    if(api) filters.api=api;
    if(injection) filters.injection=injection;
    if(feature==='all' || FEATURE_DEFS[feature]) filters.feature=feature;
    if(q) filters.query=q;
    const input=document.getElementById('searchInput'); if(input) input.value=filters.query;
  }catch(_e){}
}
function syncFilterStateToURL(){
  try{
    const url=new URL(window.location.href);
    const set=(k,v,def='all')=>{ if(v && v!==def) url.searchParams.set(k,v); else url.searchParams.delete(k); };
    set('type',filters.type); set('engine',filters.engine); set('api',filters.api); set('integration',filters.injection); set('feature',filters.feature);
    if(filters.query.trim()) url.searchParams.set('q',filters.query.trim()); else url.searchParams.delete('q');
    history.replaceState(null,'',url.pathname+(url.searchParams.toString()?`?${url.searchParams.toString()}`:'')+url.hash);
  }catch(_e){}
}
function resetResultPage(){ visibleResultCount=RESULT_PAGE_SIZE; }
function openExplorePreset(el){
  filters.type=el.dataset.type || 'all';
  filters.engine=el.dataset.engine || 'all';
  filters.api=el.dataset.api || 'all';
  filters.injection=el.dataset.injection || 'all';
  filters.feature=el.dataset.feature || 'all';
  filters.query=el.dataset.query || '';
  const input=document.getElementById('searchInput'); if(input) input.value=filters.query;
  resetResultPage(); render(); syncFilterStateToURL();
  document.getElementById('explore')?.scrollIntoView({behavior:'smooth',block:'start'});
}

function applyFilters(){
  const q = filters.query.trim().toLowerCase();
  return DB.filter(e=>{
    if(filters.type!=='all' && e.type!==filters.type) return false;
    if(filters.engine!=='all' && engineCategory(e.engineFamily)!==filters.engine) return false;
    if(filters.api!=='all' && apiCategory(e.renderAPI)!==filters.api) return false;
    if(filters.injection!=='all' && injectionCategory(e.injectionMethod)!==filters.injection) return false;
    if(filters.feature!=='all' && !cachedEntrySubsystems(e).includes(filters.feature)) return false;
    if(q && !cachedEntrySearchText(e).includes(q)) return false;
    return true;
  }).sort((a,b)=> (b.votes||0)-(a.votes||0));
}

function facetGroup(title, field, key, categoryFn){
  const vals = categoryFn ? Array.from(new Set(DB.map(e=>categoryFn(e[field])).filter(Boolean))).sort() : uniqueVals(field);
  const opts = [{label:'All', val:'all'}].concat(vals.map(v=>({label:v, val:v})));
  const rows = opts.map(o=>{
    const cnt = o.val==='all' ? DB.length : DB.filter(e=>(categoryFn ? categoryFn(e[field]) : e[field])===o.val).length;
    const active = filters[key]===o.val ? ' active':'';
    return `<div class="facet-opt${active}" data-key="${key}" data-val="${o.val.replace(/"/g,'&quot;')}">
      <span>${o.label}</span><span class="count">${cnt}</span>
    </div>`;
  }).join('');
  return `<div class="facet-group"><h3>${title}</h3>${rows}</div>`;
}

function filterOption(label,val,active){
  return `<option value="${escapeAttr(val)}" ${active===val?'selected':''}>${escapeHtml(label)}</option>`;
}

function renderFacets(){
  const engines = Array.from(new Set(DB.map(e=>engineCategory(e.engineFamily)).filter(Boolean))).sort();
  const apis = Array.from(new Set(DB.map(e=>apiCategory(e.renderAPI)).filter(Boolean))).sort();
  const integrations = Array.from(new Set(DB.map(e=>injectionCategory(e.injectionMethod)).filter(Boolean))).sort();
  const html = `<div class="filter-panel">
    <div class="filter-panel-head">
      <h3>Refine results</h3>
      <button type="button" data-clear-refinements>Reset</button>
    </div>
    <div class="filter-field">
      <label for="filterType">Entry type</label>
      <select id="filterType" data-filter-select="type">
        ${filterOption('All entries','all',filters.type)}
        ${filterOption('Methodology / pattern','pattern',filters.type)}
        ${filterOption('Case study','case_study',filters.type)}
      </select>
    </div>
    <div class="filter-field">
      <label for="filterEngine">Engine family</label>
      <select id="filterEngine" data-filter-select="engine">
        ${filterOption('All engines','all',filters.engine)}
        ${engines.map(v=>filterOption(v,v,filters.engine)).join('')}
      </select>
    </div>
    <div class="filter-field">
      <label for="filterApi">Render / VR API</label>
      <select id="filterApi" data-filter-select="api">
        ${filterOption('All APIs','all',filters.api)}
        ${apis.map(v=>filterOption(v,v,filters.api)).join('')}
      </select>
    </div>
    <div class="filter-field">
      <label for="filterInjection">Integration method</label>
      <select id="filterInjection" data-filter-select="injection">
        ${filterOption('All integration methods','all',filters.injection)}
        ${integrations.map(v=>filterOption(v,v,filters.injection)).join('')}
      </select>
    </div>
    <p class="filter-note">Subsystem selection lives at the top of the page. These refinements are optional and are also respected by Export for LLM.</p>
  </div>`;
  document.getElementById('facets').innerHTML = html;
}

function cardHTML(e){
  const isOpen = !!expanded[e.id];
  const links = (e.sourceLinks||'').split(',').map(s=>s.trim()).filter(Boolean);
  return `<article class="card" data-entry-id="${escapeAttr(e.id)}">
    <div class="card-top">
      <div>
        <div class="card-title-row">
          <span class="type-tag">${e.type==='pattern' ? 'Pattern' : 'Case study'}</span>
          <h2>${escapeHtml(e.title)}</h2>
        </div>
        <div class="card-meta">
          <span><b>Engine:</b> ${escapeHtml(e.engineFamily)}</span>
          <span><b>API:</b> ${escapeHtml(e.renderAPI)}</span>
          <span><b>Platform:</b> ${escapeHtml(e.platform||'—')}</span>
        </div>
      </div>
    </div>
    <p class="card-summary">${escapeHtml(e.summary)}</p>
    ${(()=>{ const subs=cachedEntrySubsystems(e); if(!subs.length) return ''; const ordered=filters.feature!=='all' && subs.includes(filters.feature) ? [filters.feature,...subs.filter(k=>k!==filters.feature)] : subs; const limit=filters.feature==='all'?5:4; const visible=ordered.slice(0,limit); const more=ordered.length-visible.length; return `<div class="feature-badges">${visible.map(k=>`<span class="feature-badge ${filters.feature===k?'active':''}" data-feature-select="${k}" title="Filter by ${escapeAttr(FEATURE_DEFS[k].label)} — ${escapeAttr(FEATURE_DEFS[k].hint)}">${escapeHtml(featureShortLabel(k))}</span>`).join('')}${more?`<span class="feature-more-badge">+${more}</span>`:''}</div>`; })()}
    <div class="card-foot">
      <button class="expand-link" data-toggle="${e.id}">${isOpen ? 'Close implementation details ↑' : 'Open implementation details ↓'}</button>

    </div>
    ${isOpen ? `
    <div class="card-detail">
      <h4>Injection method</h4><div>${escapeHtml(e.injectionMethod)}</div>
      <h4>Details</h4><div>${escapeHtml(e.details)}</div>
      ${CODE_AUDITS[e.id] ? `<h4>Code / source audit</h4><div>${escapeHtml(CODE_AUDITS[e.id])}</div>` : ''}
      ${e.blockers ? `<h4>Known blockers</h4><div>${escapeHtml(e.blockers)}</div>` : ''}
      ${links.length ? `<h4>Sources</h4><div class="links">${links.map(l=>`<a href="${escapeAttr(l)}" target="_blank" rel="noopener">${escapeHtml(l)}</a>`).join('')}</div>` : ''}
      <div class="submitted-by">Submitted by ${escapeHtml(e.submittedBy||'anonymous')} · ${escapeHtml(e.createdAt||'')}</div>
    </div>` : ''}
  </article>`;
}


CODE_AUDITS["seed_ror2vr_case"] = "VERIFIED FROM SUPPLIED RoR2VRMod 1.0.3 SOURCE (Resurrected VRMod). ARCHITECTURE: BepInEx + HookGenPatcher with a patch-stage `VREnabler` that provisions UnityOpenXR/openxr_loader/subsystem manifest before the main plugin. `VRMod.InitVR` dynamically constructs XRGeneralSettings/XRManagerSettings/OpenXRLoader, selects OpenXR MultiPass, registers common interaction profiles, starts subsystems and explicitly owns shutdown.\n\nRENDERING/TIMING: Unity XR/OpenXR owns compositor/predicted timing. `StereoProjectionFix` keeps a hidden enabled XR-driven reference camera with head TrackedPoseDriver(UpdateAndBeforeRender) and copies the per-eye `GetStereoProjectionMatrix` back into RoR2's real scene camera on pre-cull/pre-render so flat FOV writes cannot break stereo.\n\nCAMERA/SPACES: VRCameraWrapper re-homes CameraRig children beneath an XROrigin Device-space wrapper while native CameraState still rotates the world/body frame; flat recoil/pitch/FOV/DoF paths are suppressed. Recenter uses XRInputSubsystem.TryRecenter plus an absolute non-accumulating menu parent-yaw fallback.\n\nINPUT: Unity XR InputDevices feed one custom Rewired controller mapped into native RoR2 gameplay/UI actions; survivor-specific semantic trigger/grip→SkillSlot overrides are supported.\n\nMOVEMENT: controller-relative movement swaps only the native movement reference; snap/smooth turn stay in the game look path.\n\nHANDS: tracked left/right roots use TrackedPoseDriver UpdateAndBeforeRender, semantic dominance, OpenXR grip-pose correction and local-space rig parenting. RuntimeHands can identify real hand/wrist bones, reconstruct bind pose, weight-filter and BakeMesh survivor hand/optional forearm geometry, capture rigid attached props and re-register renderer materials; optional forearm is explicitly rigid, so this is NOT Body/Arm IK.\n\nWEAPONS: SetHandPair makes tracked muzzle the body aimOrigin and edits ChildLocator named transforms (`CurrentDominantMuzzle`, `CurrentNonDominantMuzzle`, configured replacement names); shared BaseState/GetAimRay and narrow per-ability hooks select tracked hand aim while native entity-state/projectile authority remains. TwoHandedMainHand is angular support-hand stabilization, not a constrained physical grip.\n\nMELEE: MeleeSkill measures weapon-tip speed in VRCameraWrapper-local tracking rig space and turns a qualified swing into a timed native GenericSkill input state; native skill attacks own contact/damage.\n\nSCOPE: SniperScopeController creates a weapon-mounted mono RenderTexture camera plus a mono weak-point UI camera, renders at end-of-frame and composites UI into a true PiP optic.\n\nUI: original canvases are converted/reparented to world/wrist presentation while gamepad/Rewired navigation stays authoritative; current UIPointer ray hooks are intentionally disabled.\n\nCOMFORT: high-motion native EntityState types drive vignette contraction.\n\nMULTIPLAYER: HMD forward is written into existing NetworkedViewAngles; no custom hand/body pose protocol or remote VR embodiment.\n\nHAPTICS: native GamepadVibrationManager output is reused as XR hand impulses; optional suit adapters process accepted damage/health/death events and infer chest facing from HMD+hands.\n\nAPI: VRAPI exposes semantic hand/aim/muzzle/skin/skill-binding/vignette/renderer hooks without exposing OpenXR ownership.\n\nSOURCE BOUNDARIES: no body/arm IK, physical swept melee, manual reload/grab/throw system, remote hand-pose replication, active menu ray pointer, custom predicted-display-time loop or collision-reconciled roomscale body solver demonstrated in 1.0.3.";
CODE_AUDITS["pattern_ror2_openxr_dependency_bootstrap"] = "VERIFIED FROM SOURCE: VREnabler/VREnabler.cs, VREnabler/Dependencies/UnitySubsystemsManifest.json, VREnabler/VRPatcher.csproj. Transfer: when a shipped Unity game lacks the XR provider binaries, use the earliest mod-loader patch stage to establish the subsystem/native dependency boundary before any runtime XR bootstrap.";
CODE_AUDITS["pattern_ror2_dynamic_openxr_manager_profiles"] = "VERIFIED FROM SOURCE: RoR2VRMod/VRMod.cs (`InitVR`, `SetupControllerProfiles`, `ShutdownXR`). Transfer: a BepInEx retrofit can assemble Unity XR configuration completely at runtime, but if it bypasses XR Management’s normal lifecycle it must also own teardown.";
CODE_AUDITS["pattern_ror2_shadow_camera_projection_oracle"] = "VERIFIED FROM SOURCE: RoR2VRMod/Camera/StereoProjectionFix.cs; CameraFixes.AddStereoProjectionFix. Transfer: use an untouched XR camera as a projection source of truth instead of reverse-engineering or continuously fighting a flat game’s FOV/projection writers.";
CODE_AUDITS["pattern_ror2_camera_wrapper_native_state_hmd"] = "VERIFIED FROM SOURCE: RoR2VRMod/Camera/VRCameraWrapper.cs; CameraFixes.cs. Transfer: separate the target game’s camera-state machine from the tracked local eye transform rather than deleting all native camera logic.";
CODE_AUDITS["pattern_ror2_device_origin_absolute_yaw_recenter"] = "VERIFIED FROM SOURCE: RoR2VRMod/VRMod.cs; Camera/RecenterController.cs; VRCameraWrapper.cs. Transfer: treat tracking-origin policy and game-world yaw rebasing as explicit ownership; absolute rebasing avoids cumulative recenter drift.";
CODE_AUDITS["pattern_ror2_xrinput_rewired_semantic_bridge"] = "VERIFIED FROM SOURCE: RoR2VRMod/Inputs/Controllers.cs; Inputs/XRI/InputHelpers.cs; Inputs/RewiredAddons.cs. Transfer: add a synthetic controller at the target game’s existing input abstraction rather than bypassing its rebinding/action consumers.";
CODE_AUDITS["pattern_ror2_survivor_skill_binding_roles"] = "VERIFIED FROM SOURCE: RoR2VRMod/Inputs/Controllers.cs; VRAPI/MotionControls.cs; MotionControls.cs. Transfer: when a game has heterogeneous characters/loadouts, bind physical hand roles to semantic skill slots per archetype rather than duplicating controller maps.";
CODE_AUDITS["pattern_ror2_controller_relative_move_native_turn"] = "VERIFIED FROM SOURCE: RoR2VRMod/Inputs/Controllers.cs (`ControllerMovementDirection`); Camera/CameraFixes.cs (`GetVRLookInput`); Settings/ModConfig.cs. Transfer: preserve the game’s locomotion solver and swap only the input reference frame / turn command semantics.";
CODE_AUDITS["pattern_ror2_tracked_hand_pair_pose_correction"] = "VERIFIED FROM SOURCE: RoR2VRMod/MotionControls/MotionControls.cs (`SetupHands`); HandController.cs. Transfer: keep tracked pose root, semantic handedness and visual/weapon calibration as separate layers.";
CODE_AUDITS["pattern_ror2_runtime_bindpose_hand_extraction"] = "VERIFIED FROM SOURCE: RoR2VRMod/MotionControls/RuntimeHands.cs; Settings/ModConfig.cs. SOURCE BOUNDARY: this outputs rigid controller-local geometry; the optional forearm is documented as rigid and does not bend at the elbow, so it is not Body/Arm IK.";
CODE_AUDITS["pattern_ror2_childlocator_semantic_muzzle_graft"] = "VERIFIED FROM SOURCE: RoR2VRMod/MotionControls/MotionControls.cs (`SetHandPair`); HandComponents/Muzzle.cs; Hand.cs. Transfer: find the engine’s shared named attachment locator and graft tracked transforms there before resorting to per-weapon patches.";
CODE_AUDITS["pattern_ror2_shared_aimray_ability_adapters"] = "VERIFIED FROM SOURCE: RoR2VRMod/MotionControls/MotionControlledAbilities.cs; HandController.cs; MotionControls.cs. Transfer: centralize VR aim first; make character-specific patches describe hand ownership, not duplicate projectile/damage code.";
CODE_AUDITS["pattern_ror2_twohand_angular_snap_stabilizer"] = "VERIFIED FROM SOURCE: RoR2VRMod/MotionControls/HandComponents/TwoHandedMainHand.cs and TwoHandedGuidingHand.cs; MotionControls.cs. Transfer: a lightweight two-hand retrofit can use support-hand angular intent without requiring weapon physics or a full two-point rigid-body solver.";
CODE_AUDITS["pattern_ror2_tracking_space_melee_skill_intent"] = "VERIFIED FROM SOURCE: RoR2VRMod/MotionControls/HandComponents/MeleeSkill.cs; MotionControlledAbilities.cs input-state hook; MotionControls.cs survivor setup. SOURCE BOUNDARY: this is gesture-driven native melee, not swept controller/weapon contact.";
CODE_AUDITS["pattern_ror2_weapon_mounted_pip_scope"] = "VERIFIED FROM SOURCE: RoR2VRMod/MotionControls/HandComponents/SniperScopeController.cs; MotionControlledAbilities Railgunner scope hooks. Transfer: a physical weapon optic can be a separate mono render product while the primary HMD remains normal stereo.";
CODE_AUDITS["pattern_ror2_native_gamepad_vibration_to_xr"] = "VERIFIED FROM SOURCE: RoR2VRMod/Inputs/Controllers.cs (`VRHaptics`). Transfer: first look for the target game’s consolidated gamepad-rumble signal; it is often a better VR haptic semantic source than patching effects individually.";
CODE_AUDITS["pattern_ror2_worldspace_canvas_gamepad_ui"] = "VERIFIED FROM SOURCE: RoR2VRMod/UI/UIFixes.cs; Inputs/Controllers.cs; ControllerGlyphs.cs; LobbyNavigation.cs. Transfer: if pointer interaction is not necessary, spatializing the UI and preserving its mature gamepad navigation can be far less fragile than inventing a laser event system.";
CODE_AUDITS["pattern_ror2_ui_pointer_fail_safe_disable"] = "VERIFIED FROM SOURCE: RoR2VRMod/UI/UIPointer.cs; MotionControls/HandController.cs; Inputs/ControllerGlyphs.cs. Transfer: fail closed at the interaction surface—never let a partially working VR pointer continuously overwrite a reliable legacy UI input path.";
CODE_AUDITS["pattern_ror2_wrist_hud_native_widget_reparent"] = "VERIFIED FROM SOURCE: RoR2VRMod/MotionControls/HandHUD.cs; MotionControls.cs; UI/UIFixes.cs. Transfer: reparent existing reactive widgets instead of building a second VR HUD state model.";
CODE_AUDITS["pattern_ror2_cutscene_worldspace_presentation"] = "VERIFIED FROM SOURCE: RoR2VRMod/Misc/CutsceneFixes.cs. Transfer: treat cutscene camera, screen UI and comfort/presentation as their own state rather than applying ordinary gameplay HMD rules blindly.";
CODE_AUDITS["pattern_ror2_state_driven_comfort_vignette"] = "VERIFIED FROM SOURCE: RoR2VRMod/Camera/ConfortVignette.cs; VRAPI/VR.cs. Transfer: in an ability/state-machine game, semantic mobility states can provide more reliable comfort triggers than noisy movement heuristics.";
CODE_AUDITS["pattern_ror2_native_networked_hmd_viewangles"] = "VERIFIED FROM SOURCE: RoR2VRMod/Camera/CameraFixes.cs (`ChangeNetworkAngles`); MotionControlledAbilities local-body checks; README vanilla multiplayer compatibility. Transfer: if remote embodiment is unnecessary, reuse the smallest existing network semantic needed for gameplay/animation rather than introducing a VR pose protocol.";
CODE_AUDITS["pattern_ror2_optional_suit_haptics_chest_inference"] = "VERIFIED FROM SOURCE: RoR2VRMod/Haptics/HapticsManager.cs; BHapticsController.cs; ShockwaveController.cs. README boundary: these inherited suit backends are retained in 1.0.3 but described as not fully revalidated by the rebuild maintainer.";
CODE_AUDITS["pattern_ror2_vrapi_extension_surface"] = "VERIFIED FROM SOURCE: VRAPI/VRAPI.cs, VRAPI/VR.cs, VRAPI/MotionControls.cs; RoR2VRMod MotionControls/CameraFixes public extension methods. Transfer: expose semantic pose/aim/handedness/presentation hooks, not XR loader/session objects, so third-party gameplay mods never become runtime owners.";


// Restore pre-existing audit records unchanged after RoR2 formatting edits.
CODE_AUDITS["seed_valheimvr_case"] = "VERIFIED FROM SUPPLIED VHVR 0.9.21 SOURCE. ARCHITECTURE: `ValheimVRMod` is a BepInEx `BaseUnityPlugin`; `VRManager` loads Unity XR/OpenVR settings from AssetBundle, pre-initializes SteamVR actions, starts XR subsystems and SteamVR, then Harmony patches map tracked state into Valheim. RENDERING: `VRPlayer.enableVrCamera` copies the native camera into a tracked XR camera and splits hands/skybox/world-space UI/mirror layers. `VRTaaComponent` maintains per-eye temporal history/jitter and `FogComponentPatches` uses the active eye frustum. Unity XR owns low-level compositor frame timing. CAMERA/SPACES: `EyeRotationPatch` separates HMD eye rotation from body/player yaw; roomscale movement counter-translates the rig while native body/Rigidbody displacement is applied elsewhere. BODY IK: FinalIK VRIK has head, pelvis, arm and local leg targets; hip and foot trackers can be auto-detected/calibrated and leg weights are context gated. Remote VRIK intentionally removes legs. WEAPONS/MELEE: mesh-derived weapon geometry and equip-specific two-hand providers position tracked weapons. Weapon/fist/foot colliders use camera-rig-relative motion for physical intent/contact, then start native `Attack`; block/parry logic feeds native `Humanoid.BlockAttack`. PROJECTILES: one `Attack.GetProjectileSpawnPoint` Harmony seam supplies physical bow/crossbow/magic/fishing/throwable origins/aim. Bow draw is physical; crossbow cock/bolt placement drives native reload state; throwing combines linear+angular controller velocity. INTERACTION/UI: independent hand rays call native `Player.Interact`; building manager authors spatial placement while preserving native validation; `VRGUI` reuses Unity GUI through RenderTexture + overlay/quad and fake mouse; `VRHud` redistributes native widgets to wrist/camera/build canvases. LOCOMOTION: roomscale body movement, physical sneak, hand/foot gestured movement, swim, jump/dodge and foot-tracker walk/slide feed native motion semantics. VEHICLES: `ShipSteering` and `Reining` convert physical hand gestures to native ship/saddle controls. MULTIPLAYER: `VRPlayerSync` writes head/hands/pelvis/velocity/fingers/bow/handedness/two-hand state to ZDO `vr_data`; remote transforms interpolate and drive VRIK, but remote legs are absent and transmitted velocity is not used for extrapolation. HAPTICS: controller `hapticAction.Execute` and separate bHaptics event patches coexist. SOURCE-BOUNDARIES: no explicit OpenXR predicted-time frame owner in this snapshot; no remote tracked-leg FBT; generic manual-magazine reload is not demonstrated beyond the crossbow physical reload workflow.";
CODE_AUDITS["seed_vicecity_quest_case"] = "VERIFIED FROM SUPPLIED SOURCE (Vice City Quest v0.5.5). ARCHITECTURE: tools/assemble.sh reconstructs a pinned reVC checkout through an ordered patch stack, overlay, and bundled librw; XR/session code, renderer semantics, pose-space authority, weapons, driving and reVC gameplay patches are distinct layers. FRAME TIMING/RENDERING: xr_vulkan_session.cpp owns xrWaitFrame/xrBeginFrame/xrLocateViews/xrEndFrame and uses one predictedDisplayTime for eye/controller pose sampling; both eyes are array layers of one Vulkan multiview OpenXR swapchain, with per-eye asymmetric XrFovf projections and scope FOV scaling. GameRenderCommand gives legacy draws semantic roles before the RenderWare/Vulkan backend. CAMERA/SPACES: librw centralizes live HMD pose, latched tracking origin, character/vehicle anchor, eye poses and bidirectional play↔world transforms. Controllers are transformed relative to the latched head so physical leaning is not applied twice. Full vehicle-basis anchoring preserves pitch/roll. Large tracking-origin jumps relatch. VrUpdateFirstPersonAnchor runs before input and post-physics before render; visual hand rebasing is separated from gameplay interaction. CULLING: stereo sphere/box tests use the exact render play space and union of asymmetric eye clip planes, with bounded safety margin and fail-open invalid-state behavior. INPUT/LOCOMOTION: OpenXR grip/aim/actions map into native CControllerState; head-relative movement rotates by local latched HMD yaw only; snap/smooth/head-turn modes feed native camera/player heading. HANDS: VRHandModel is a four-baked-pose per-vertex morph (open/grip/trigger/both), not skeletal finger tracking or body IK. WEAPONS: body-yaw holster frame, calibrated per-hand weapon/support poses, physical grab/return/drop/catch/hand-transfer state, rigid fixed-pivot two-hand solve, calibrated muzzle aim, physical scope gating and centre-ray convergence. MANUAL RELOAD: Colt45/TEC9/Uzi/Silenced Ingram use a magazine gesture state machine (leave body socket, delay, enter magwell) that gates native CWeapon::Reload and requires post-insert trigger release. THROWABLES: tracked source/direction + release semantics, obstruction-safe source trace, constant launch speed, native CWeapon::Fire/projectile/fuse/ammo, trajectory preview. MELEE: weapon root/tip motion is measured in camera-relative tracking space so locomotion/snap turns cannot synthesize strike velocity; fast inception plus a short continuation window publishes swept segments; real contact routes into native CWeapon::FireMelee. UI: native HUD widgets are rendered to private wrist textures then hung on tracked wrist/vehicle anchors; separate Im2D transform preserves flat screen coordinates on a headset plane. DRIVING: car wheel grips solve two-hand chord or one-hand unwrapped spoke with ownership rebasing, discontinuity rejection and slip-at-lock; visible DFF wheel rotates about calibrated real pivot; horn requires an approach gesture. Bike steering has a tracking-space frozen reference, one/two-hand rebasing, throttle twist and both-hand lean gestures. CINEMATICS: upright latched theater quad or stereo director/actor-head anchor. BOUNDARIES/NEGATIVES: no full-body IK; no OpenXR skeletal fingers; throwable speed is not hand velocity; manual reload is limited to an explicit subset; TAA/SGSR/runtime-only foveation are disabled in the current Quest configuration. REUSABLE PATTERNS: reproducible patch-stack source port; predicted-time multiview; semantic draw boundary; one bidirectional pose authority; union-of-eyes culling; cheap analog morph hands; native input bridge; explicit physical ownership/holsters; fixed-pivot two-hand solve; physical optic convergence; physical-reload intent around native ammo; obstruction-safe native throw; tracking-space swept melee; authority/render transform split; stateful physical wheel/bike controls; render-to-texture wrist UI; local-yaw locomotion; pre-input/post-physics anchor ownership; cutscene presentation state machine.";
CODE_AUDITS["seed_simpsons_hnr_case"] = "FULL SOURCE AUDIT (2026-09-06; supplied `code` tree). ARCHITECTURE: this is a native source-port conversion, not a camera-only wrapper. `vr/openxrmanager.cpp/.h` owns XR session/actions/reference space/eye and hand pose normalization, stereo targets, HUD carriers and physical vehicle-control state; `render/RenderManager/RenderManager.cpp` owns when the game renders one world pass vs two eye passes; native camera/gameplay code consumes the VR service through narrow functions. FRAME TIMING: `BeginFrame` does `SyncInputActions` before `xrWaitFrame`, then waits/begins the XR frame and locates both `XrView`s plus hand action spaces at `predictedDisplayTime`. `EndFrame` submits the same cached poses/FOVs and two array layers at that time. Quest reference-space-change events cause yaw-only origin rebasing after a short settle window, preserving standing height on crouched recenter and invalidating spatial 2D anchors. RENDERING: `CreateSwapchains` creates a single two-layer stereo swapchain. GLES uses `GL_OVR_multiview2` only if extension and multiview Pure3D shaders are ready; otherwise `BeginEye` renders each layer separately. Vulkan uses an OpenXR-created compatible device (`XR_KHR_vulkan_enable2`), true multiview and optional Meta fragment-density/foveation. `PrepareMultiviewCamera` builds separate asymmetric eye projections/view adjustments but uses the tracked HMD midpoint for shared traversal/culling. Render scheduling intentionally broadcasts only compatible world work; Scrooby GUI/FMVs get conventional per-eye passes. Persistent 24-bit depth, a distinct single-layer FBO, careful acquire/wait/release pairing, safe deferred swapchain recreation and asynchronous telemetry are explicit stability/performance work. The source disables the existing mono-depth GTAO in VR rather than presenting it as stereo-correct. COORDINATES/CAMERA: `RelativePose` removes app recenter state; `PoseToGame` performs the one RH OpenXR -> SHAR conversion, with 1 unit treated as 1 metre. `GetEyeCamera` composes local eye then base game camera. `FirstPersonCam` owns artificial yaw separately from HMD yaw, consumes horizontal roomscale movement into native character position while moving the tracking origin to avoid double application, replaces authored eye height with physical STAGE height, and applies child height scaling for Bart/Lisa. Vehicle camera anchors on `Vehicle::GetDriverLocation` + eye height, recenters at entry, keeps HMD motion local, and optionally bounds/filters chassis pitch/roll. Generic third-person collision push-out is bypassed for the tracked first-person eye. INPUT: one OpenXR `gameplay` set contains semantic axes/buttons, analog triggers/grips, hand pose and haptics. `SyncInputActions` deadzones and maps them into existing `UserController` virtual names. VR-specific arbitration occurs here (driving look suppression, yoke gas/brake, grip ownership, menu single-axis lock, physical interaction pulse). HANDS: `RenderControllerHands` uses character-specific static hand meshes at tracked grip poses, with context-based visibility and physical wheel/yoke attachment. No full-body/arm IK or skeletal finger retargeting is demonstrated. PHYSICAL PUSH: `UpdatePhysicalPushInteract` recognizes deliberate hand velocity/direction but first requires current `ButtonHandler::AllowPhysicalInteract`; unsafe car/phone/purchase/talk semantics are excluded. Success injects the same native DoAction edge. COLLECTIBLES: `CollectibleObjective` and `ActionButton::Collectible` convert body overlap to pending eligibility; grip + tracked hand proximity confirms collection; then original mission/reward/event code finalizes it. MELEE: normal flat attack mapping is removed in VR. `Character::PreSimUpdate` measures hand speed from controller-local tracking deltas, not world motion, then world-sweeps an extended hand segment. `VrPunch` uses native dynamic intersections and original kick forces/events/breakables; one swing is consumed even on miss until the hand slows. VEHICLES: `UpdateVrSteeringWheel` is a complete physical solver. Round-wheel grip uses spatial hysteresis and fixed snapshot/angle-unwrapping; tracking loss resnapshots; one/two hand targets drive authoritative wheel angle; trim/centering/output shaping feed `HumanVehicleController::GetSteering`. A separately smoothed visual angle drives wheel mesh and glued hand presentation. An in-VR two-hand calibration mode authoritatively sets centre/radius/yaw/pitch/yoke anchor per vehicle and persists it. Honor Roller has its own T-yoke: differential vertical hand movement steers; shared fore/aft movement becomes native gas/brake triggers; full edges haptically signal. Wheel-hub proximity can invoke native horn. UI: authored radar/mission/gameplay HUD pieces are captured/cropped and drawn as per-eye physical planes with semantic wrist, dashboard/wheel and centre-camera anchors. Legacy screen GUI can use eye/FOV-derived convergence correction. Movies and front-end/pause/loading screens use latched yaw-only planes and re-anchor after recenter; Vulkan iris fade can be a composition-layer color scale/bias. RENDER-SIDE EFFECTS: legacy particle emission called from draw paths is gated to one canonical normal eye/pass so stereo/CSM replay cannot multiply simulation; cockpit draw temporarily suppresses intrusive sirens, driver geometry, flapping hood and self-light cost while restoring shared state afterward. REUSABLE MODEL: explicit XR frame timeline -> one pose/recenter conversion -> stereo renderer with multiview compatibility phases -> native camera/player/vehicle anchors -> semantic input bridge -> tracked intent detectors -> original gameplay authority -> stereo-safe spatial UI. SOURCE LIMITS: no full-body IK, skeletal finger tracking, physical weapon/reload/throw system or remote XR-pose networking; roomscale SetPosition path does not show dedicated collision reconciliation; physical punch is a dynamic-object segment test and disabled indoors; Oculus Touch bindings are explicitly authored rather than a data-driven multi-profile layer.";
CODE_AUDITS["seed_mousepi_vr_case"] = "Binary/asset audit (no public game-plugin source): MousePI_VR.dll is a BepInEx BaseUnityPlugin (MousePIPlugin/GamePlugin, net472, Harmony + Fody) built from a path labeled Simple CustomOpenXR for bepinex. OpenXR is a separate MinimalOpenXR-style OpenXR.dll (InitializeOpenXR/FinalizeOpenXR, D3D11/D3D12/Vulkan/OpenGL session bindings, swapchain acquire, interaction profiles for Touch/Index/simple_controller). Camera seams: VRCamFix.UpdatePosition, VR_Rig_LeftEye/RightEye, StereoTargetEyeMask, ScreenSpaceCameraPositionLeftHand/RightHand, OnBeginCameraRendering, SetupFullscreenEffectsCamera for URP fullscreen passes. UI: InitCanvasFixLeft/Right, PatchCanvas, InventoryControllerToggleCanvas, DivingSuitUIControllerSetCanvasVisibility; AssetBundles TwoPassAlphaMask and UIWithFakeAlpha shipped for Built-in, URP, and HDRP so transparent HUD survives stereo. Hands: AssetBundles hands / hands_animated (Unity 6000 manifests) with left_hand and right_hand prefabs as VR_LeftHand/VR_RightHand. Gameplay Harmony targets: PlayerWeaponController spread/reload/shoot VFX, KickForwardPatch and kick trigger reposition, PlayerTailRenderer.RefreshTail, death and flashlight handlers. Input bridge: VRInputManagerCustomOpenXR plus Nefarius.ViGEm.Client Xbox 360 virtual pads (ViGemVRControllers). Haptics: ForceTubeVR_API_x64 Shot/Kick/Rumble channels (InitializeProTube) and Bhaptics.Tact TactsuitVR PlaybackHaptics/TriggerHapticFeedback. Deep pass: Treat this as a BepInEx + custom-OpenXR pattern for Unity FPS titles where XR Plugin Management alone is not enough. Preserve the dual input path (OpenXR poses for hands/aim, ViGEm for gamepad-only systems), pipeline-specific UI shaders, and weapon-hook-driven dual haptics. Do not invent IK solvers or full physical weapon collision — those are not evidenced in the shipped strings/assets. Discord-only distribution means update risk is high after game patches.";
CODE_AUDITS["seed_cyberpunk_vrik_case"] = "Source-audit (2026-09-06), VERIFIED FROM THE USER-SUPPLIED current cyberpunk-vr-port source snapshot and cross-checked against the current public project README. The supplied tree contains 109 C++ source files, 52 project headers, 97 CET Lua files, 16 redscript files, 47 CyberpunkVR_TwoHandGrip_*.ini captures/configs, and 13 weapon-specific reload modules plus their index. This audit supersedes the registry's older split Stereo/Hands and AER pair-lock description.\n\nARCHITECTURE / BOOTSTRAP: CMakeLists.txt defines one C++20 RED4ext shared library, output CyberpunkVR_Stereo. It GLOB_RECURSEs all src/*.cpp + include/*.hpp, explicitly because the former CyberpunkVR_Hands code is now part of the same binary. Dependencies: Khronos OpenXR-SDK release-1.0.34, ImGui 1.90.9, MinHook, RED4ext SDK, d3d12, dxgi and d3dcompiler. Current source comments document two migrations: the old dxgi.dll proxy is gone, and the old CyberpunkVR_Hands.dll is gone. Main.cpp Load order is intentional: InitRuntimePaths -> CyberpunkVR_RegisterHandsNatives (before the registration window closes) -> ApplyFirstLaunchGameSettings -> CyberpunkVRPort_InitStereo (before the game's D3D12CreateDevice so device/queue/descriptor changes can be captured) -> CyberpunkVRPort_PluginBootstrap (before game swapchain creation) -> delayed WorkerThread pattern-scan/game-hook pass. Unload drops overlay device/queue references and shuts down OpenXR before D3D12 teardown. This is a single-process native plugin with CET/redscript gameplay extensions, not two competing native plugins and not a DXGI forwarding proxy.\n\nHOOK ORGANIZATION / REVERSE ENGINEERING: Hooks/Registry.cpp implements static hook registration with PreDevice, Boot and PostStereo stages plus explicit order; hooks are collected/sorted deterministically instead of trusting link order. Disabled is logged separately from failure; every attempted hook logs ok/FAILED and failure means its feature is absent. Stereo/DetourRegistry.cpp keeps a second deterministic registry for engine detours. Utils/AobScanner.hpp provides process-module byte/mask scanning over committed readable/executable pages. Do not generalize that into 'the mod is signature based': Stereo/EngineRvas.hpp contains a large centralized table of Cyberpunk2077.exe RVAs explicitly verified against build 2.31, and several callsite patches validate expected instruction bytes before writing. The repository's docs contain the investigation trail for camera write chains, render-to-texture creation, frame-graph builders/node executors, D3D12 replay/in-place replay dead ends, VRCAM discovery, per-view render state, PhysicalRay weapon hits and VRIK frame-phase measurements. Reusable rule: keep known-build RVAs centralized, document how each was proven, validate bytes/invariants at the patch edge, log every install, and fail closed.\n\nOPENXR INITIALIZATION / RUNTIME SELECTION: Runtimes/OpenXRManager.cpp calls ConfigurePreferredOpenXRRuntime before xrCreateInstance. XR_KHR_D3D12_enable is required. The code enumerates extensions and enables XR_KHR_composition_layer_depth when available. It creates a PRIMARY_STEREO system/view configuration, reads recommended view dimensions, obtains D3D12 graphics requirements, creates an OpenXR session from the captured game ID3D12Device + ID3D12CommandQueue, then creates LOCAL and VIEW reference spaces. SteamVR selection is an OpenXR runtime choice: the code can load openvr_api.dll only to call VR_GetRuntimePath/find steamxr_win64.json and sets process XR_RUNTIME_JSON before OpenXR initialization. The runtime identity is read with xrGetInstanceProperties and classified (SteamVR/Virtual Desktop etc.). There is no separate OpenVR compositor submission backend in the current implementation.\n\nOPENXR ACTIONS / CONTROLLER INPUT: OpenXRManager creates a subactioned grip/palm pose action (m_handPoseAction), a distinct aim pose action (m_handAimPoseAction), thumbstick Vector2, trigger float, grip float, stick-click bool, primary/secondary button bool and menu bool. It suggests bindings for /interaction_profiles/oculus/touch_controller, /valve/index_controller, /htc/vive_controller, /microsoft/motion_controller and /khr/simple_controller. Grip pose is the hand/VRIK source; aim pose is available for pointing and hand-relative locomotion because a controller's aim -Z is more stable for that semantic than grip orientation. The frame loop xrSyncActions/reads action state into VRControllerState. Hooks/XInput.cpp merges that semantic controller state into gamepad 0 during gameplay but deliberately leaves menus/braindances on the game's raw pad bindings. The gameplay bridge handles fixed movement magnitude, sprint detent, dash, crouch, snap/smooth turn, scanner gesture, D-pad/quickhack paging and trigger/grip arbitration. Pose and gameplay actions can be disabled separately (pose-only fallback). SOURCE CHECK: no XR_EXT_hand_tracking symbol/extension and no XR_ACTION_TYPE_VIBRATION_OUTPUT/xrApplyHapticFeedback were found in the supplied source, so this is controller-driven motion control rather than optical skeletal hand tracking, and OpenXR haptics are UNKNOWN/absent from this snapshot.\n\nFRAME TIMING / DISPLAY-TIME OWNERSHIP: Runtimes/OpenXRFrameLoop.cpp owns the XR cycle. Its runtime-paced mode performs xrWaitFrame, xrBeginFrame, chooses one locateTime, uses that time for xrLocateViews and controller/hand locates, captures/copies the completed game images into OpenXR swapchains, then xrEndFrame. SetFrameAimTime publishes the chosen target so camera-side LocateHeadPoseAt uses the same instant. The code contains optional display-time fitting/pipeline-depth instrumentation, but the current default PoseAimScale is intended to add no private lead beyond the runtime target; OpenXRManager explicitly marks the old xr_motion_predict_ms custom extrapolation REMOVED because runtime predicted display time + compositor reprojection are already the prediction stages. This is a critical correction to the older registry entry.\n\nPAIR LOCK REMOVAL / SAME-FRAME NATIVE STEREO: OpenXRManager.cpp explicitly says UpdatePairLock/GetPairLockedHeadPose were removed with AER. The old lock was meaningful when one engine camera alternated eyes across two engine frames. The current architecture has two cameras in one engine frame, and AnimPose caches/replays one skeleton solve for that animation epoch. FlushHandsToShared therefore publishes live hands/head rather than freezing a second independently clocked snapshot. The source also removes the old pair-lock overlay control (legacy config key can be round-tripped). Reusable rule: do not cargo-cult 'freeze one pose for both eyes'; first determine whether the eyes are separate game frames or two views of the same engine frame.\n\nTHREADED SUBMISSION / LOW GAME FPS: OpenXRFrameLoop supports inline or dedicated submit-thread ownership. Source comments/logic specifically explain that SteamVR's xrWaitFrame/compositor pacing can stall the game's Present thread if run inline, while other runtimes can use inline. When the dedicated thread owns XR pacing, the game Present returns instead of blocking on xrWaitFrame. The XR loop can re-submit the most recent completed game snapshot with its OWN render pose when no new game frame exists, maintaining compositor cadence rather than skipping XR frames. Producer/consumer work uses bounded waits and a small allocator/resource pool so submit never blindly shares a mutable texture with the game's next capture.\n\nPOSE-TO-IMAGE COHERENCE: StoreRenderEyePose records the camera pose that was actually used by an engine sequence and queues it by sequence ID. Captured MAIN/VRCAM images have serials; the submit path finds the image slot for the requested serial and rejects mismatched pairs. This fixes a subtle failure where a CPU serial could still match while the GPU had already overwritten the same shared texture with the next frame. OpenXR submission expects raw LOCAL-space poses while camera/game code uses a recentered base-relative pose, so StoreRenderEyePose composes the base pose back in before the projection layer is submitted; otherwise the compositor's timewarp delta would include the recenter transform and warp incorrectly. Reusable rule: bind image, render pose, eye identity and serial as one transaction, and make resource ownership agree with CPU bookkeeping.\n\nNATIVE STEREO / VRCAM: Stereo/SyncStereo.cpp drives the right eye through an authored entRenderToTextureCameraComponent. Selection data lives in CET's CyberpunkVRPort_Stereo/vrcam.json and generated archive assets; VRCAM is identified by the selected virtualCameraName CName hash from the view context. MAIN is not 'anything not VRCAM': structural MAIN-only nodes/view context are used, and unknown views are passed through. This prevents desktop window, reflection probes, braindance or other auxiliary views from being mutated as the left eye. The plugin also patches descriptor-heap capacity because the extra engine view consumes descriptors the flat game never budgeted.\n\nFRAME GRAPH / PER-VIEW STATE: Stereo/FrameGraph.cpp and the Stereo/* modules treat the second eye as a real engine view whose graph must be reconciled, not copied wholesale. The source observes/diffs view feature bits/upscaler groups, mirrors/forces required flags from MAIN and hooks the per-frame flag writer because REDengine regenerates view flags each frame. There are dedicated modules for NodeDispatch, ViewReuse, CullVisibility, Grading, VisionLayer, Hud, Dlss, Capture and profiling. Source comments document why indiscriminate cloning/re-run is wrong: sun-cascade atlases, foliage/SpeedTree wind, reflection march/shader clock and other resources are shared/once-per-frame structures, while environment override, composition/scanner tint, culling and view-dependent depth need to be valid for VRCAM itself. The implementation either lends/reuses shared results or reruns per-view work based on live evidence. Final color is picked up from the engine's node epilogue/acquire barrier, avoiding a mid-chain resource guess.\n\nDEPTH / CULLING / VISIBILITY: VRCAM keeps its own depth range; copying MAIN's near/depth setup was observed to empty clustered-light grids in interiors. Cull/visibility modules track the actual second-view candidates/materialization rather than assuming MAIN visibility is sufficient. The camera/view-context FOV scalars can be synchronized for culling, but source comments distinguish culling state from the actual render camera's projection and warn that scripted cameras can require different handling. This distinction is useful in any deferred renderer where visibility/light clustering reads a different view structure than the shader projection.\n\nDLSS / STREAMLINE / TEMPORAL STATE: Stereo/Dlss.cpp + Hooks/Ngx.cpp/NGX resolution hooks create/route a separate Streamline/DLSS viewport/context for VRCAM and force compatible feature-group selection when MAIN uses DLSS. Reusing one MAIN viewport for both eyes would make temporal/upscaler history cross-contaminate. The port also has dedicated shader constants and per-view dimensions. The broader lesson is that true second-view stereo must account for temporal history ownership, not just duplicate camera matrices.\n\nOPENXR COLOR/DEPTH SWAPCHAINS: Runtimes/OpenXRCapture.cpp creates per-eye D3D12 color swapchains with XR_SWAPCHAIN_USAGE_COLOR_ATTACHMENT_BIT | XR_SWAPCHAIN_USAGE_TRANSFER_DST_BIT, enumerates runtime-supported formats and chooses a compatible typed format. Optional depth submission creates OpenXR depth swapchains when XR_KHR_composition_layer_depth is supported; the capture path can add depth later without tearing down working color swapchains. Source comments move depth copies onto the game depth-writer queue/ordered path where necessary rather than forcing unsafe cross-queue waits. Mono/menu fallback copies the backbuffer to both eyes when the second view has no fresh usable frame, preventing a stale VRCAM image from surviving into loading/menu states.\n\nHUD / UI / OVERLAY: Cyberpunk's engine HUD is composited into the second eye with the same HUD shader logic; default placement is same pixel in both eyes (zero disparity) with optional finite-distance placement. F10 ImGui is rendered into both eye textures. Overlay code avoids draining/stalling the entire game queue: its allocator/upload resources are fenced directly. HUDitor now owns individual widget placement; the port's old shared-root HUD mover was removed, while the native plugin still performs the part an external HUD editor cannot: duplicating the engine HUD composite into the second eye. CET/redscript modules fit 16:9 interfaces to the square-ish VR view (phone, vehicle/radio lists, subtitles, dialogue, tutorial/welcome/loot), head-lock the world map, and handle braindance/scanner/device-camera presentation. A wrist-HUD module and F10 settings overlay are additional examples of changing spatial presentation while leaving underlying game state intact.\n\nCAMERA / GAME STATES: Hooks/LocateCamera.cpp, PatchCamera.cpp, FinalCamera.cpp, CameraPitch/Fov/BodyYaw files and Camera/CameraLink separate the engine/body heading from HMD view. Normal gameplay can suppress mouse Y so pitch belongs to the HMD while yaw/body policy remains independent. Physical body rotation optionally writes through the engine heading channel so mesh/collision/aim/movement turn with the user without feeding that yaw back into the headset view. Braindance uses one base + one head sample for both eyes. Surveillance/device/AV turret camera takeover keeps the native camera's aim/base, layers HMD movement on top and identifies special cameras through entity/buffer paths when they never reach the ordinary classifier. Cutscene sceneTier is obtained through RTTI; VRIK and certain view interventions suspend at configured cinematic tiers. Camera/pose snapshots use seqlocks/epochs to avoid combining camera(N-1) with entity(N) or head/hand samples from different phases.\n\nCOORDINATE SPACES: The implementation distinguishes OpenXR LOCAL/view/action spaces, recentered base-relative tracking, engine world/entity space, avatar/model space, camera/view space, controller grip/aim space, wrist/hand targets, weapon rig space, muzzle world space and OpenXR submission space. CharacterRig maps OpenXR position axes into model coordinates (representative helper mapping {x,-z,y}) and applies body/camera rotation explicitly rather than copying an XrPosef into a REDengine transform. VRIK view targets can be built from a latched view packet/body heading so hand positions remain anchored to the same camera/entity frame. The solve publishes solved palms/body bones/world view for CET/redscript consumers so those modules can reason in the right space instead of re-deriving controller->world transforms independently.\n\nVRIK INSTALL / RIG IDENTIFICATION: Hooks/AnimPose.cpp detours the engine's pose-apply function when script/natives arm it. It is intentionally not a boot registry hook because the script controls when the pose path is installed. The hook runs for many skeletons, so steady-state identification is by named bones/remembered track buffers rather than expensive VirtualQuery/statistical heuristics on every call. VrikArming/PoseRig/native helpers resolve the player rig and known bone indices. The weapon skeleton is recognized separately and supplies moving weapon-part slots to reload/aim modules.\n\nVRIK UPDATE ORDER / ANIMATION EPOCH: The pose apply detour can execute several times within one animation batch. Source instrumentation measures microsecond same-batch gaps vs frame/batch gaps. The current path can clock freshSolve by the engine animation batch instead of Present; fresh VRIK writes are cached for the relevant body/limb bones and replayed on remaining pose passes of the same epoch. This fixes phase errors where a Present-based clock could replay the previous arms while the camera/world had advanced. Two-hand pose capture deliberately executes BEFORE VR writes because it needs one frame of the game's authored hold with VRIK off. Ownership transitions such as HeadAim invalidate the solve cache so a pose from the previous owner cannot be replayed after control changes.\n\nFULL BODY / SPINE / LEGS: VRIK_PlaceBodyUnderHMD captures foot positions, derives physical squat/drop from HMD/head height with deadzone/filter/clamp, recenters the foot pair under the head anchor, moves hips to maintain captured torso height, performs multiple CCD passes through spine/neck to reduce head residual, solves both legs back to planted feet with forward-knee constraints, rotates the head bone to the VR camera, and publishes hips/spine/chest/neck/head + leg bone positions for interaction modules. The hips yaw is not produced by this solver; body yaw is a separate engine heading policy. That separation avoids mixing 'where the body root faces' with 'how the avatar bends to meet the HMD'.\n\nARMS / SHOULDERS / ELBOWS / WRISTS: VRIK_ScaleArmBonesFromRest captures rest translations and scales upper/forearm segments toward measured user arm length with safety clamps; arm length calibration therefore changes skeleton segment lengths rather than only multiplying controller offset. CharacterRig contains shoulder/clavicle anchoring/protraction for far reaches, anatomical bend-plane construction from body axes, cross-body correction, near-extension handling, reach stretching instead of permanently clamping the hand short, elbow/pole smoothing and twist distribution. Hand target builders convert the tracked pose into avatar/model space and apply wrist calibration. VRIK_ApplyHandStop publishes the raw target but can clamp the solved target when collision/interaction says the wrist cannot pass farther; reload can also lock wrist orientation during a specific hand-owned action.\n\nHAND SMOOTHING: Current source explicitly moved smoothing away from the raw XR controller pose. OpenXRManager::FlushHandsToShared applies a UEVR-style delta-time-based follow filter to the pose the ARMS consume, leaving other semantics/aim less contaminated by arm smoothing. Effective hand lerp can vary by weapon class: melee can follow faster to avoid a trailing blade, sniper slower to damp aim noise, while wheel grab effectively disables smoothing because steering needs immediate tracked positions. Reusable rule: filter the attachment/consumer that needs visual stability, not the global XR pose every subsystem depends on.\n\nFINGERS / HAND COLLISION: Finger rotations are not optical hand-skeleton data. They come from authored/captured interaction poses: two-hand support capture stores per-finger rotations; reload poses own finger states while a magazine/slide is held; smoking records its own grips; wheel driving can hand the arm/fingers back to authored animation. CyberpunkVRPort_HandCollision contains body/weapon capsule construction and a one-way hand-stop path, but current init.lua declares COLL_ON=false. Source comments explain prior body capsules using world-dynamic/queryable behavior could launch/push the player/vehicle; the basketball module explicitly forces VR body capsules non-queryable for character-controller sweeps while preserving simulation contacts. Registry must distinguish implemented collision research from an enabled default feature.\n\nWEAPON MUZZLE / PHYSICALRAY PRODUCTION PATH: Hooks/WeaponAim.cpp and docs/cp2077-hitscan-physicalray-muzzle.md establish gameEffectObjectProvider_PhysicalRay::Execute as the live firearm damage-ray provider. The production hook patches two exact evaluator callsites rather than globally detouring every PhysicalRay user. WaPlayerOwnedWeapon reads effect-data fields including weaponItemRecord/playerOwnedWeapon; this filters to the local player's firearm. The origin wrapper calls the original evaluator first, checks the current published muzzle against the native ray origin (3 m sanity bound for stale/foreign data), marks the same thread's invocation and writes the ray origin to the live muzzle. It snapshots both muzzle forward and the original game camera/cone centre at that instant.\n\nSHOTGUN-SPREAD-PRESERVING DIRECTION: The forward wrapper calls the original evaluator and only acts if the paired origin wrapper accepted the same thread/invocation. It computes a quaternion/rotation from the game's original cone centre (camera forward) to the live muzzle/barrel forward and applies that rotation to the raw ray the game already generated. Therefore raw==coneCenter for a single bullet becomes exact barrel forward, while six shotgun pellet rays retain their relative offsets. This was specifically derived after direct 'write barrel vector into every ray' collapsed shotgun spread. PhysicalRay counters are Interlocked because pellet workers can run concurrently. Native attack/damage/hit systems remain untouched; only the local player's ray origin/basis changes.\n\nWEAPON VISUAL AIM / CROSSHAIR: Weapon pose, muzzle pose and projectile ray are kept separate. The plugin publishes the real muzzle/forward from the weapon rig/provider; CET can hide Cyberpunk's flat crosshair when VR weapon aim is enabled. A barrel-dot overlay/debug path can render aim in both eyes. Legacy/diagnostic target/crosshair hooks remain in source, but the PhysicalRay path is the current high-confidence combat redirect and should be taught as such.\n\nTWO-HAND GRIP: Anim/TwoHandGrip.cpp captures one native two-hand animation frame with VRIK disabled, storing support-wrist transform relative to the primary/right wrist plus finger rotations to CyberpunkVR_TwoHandGrip_<weapon>.ini. At startup it scans all configs into memory; the supplied tree contains 47 files, including aliases/reskins. Runtime computes the support point from the primary wrist every pose pass. Proximity can preview fingers; an unspent/fresh grip edge locks the support hand. Grip ownership is explicitly spent/swallowed when reload/carry owns the same hand so one physical squeeze cannot activate two interactions. Aim correction is based on the error between tracked support hand and the captured support point, with spring/time smoothing, deadzone, maximum correction and leverage weighting. Long rifle baselines receive stronger authority; short pistol baselines get much less because centimetres of tracking noise imply huge angular changes. Support-hand finger pose is written before more specific reload finger layers so the most specific current interaction wins.\n\nRECOIL: Anim/Recoil.cpp uses a damped spring. A shot adds velocity impulse rather than teleporting spring position, so rapid shots accumulate naturally. Integration uses fixed 2 ms substeps (bounded) to reduce frame-rate-dependent peak behavior. Per-weapon/class data determines kick; rise/back travel can be scaled separately, and two-hand leverage/support state reduces recoil. RecoilSample applies direct kick only to the weapon-owning hand; the support hand inherits through its constraint/weapon relation instead of receiving a duplicate impulse. This is intentionally hand/weapon recoil, not camera recoil.\n\nADS / SIGHTS: Anim/AdsEyeAlign.cpp keeps a stable authored ADS base/pivot while re-anchoring alignment toward the configured/dominant VR eye so fine head movement does not drag the gun arbitrarily. AdsMuzzleStabilizer handles non-VRIK authored ADS raise motion so the muzzle direction does not drift just because the vanilla animation raises the weapon. Shaders/sight_reflex_ps.hlsl builds a sight tangent/bitangent/optical-axis frame, computes eye-to-pixel angular offset and places reticle UV by angle rather than glass screen coordinates. Glass/world dimensions are carried explicitly from vertex stage instead of relying on ddx/ddy under DLSS, reducing temporal derivative jitter. The reticle therefore behaves like a collimated optic aligned to the bore.\n\nPHYSICAL RELOAD CORE: mods/cet/CyberpunkVRPort_Reload/reload/reload.lua is a generic geometry/state layer. The native pose hook provides weapon-rig bone/part transforms and functions to write local transforms; CET derives live magazine well, slide, grip and weapon axes and converts world/hand data into weapon-local coordinates. States cover magazine grab/extraction/carry/insertion/return/drop and slide/palm grab/release/locked behavior. Magazine travel follows the physical well/path rather than only elapsed animation time; slide displacement is a scalar projection of real hand motion onto the weapon's live slide axis. Reload finger poses, wrist lock/hand-stop and ownership flags keep visual hands attached to the part they are manipulating. redscript/manualReload prevents flat auto-reload behavior from racing the physical path; ammo/action/audio transitions occur at interaction thresholds. The supplied tree contains 13 weapon-specific modules + index, matching the current README's tuned list.\n\nSPECIALIZED REVOLVER: Malorian Overture is not forced through the box-magazine abstraction. Its module represents cylinder/crane/rotation/hammer, six live/spent cases and a speedloader. Cases can remain seated and then slide/eject along their chamber axes under gravity/friction/orientation before transitioning to dropped-body behavior. This is a strong abstraction lesson: generic framework + per-mechanism adapter, not one condition-heavy universal reload algorithm.\n\nMOTION MELEE CONTACT: mods/cet/CyberpunkVRPort_Weapon/init.lua uses MELEE_SWING_SPEED=2.5 m/s of weapon motion relative to the player as the current hit gate; whoosh has separate 3.0/1.0/4.2 m/s thresholds. CET only calls PlayerPuppet::VRMeleeBladeHit while the physical swing gate is satisfied. redscript/CyberpunkVRPort_Melee models the weapon as a blade segment from grip along blade direction, takes the weapon's native attack Range but caps physical segment length to ~1.25 m to avoid the flat game's lunge range hitting neighbours, queries NPC target parts, samples body centreline at shin/hip/chest/neck/head heights, chooses the closest body within hitRadius, and applies a 0.1 s cooldown only for repeat hits on the same EntityID. Different NPCs can still be hit on one fast slash.\n\nNATIVE MELEE AUTHORITY: VRMeleeBladeHit reads the weapon's own EffectiveDamagePerHit/DamagePerHit (strong swing can scale it), creates the weapon's own Attack_GameEffect from its record, configures the effect's position/forward/range/fxPackage/playerOwnedWeapon and calls StartAttack. That native stage restores Cyberpunk's reaction, blood/material VFX, impact sound/impulse and normal combat pipeline behavior. Because native damage calculation can zero script-initiated melee in the wrong combat state, a DamageSystem::CalculateDamageVariants wrap re-injects the queued VR melee damage for player-instigated melee attacks before armor/crit/markers/ApplyDamage. If Attack_GameEffect creation fails, a bare gameHitEvent/QueueHitEvent is a fallback. A holster-intent timestamp suppresses melee for ~1 s while physically reaching to holster, preventing a false swing from putting the weapon in a busy state and dropping the unequip. WeaponUp redscript also blocks idle auto-lower/auto-unequip logic that expects button attacks to reset timers; real VR swings bypass that input.\n\nHOLSTERS: CET Holster uses solved/published wrist-to-right-hip, left-hip and back-anchor distances. Visual-holster mode classifies outfit item names/slots to decide where melee/ranged props are visually carried; simple mode maps fixed slots. Zones have proximity/cooldown and cross-body thresholds. The module suspends while a cigarette occupies the weapon slot, and wheel proximity pre-claims the grip so grabbing the steering wheel cannot equip a weapon. This is a clean semantic-intent arbitration layer above raw grip input.\n\nSMOKING / PROP INTERACTION: CET feeds left trigger + left/right grip states into redscript VRSmokeTick. redscript owns proximity using actual world cig-tip/lighter/head positions rather than controller-centre distance, attaches vanilla cigarette/lighter props through game slots, uses captured finger poses, has a mouth anchor for hands-free hold and invokes the game's stock EffectSpawner FX/audio. This is a reusable 'native prop + tracked spatial state + existing effects' pattern, not a weapon-only subsystem.\n\nDRIVING: Anim/WheelGrab.cpp detects hand proximity/grip at the authored wheel position. When grabbed, that arm is handed back to the game's driving animation and rest translations are restored so VRIK's arm scaling/protraction does not distort the wheel pose. Steering comes from tilt of the line through controller positions, with one-hand/two-hand variants, deadzone and lock angle; wheel hub proximity drives horn. Input arbitration lets the right trigger become weapon fire when a gun is drawn while a throttle latch/trim allows the vehicle to keep moving. This demonstrates per-state ownership transfer between tracked IK and authored animation rather than insisting VR IK always wins.\n\nBODY YAW / LOCOMOTION: Hooks/OnFootMoveXY.cpp and related heading/delta hooks support Game, HMD, LeftHand and RightHand movement sources. Hand-relative movement uses the OpenXR aim pose. Optional physical body rotation feeds headset yaw through the engine's own heading channel; free-look/deadzone/snap logic keeps view rotation separate. This lets mesh/collision/weapon/movement share a body heading while the HMD remains an additive view transform. No teleport/climbing implementation was identified in this snapshot; do not infer them from generic VR locomotion terminology.\n\nBASKETBALL / BODY PHYSICS RESEARCH: CyberpunkVRPort_Basketball is a separate interaction experiment worth preserving as generalized evidence. CET supplies exact dt and grip state; redscript owns a real entPhysicalMeshComponent ball, uses plugin native calls for rigid-body linear/angular velocity, and tops up only normal bounce energy because Cyberpunk/PhysX material restitution cannot reach a basketball-like target without globally changing materials. Tangential physics/spin is left to PhysX. Solved palm/model-space positions become hand anchors. VR body capsules are forced non-queryable so character-controller scene queries ignore them while simulation contacts can still occur — a useful collision-layer distinction for embodied VR.\n\nUI / WORLD MAP / DEVICE CAM / WRIST HUD: CET/redscript modules exist for braindance HUD, crosshair suppression, ForceFPP, world map/head lock, scanner HUD, device camera, loot UI and wrist HUD. The source separates native render duplication from script-side widget/layout policy. Menus intentionally bypass gameplay input remapping. HUDitor now handles individual widget transforms; the port's VR layout assets/config provide a starting layout while avoiding a second competing HUD-transform system.\n\nMULTIPLAYER / REPLICATION: NOT APPLICABLE in this source audit. Cyberpunk 2077's port here has no VR network pose packet, timestamp/interpolation protocol or remote player hand reconstruction. Do not reuse this case as evidence for multiplayer VR replication.\n\nIMPORTANT SOURCE FILES: CMakeLists.txt (single-DLL build/history); src/Main.cpp (RED4ext lifecycle/order); src/Hooks/Registry.cpp + src/Stereo/DetourRegistry.cpp (hook staging); include/Stereo/EngineRvas.hpp + include/Utils/AobScanner.hpp (version-sensitive RE surfaces); src/Runtimes/OpenXRManager.cpp, OpenXRFrameLoop.cpp, OpenXRCapture.cpp, OpenXRPresent.cpp (runtime/actions/timing/swapchains/pose-image binding); src/Stereo/SyncStereo.cpp, FrameGraph.cpp, NodeDispatch.cpp, ViewReuse.cpp, CullVisibility.cpp, Grading.cpp, Hud.cpp, Dlss.cpp, VisionLayer.cpp, Capture.cpp (native second view); src/Hooks/LocateCamera.cpp/PatchCamera.cpp/FinalCamera.cpp/OnFootMoveXY.cpp/XInput.cpp (camera/input/locomotion); src/Hooks/AnimPose.cpp + src/Anim/CharacterRig.cpp (full-body solve/update order); src/Hooks/WeaponAim.cpp + docs/cp2077-hitscan-physicalray-muzzle.md (PhysicalRay); src/Anim/TwoHandGrip.cpp, Recoil.cpp, AdsEyeAlign.cpp, AdsMuzzleStabilizer.cpp; src/Shaders/sight_reflex_ps.hlsl; mods/cet/CyberpunkVRPort_Reload/reload/*; mods/redscript/CyberpunkVRPort_Melee/vrport_melee.reds; Holster/Smoking/Basketball/WorldMap modules; docs/vrik-map.md and the cp2077-* reverse-engineering notes.\n\nREUSABLE PATTERNS FOR AN LLM: (1) use an engine-owned secondary camera/view when possible, but audit the entire per-view/frame-global render graph; (2) explicitly identify views instead of classifying 'everything else' as an eye; (3) bind render pose + eye image + frame serial and preserve that transaction through OpenXR submission; (4) let OpenXR/compositor prediction own late head motion instead of stacking arbitrary custom prediction; (5) solve full-body IK once per engine animation epoch and replay it to repeated pose passes; (6) filter the visual hand attachment/arm consumer, not the global tracking pose; (7) keep weapon visual pose, muzzle, optical axis, native spread cone and combat event separate; (8) preserve shotgun spread by rotating the native cone rather than overwriting rays; (9) make physical reload a generic geometry/state core with per-weapon mechanism data; (10) detect physical melee intent spatially but execute the game's native attack/damage pipeline; (11) use explicit ownership/arbitration for grips shared by reload, foregrip, wheel, holster and props; (12) centralize direct RVAs and byte validations, log every hook result and fail closed on unknown builds.\n\nLIMITATIONS / CONFIDENCE: High confidence for the source-described current snapshot. Build-specific addresses are verified in-source for Cyberpunk 2.31, not universal. README claims were not promoted when current code contradicted legacy text: AER pair lock/custom motion prediction are recorded as removed. Hand collision is recorded as disabled by default because source says so. OpenXR skeletal hand tracking/haptic output are not claimed because their required API symbols/actions are absent. The public web index can lag the supplied source restructuring, so this audit treats the user-provided snapshot as the primary current code artifact and uses the current public README as an independent feature/architecture cross-check.";
CODE_AUDITS["seed_jfovr_case"] = "Source-audit (2026-09-05) against the supplied Jedi Fallen Order UEVR Lua set (Main.luabb, SaberMelee.lua, Controls.lua, CameraManager.lua, GestureScript.lua, Trackers.lua, MeleePower.lua, Handsmain.lua, hands.lua, hand_animations.lua, UEHelper.lua, assetloader.lua, ControlInput.lua). ARCHITECTURE: Main.luabb composes SaberMelee, Controls, CameraManager, UEHelper, Trackers, HolsterScript/GestureScript, MeleePower. TRACKERS: spawn Actors + MotionControllerComponent (Left/Right, MotionSource) + SceneComponent (HMD); UObjectHook hand 0/1/2; Diff_Rotator_LR / Diff_Vector_LR / RightRotator / LeftRotator / HmdRotator each tick; level-change destroy/respawn. MELEEPOWER: samples raw VR poses via vr.get_pose each frame; PosDiffWeaponHand / PosDiffSecondaryHand = world-space speed. SABERMELEE: enables generate-overlap on pawn.weaponCollision; GetOverlappingComponents; filters Hero/Blaster/Volume/Pull/Push; velocity-scaled RsApplyDamage via RsGameplayStatics with RsDamageParams; block path on Blaster/Cannon/Electrostaff/Arrow overlap drives HC_Defense Block Pressed/Released; LightsaberMarks StartTracing/StopTracing when blade extended. CONTROLS: two-handed wield (lShoulder) positions Lightsaber_01 + weaponCollision at L/R controller midpoint with Diff_Rotator_LR orientation after removing MC state; grip switch (rShoulder) lerps CurrGripAngle 0↔π and updates MC location/rotation offsets; blade toggle (A hold timing) calls ExtendRetractBlade on LightsaberChild_01/02; saber throw (rShoulder+RTrigger+velocity) detaches from MC follow, projects along right forward by CurrThrowRange with spin, returns on release; Force gestures capture trigger-start hand position and fire push/pull/slow from displacement thresholds, mapped to XInput triggers/shoulder. CAMERA: right-hand rotation drives SetCameraRotation; decoupled yaw from ThumbRX (snap or smooth); on_early_calculate_stereo_view_offset locks position to pawn and applies DecoupledYawCurrentRot; stick axes rotated by AlphaDiff (HMD vs hand horizontal angle). HANDS: poseable components from pawn.Mesh attached to controllers; hand_animations.lua grip/open/trigger poses; reset on level/menu. GESTURES: HMD-relative RHandNewX/Y/Z zone tests; grab+zone → quick-slots / ToggleUI; haptic enter/exit. UEHELPER: isMenu / isCinematic / isSaber1Extended / isSaber2Extended / isSaberDetached / isInAir / isNavMode globals; raw XInput. REUSABLE PATTERNS: (1) spawn-and-own MC components, (2) velocity + overlap melee into native damage API, (3) two-handed midpoint attachment, (4) detach-and-project weapon throw, (5) displacement-threshold Force/gesture → legacy input, (6) decoupled yaw + stick-frame rewrite, (7) poseable hand mesh + authored grip poses.";
CODE_AUDITS["seed_jkxr_case"] = "Source-audit (2026-09-06, supplied OpenJK.zip). VERIFIED FROM SOURCE.\n\nARCHITECTURE: JKXR is compiled into the OpenJK source tree rather than injected into a retail binary. `JKXR/TBXR_Common.*` owns the cross-title OpenXR/session/eye-buffer layer; `OpenXrInput.cpp` owns actions/controller spaces/haptics; `VrInputDefault.cpp`, `VrInputCommon.cpp`, `VrClientInfo.h` and platform `JKXR_SurfaceView.cpp` translate runtime tracking into a shared `vr_client_info_t`. The ordinary OpenJK client/cgame/game/renderer source is modified to consume that state. `code/` is the Jedi Academy SP lineage and `codeJK2/` carries Jedi Outcast-specific equivalents. This architecture is useful because renderer timing, game combat, UI and controller semantics are source-level seams rather than opaque hooks.\n\nOPENXR FRAME TIMELINE: `TBXR_FrameSetup()` processes XR session state, calls `xrWaitFrame` to obtain `FrameState.predictedDisplayTime`, then `xrBeginFrame`. `TBXR_updateProjections()` calls `xrLocateViews` for that display time in `LocalSpace`; `TBXR_GetHMDOrientation()` locates `ViewSpace` against `StageSpace` at the same predicted time; `VR_HandleControllerInput()` reaches `TBXR_UpdateControllers`, whose aim/grip `xrLocateSpace` calls also use that same predicted display time. `TBXR_ProcessHaptics()` runs before rendering. `SCR_UpdateScreen()` then renders eye 0 and eye 1 into acquired OpenXR framebuffers and `re.SubmitStereoFrame()` reaches `TBXR_submitFrame()`, whose `xrEndFrame` uses the original predicted time. This establishes one frame-level pose time for views, HMD and controllers. No extra renderer late-latch after this sample was found.\n\nSEQUENTIAL STEREO / STATE FREEZE: `SCR_UpdateScreen()` calls `SCR_DrawScreenField(STEREO_LEFT)` and `SCR_DrawScreenField(STEREO_RIGHT)`, ending the engine renderer after each eye but submitting XR only after the pair. `CL_CGameRendering()` updates `cl.serverTime`/Ghoul2 time only on the left eye and passes the frozen time into both cgame renders. `CG_DrawActiveFrame()` changes `cg.time` and calls `CG_ProcessSnapshots()` only for STEREO_LEFT. It deliberately runs `Rand_Init(cg.time)` for both eyes so random effects produce the same result. This is an explicit sequential-stereo side-effect contract rather than simply drawing the same scene twice.\n\nPROJECTION / CULLING: `TBXR_updateProjections()` retains the runtime-provided `XrView.fov` and `pose` per eye. `VR_GetVRProjection()` applies any zoom scaling in tangent space and builds a true asymmetric OpenGL matrix with `XrMatrix4x4f_CreateProjectionFov`; both `rd-gles/tr_main.cpp` and `rd-vanilla/tr_main.cpp` request it before using their flat symmetric projection path. At submission, each `XrCompositionLayerProjectionView` uses the corresponding runtime eye pose and FOV. Separately, `TBXR_submitFrame()` derives `vr.fov_x`/`vr.fov_y` from broad combined eye extents for cgame FOV/culling consumers. This scalar is a conservative compatibility extent, not a claim of a mathematically exact stereo-union frustum.\n\nASYMMETRIC HUD CORRECTION: `TBXR_prepareEyeBuffer()` computes `off_center_fov_x/y` from each eye's asymmetric angular centre. `cg_drawtools.cpp` adds those offsets to the legacy HUD coordinate conversion and zoom overlays use the same values. This keeps the old 640×480 HUD visually centered on headsets whose optical centre is not the arithmetic centre of the eye texture.\n\nSCREEN-LAYER / UI PRESENTATION: `VR_UseScreenLayer()` identifies fullscreen UI, non-immersive cinematic/misc cameras, loading, cinematic state, UI catcher and console. In normal gameplay `TBXR_submitFrame()` emits the two-eye projection layer. In screen mode it also acquires a null/black projection and submits an `XrCompositionLayerQuad` in `StageSpace`, sourced from the game framebuffer, sized in metres and positioned using the latched `hmdorientation_snap` and configurable distance. `VR_GetVRProjection()` returns false in this mode so the game renders the screen with its conventional projection. `interactWithTouchScreen()` converts controller yaw/pitch relative to menu yaw into the legacy absolute mouse path (`PortableMouseAbs` / `CL_MouseEvent`); the active menu hand can switch dynamically.\n\nTRACKING / CAMERA REBASE: `vr_client_info_t` holds current/last/snap HMD pose, offsets/deltas, weapon and offhand pose histories, eye/FOV state, handedness, camera modes, body height, stabilization, velocity-attack and interaction state. `VR_SetHMDPosition()` snapshots HMD position/orientation when `take_snap` is requested or the screen-layer mode changes, then derives the current physical offset. `VR_SetHMDOrientation()` stores angular deltas and first-person reference angles. `BG_ConvertFromVR` and `BG_CalculateVRPositionInWorld` are the shared runtime-to-Raven/world conversion seam. Camera consumers branch deliberately for first person, remote NPC/turret, zoom, vehicles, third person and cinematics.\n\nIMMERSIVE CINEMATICS: `cg_camera.cpp` uses an explicit rebase policy. Entering immersive camera mode, switching FOLLOWING/ROFFING/MOVING/PANNING state, or jumping a non-moving camera by more than roughly half an in-game metre requests `vr->take_snap`. The authored camera yaw is stored; final immersive yaw is authored yaw + HMD yaw delta since the snap + snap turn, while pitch/roll come from the HMD. Non-immersive cinematics instead use the flat quad screen.\n\nLOCOMOTION / TURN / CROUCH: `VrInputDefault.cpp` applies a nonlinear stick filter. Movement can be controller-relative by subtracting HMD yaw from offhand yaw. Physical HMD deltas are scaled for configured world positional factor/refresh and rotated into native forward/side movement. `VR_GetMove()` only exposes that positional component in appropriate first-person states and uses separate policies for remote turret, zoom, possessed NPC, vehicles and third person. Snap/smooth turn accumulates `vr.snapTurn`; vehicle changes re-synchronize first orientation. `bg_pmove.cpp` implements IRL crouch by comparing `curHeight` with calibrated `maxHeight`, adjusting the native stance/collision path and avoiding a duplicate flat camera-height change. The source does not establish a separate swept roomscale body solver beyond native movement processing.\n\nVEHICLES: Jedi Academy vehicle input is a separate adapter. `VR_GetMove()` can use HMD direction or a snap-latched body direction; fighter/flier pitch can come from the average of weapon/offhand controller pitch. `VrInputDefault` also uses controller roll/pitch to influence vehicle yaw/acceleration depending on configuration. This is not physical steering-wheel interaction; it is controller-orientation adaptation into native vehicle controls.\n\nOPENXR INPUT: `OpenXrInput.cpp` creates one gameplay action set with left/right subaction paths, aim/grip pose spaces, vibration output, boolean actions, float triggers/squeeze and vector thumbstick/trackpad state, and suggests bindings for multiple known interaction profiles. `TBXR_SyncActions()` calls `xrSyncActions` once per update and `TBXR_UpdateControllers()` populates aim pose, grip pose and `XrSpaceVelocity`. `VrInputDefault` translates states into `sendButtonAction`, `sendButtonActionSimple`, `Sys_QueEvent` and movement variables so Raven continues receiving its existing semantic commands.\n\nWEAPON HANDS / PRESENTATION: The source exposes tracked weapon/offhand models and hand points but does not demonstrate a tracked full-body or shoulder/elbow IK avatar. Generic Ghoul2 IK APIs elsewhere in OpenJK must not be confused with a JKXR body-IK feature. Per-weapon `vr_weapon_adjustment_<id>` stores scale, xyz offset and pitch/yaw/roll corrections. `CG_CalculateWeaponPositionAndScale()` composes them after `BG_CalculateVRWeaponPosition`, mirrors relevant axes for left handedness, and the special weapon-alignment input mode can tune them live.\n\nTWO-HAND WEAPONS: Offhand grip is context-sensitive. Saber stabilization uses inter-controller proximity. Firearms additionally require the line between the two hands to align with dominant-controller forward (dot > 0.6). If accepted, `vr.weapon_stabilised` is set and averaged support-hand position drives the adjusted weapon direction; saber direction is inverted appropriately. Virtual-stock and scope-specific solvers are separate. If the offhand grip is not accepted as a weapon support, it becomes the Force/item selector instead. This separation prevents one grip button from meaning everything at once.\n\nPHYSICAL SCOPE: Disruptor and Blaster scope entry requires a healthy player, `weapon_stabilised`, and tracked weapon/HMD offset below `vr_scope_engage_distance` (~0.25 m). Moving the weapon away (>~0.26 m), losing stabilization or changing weapon sends the native exit-scope action. Scope rendering narrows the actual OpenXR eye FOV at submission; weapon solution can place the firing origin at the HMD while aligning the supported muzzle toward the headset. This is a physical intent gate around Raven's existing zoom state.\n\nFIREARMS / PROJECTILES: `BG_UseVRPosition()` guards local first-person VR usage. Numerous JA/JO weapon implementations call `BG_CalculateVRWeaponPosition()` to replace `muzzle/start` and derive forward angles immediately before `WP_TraceSetStart`, hitscan traces or `CreateMissile`. Examples include blaster pistol/rifle, bowcaster, disruptor, repeater, DEMP2, flechette, rocket launcher, concussion and vehicle/AT-ST paths. VR therefore changes where/direction the weapon fires but does not replace Raven's ammo, rate-of-fire, spread, projectile, damage/effect or weapon-state systems.\n\nLIGHTSABER — TRACKED BLADE INTO NATIVE COLLISION: In `cg_players.cpp`, the local first-person saber normally begins from the Ghoul2 blade bolt, but `CG_DoSaber` replaces `org_` and axis with `BG_CalculateVRSaberPosition()` when the saber is held and not in a lock/camera path. Those values propagate into the blade's current/old `muzzlePoint`/`muzzleDir` and `renderInfo.muzzlePoint`/`muzzleDir`. `WP_SaberDamageTrace()` then uses current versus old blade state through Raven's original saber sweep/Ghoul2 traces, water/world checks, `CONTENTS_LIGHTSABER`, damage accumulation and saber-intersection/parry logic. Saber entity bounds/block checks and missile deflection therefore consume the same physically tracked saber geometry. This is a true tracked-weapon/native-swept-collision architecture, not 'controller velocity = damage'.\n\nSABER ATTACK INTENT / THROW: `VrInputDefault` reads OpenXR controller linear velocity into `primaryswingvelocity`/`secondaryswingvelocity`. With velocity-triggering enabled, saber/stun-baton motion above a configurable threshold asserts native `+attack`; WP_MELEE maps right/left motion to the native alt/primary punch actions. For saber, attack intent and hit detection are separate: velocity gates attack state, while the tracked blade sweep determines contact. Physical saber throw is still the native `+altattack` mechanic; controller velocity acts as an arming gesture combined with trigger/release, not as a calculated projectile launch speed.\n\nSABER PARRY FEEDBACK: When the local saber receives native SEF_BLOCKED/SEF_PARRIED with a `saberBounceMove`, cgame records `saberBlockDebounce` and the Raven bounce direction and emits a haptic event. During that short debounce `VrInputDefault` adds a triangular time-shaped pitch/yaw correction based on LS_B1_* bounce direction before final tracked saber orientation. The physical hilt therefore reacts to the accepted native clash without becoming gameplay authority.\n\nFORCE PUSH/PULL GESTURES: When configured, a fast offhand movement above `vr_force_velocity_trigger` stores a gesture-start hand position. When the hand slows, the code constructs an approximate chest below the HMD, compares start/end radial distance, derives a palm-away flag from HMD-forward versus controller-right (mirrored by handedness), and if the distance delta exceeds `vr_force_distance_trigger` invokes configured native push or pull via `useGivenForce`. Dual sabers, melee and two-hand weapon stabilization deliberately suppress this classifier.\n\nFORCE RAYS / GRIP DEPTH: First-person Force Grip/Lightning use the tracked offhand. `BG_CalculateVROffHandPosition` supplies direction and `renderInfo.handLPoint` supplies origin for traces/effects. For high-level Grip, the code records initial physical offhand-to-HMD distance when the target is established. Subsequent physical hand depth changes alter the desired native hold distance, clamped to a safe range, while Raven's LOS checks, target eligibility and `WP_ForcePowerStop` remain authoritative. This is direct spatialization of an existing telekinesis mechanic, not a replacement physics-grab system.\n\nPHYSICAL USE: `VrInputDefault` turns weapon/offhand distance beyond a body boundary into `+use`/`+altuse` while appropriate. `G_TouchTriggersLerped` suppresses body activation of USE_BUTTON triggers under this mode. `G_TouchTriggersWithHand()` then queries a small box around the corresponding tracked hand (with an offset to compensate trigger depth), enforces facing for directional buttons, excludes hurt triggers, emits hand haptics, and calls the original `GEntity_TouchFunc`. VR changes the spatial activator while native trigger scripts stay untouched.\n\nSPATIAL SELECTORS: Dominant grip opens weapon/stance/inventory selection; unsupported offhand grip opens Force/quick selection. `CG_DrawItemSelector()` snapshots the opening hand pose, creates a tracked radial selector, converts controller angular displacement into a 2D selection vector, slows `timescale` to 0.22, emits per-icon haptics and commits via the original selection commands when the grip is released.\n\nHAPTICS: OpenXR exposes a vibration output action per hand. `TBXR_Vibrate` stores per-channel duration/intensity and `TBXR_ProcessHaptics` applies/stops `XrHapticVibration`. Game code sends semantic `VR_HapticEvent` names for pickups, weapon switches/fire, saber feedback, Force effects/use buttons, etc.; platform code selects dominant/support/both channels and can forward the same named event to an external haptics service. This is an event-driven feedback layer rather than haptics tied directly to raw buttons.\n\nCOMFORT: `CG_DrawVignette` activates a configurable vignette based on native player velocity, airborne state and smooth-turn yaw deltas; it fades the effect rather than simply turning it on/off. This correctly keys comfort to artificial/world movement rather than raw HMD movement.\n\nMULTIPLAYER / BOUNDARIES: The supplied tree contains OpenJK multiplayer source as well as SP code, but this JKXR integration does not demonstrate a VR pose packet/state or remote tracked-hand/body reconstruction comparable to L4D2VR. Do not infer remote XR embodiment merely because OpenJK has networking. Likewise, the source does not establish full-body IK, OpenXR skeletal finger retargeting, manual magazine reloads or controller-velocity projectile throwing.\n\nREUSABLE MODEL: predicted-time XR frame owner -> freeze legacy simulation across stereo replay -> true asymmetric eye projection + conservative legacy FOV -> explicit camera/screen-mode rebasing -> centralized tracking state -> semantic OpenXR actions -> native movement/input -> tracked weapon/muzzle adapters -> tracked saber into native swept blade history -> native block event back to hilt/haptics -> physical Force/use gestures into original gameplay contracts -> spatial legacy UI/selection.";
CODE_AUDITS["seed_farcryvr_case"] = "FULL SOURCE AUDIT (2026-09-06; supplied `farcry_vrmod-main` ZIP). VERIFIED FROM SOURCE. ARCHITECTURE: hybrid CryGame source modification plus narrow MinHook access to the opaque CryEngine renderer and a custom DXVK fork. Key files are `VRManager.cpp/.h`, `VRRenderer.cpp/.h`, `VRInput.cpp/.h`, `VRHaptics.cpp/.h`, `Hand.cpp/.h`, `XPlayer.cpp`, `XPlayerCamera.cpp`, `XClient.cpp`, `XEntityProcessingCmd.cpp/.h`, `WeaponClass.cpp/.h`, vehicle code and FCData weapon scripts. The launcher runs the CryVR mod with custom DXVK environment configuration; `.gitmodules` identifies DXVK, MinHook and OpenVR dependencies. RENDERER/XR: OpenVR is initialized in standing space. `VRRenderer` obtains the D3D9Ex device from `dxvkGetCreatedDevice`, hooks Present/SetCamera, samples HMD poses with `WaitGetPoses`, sequentially replays the native render for both eyes, disables the CryEngine timer during the second replay, captures the eye buffers, captures HUD/mirror at pre-Present and submits after Present. `FinishFrame` uses custom DXVK exports to convert D3D9 textures to Vulkan texture descriptors, transition image layouts and lock queue ownership while submitting eye/HUD/stereo textures to OpenVR; no CPU copy is involved. PROJECTION: raw per-eye FOV tangents are reduced to a conservative symmetric engine FOV, while per-eye compositor texture bounds crop the oversized images back to the real asymmetric extents. The source's direct asymmetric frustum update is commented out; documented distant LOD stereo artifacts therefore remain a limitation. The SetCamera hook repairs CryEngine's special DRAW_NEAR FOV. TIMING/LATE UPDATE: HMD pose is sampled once at render start. After that sample, the local player's controllers are refreshed and first-person weapon positioning is recomputed immediately before eye rendering. This is a real presentation-time controller/weapon update but not a second HMD late latch. TRACKING: `OpenVRToFarCry/FarCryToOpenVR` centralize axis conversion. Reference yaw/position and uncommitted variants implement a deferred rebase: roomscale turn/move alters native player state and accumulates the equal tracking correction, then `OnPostPlayerCameraUpdate` commits it. MENU/CUTSCENE skips cause a recalibration before movement resumes. LOCOMOTION: physical yaw goes through normal player delta angles; horizontal roomscale displacement is incrementally clamped, aligned with ground slope and applied through the ordinary entity position, then consumed from tracking reference. HMD height maps to native stand/crouch/prone states and camera base height is compensated. Immersive ladders convert controller pull deltas into native ladder vertical speed and use a ray+`CanStand` dismount. CAMERA/RECOIL: native camera gives world/body base, HMD gives tracked orientation; legacy weapon sway is suppressed and native recoil is diverted into weapon-offset angles rather than HMD rotation. INPUT: external SteamVR action manifest -> semantic default/move/weapons/vehicles sets -> existing `CXClient::Trigger*` commands. Short/long press multiplexing and spatial hand-to-head modifiers add VR semantics without replacing the native command layer. HANDS: stock hand/viewmodel skeletons are aligned to controller grip bones; parent arm bones are hidden/collapsed; native reload/support animation visibility is preserved. No full-body/arm IK or skeletal finger tracking is shown. WEAPONS: per-weapon script metadata and live `BoneRightHand`, `BoneLeftHand`, offsets and `SpitFireBone` derive dominant/support grip and muzzle transforms; left-handed mirroring is corrected. Two-hand behavior is explicit DISABLED/SINGLE/FULL. FULL derives orientation from the hand-to-hand axis while retaining main-hand translation; SINGLE allows physical support without orientation authority. WEAPON FIRE: tracked physical muzzle replaces `GetFirePosAngles`, after which original `CWeaponClass::Fire` retains cadence, synchronized spread, ammo, ray/projectile, hit and script authority. Grenades remain button-triggered with no controller-velocity throw. MELEE: tracking-relative controller speed gates a physical swing; world muzzle movement supplies direction; a short broad-phase/beam test avoids attacks into empty space; then original native melee fat-beam collision/damage runs. UI/SCOPES: native HUD is captured to an OpenVR overlay with head, fixed-world, off-hand binocular and physical weapon-zoom attachment policies; a separate side-by-side overlay supports stereo cinema/zoom fallback. Binocular rotation is stabilized; native overlay mouse mapping is retained for menus. HAPTICS: named sampled effects are mixed per hand and the same semantic events fan out to OpenVR controllers, bHaptics and ProTube. NETWORK: `CXEntityProcessingCmd` actually serializes the VR flag, dominant hand, HMD pose/reference height and both controller poses in Far Cry's existing command stream; `CPlayer::ProcessAngles` consumes them. This demonstrates transport groundwork, but the README explicitly says multiplayer motion controls are not properly implemented and no complete remote tracked-avatar presentation is established. GENERALIZATION: this project is a high-value model for combining source-level gameplay adaptation with an opaque legacy renderer: isolate renderer hooking/interop, make tracking/recenter a coherent transaction, keep physical VR gestures as semantic intent, and reuse native movement/weapon/melee/network/UI authorities wherever possible.";
CODE_AUDITS["seed_l4d2vr_case"] = "Source-audit (2026-09-05, full source verification). VERIFIED FROM SOURCE (dllmain.cpp, game.cpp/h, hooks.cpp/h, offsets.h, sigscanner.h, vr.cpp/h).\n\nBOOTSTRAP / INJECTION: Loads as d3d9.dll (DXVK-based proxy). DllMain spawns InitL4D2VR on a new thread; the process is terminated unless the command line contains -insecure. Game constructor obtains module bases (client/engine/server/MaterialSystem/vgui2) with retry, then resolves interfaces via CreateInterface with a static cache. Offsets are constructed with SigScanner::VerifyOffset: each target is validated against a byte signature; mismatch or missing signature fails closed with an error dialog.\n\nRENDERING / STEREO: dRenderView creates two independent CViewSetup structures. Left/right origins come from VR::GetViewOriginLeft/Right (HMD position + eye-to-head offset + IPD scale); angles are shared from the HMD. FOV, aspect, near planes and viewport size are forced from the OpenVR recommended render target size and GetProjectionRaw-derived tan-half-FOV values. Each eye is rendered into a named MaterialSystem render target (leftEye0 / rightEye0) created with MATERIAL_RT_DEPTH_SHARED. Submission uses DXVK Vulkan shared textures (m_VKLeftEye / m_VKRightEye) passed to VRCompositor()->Submit together with per-eye VRTextureBounds_t. A blank texture is submitted while not in-game.\n\nHUD / UI: A call-sequence detector (IsSplitScreen -> PrePushRenderTarget -> PushRenderTargetAndViewport) identifies the HUD push and redirects the texture to a dedicated vrHUD RT. The HUD is then submitted as an OpenVR overlay (with mouse-scale matching window size). Menu overlays are repositioned in absolute tracking space in front of the HMD. Laser interaction uses controller tip matrix + ComputeOverlayIntersection -> VGUI cursor.\n\nCAMERA / COORDINATE SPACES: HMD and controller poses are converted from OpenVR (Y-up, -Z forward) into Source space. Roomscale is implemented with an explicit m_CameraAnchor + m_HeightOffset; the anchor is advanced only while the player is grounded and not pushing the thumbstick. A wall-clip TraceRay from setup origin through the HMD prevents the camera from entering geometry. Stick turning applies a yaw pivot around the HMD for both head and controllers.\n\nINPUT: Full OpenVR Input action set (ActivateVR, Jump, PrimaryAttack, Reload, Use, Walk, Turn, SecondaryAttack, Next/PrevItem, ResetPosition, Crouch, Flashlight, Menu*, Spray, Scoreboard, ShowHUD, Pause). Digital and analog actions are polled every frame and mapped to Source ClientCmd strings. Controller tip component matrices are queried via RenderModels for accurate laser origin.\n\nWEAPONS: dServerFireTerrorBullets and dClientFireTerrorBullets replace the bullet origin/angles with the right-controller absolute pose for the local player (and for any remote player whose m_PlayersVRInfo entry is marked isUsingVR). Viewmodel is driven by CalcViewModelView using GetRecommendedViewmodelAbsPos/Angle (controller tip + configurable offset).\n\nMELEE (high-value): On the server, dProcessUsercmds detects a VR melee swing from the replicated controller pose history. It reconstructs a continuous arc (10 traces) by rotating the previous forward vector around the swing pivot axis by the measured angle delta, then calls the native TestMeleeSwingCollisionServer for each sample. A velocity threshold on the controller sets the isNewSwing flag and resets the hit counter. During the swing, dEyePosition is overridden so the native code sees the controller position as the eye origin.\n\nMULTIPLAYER POSE REPLICATION (rare & valuable): dWriteUsercmd packs the right-controller position and angles into the existing CUserCmd fields (negative tick_count as signal, command_number encoding for roll, viewangles.x packing for Z+X, upmove for Y, mousedx/y for pitch/yaw). The verified-command checksum is recalculated. dReadUsercmd on the server decodes the same fields into the per-player m_PlayersVRInfo array. Consequently remote VR players receive correct aim and melee without a custom network message.\n\nFRAME TIMING: VR::Update runs every frame after WaitGetPoses + UpdateActionState. Poses are sampled once; there is no additional late-latch beyond OpenVR's prediction. Texture creation is deferred until the first RenderView.\n\nREUSABLE PATTERNS:\n1. Signature-scanned, fail-closed offset table (Offsets + SigScanner).\n2. Forced dual-eye RenderView into MaterialSystem RTs + DXVK Vulkan share for compositor submission.\n3. HUD RT interception by call-sequence detection rather than name matching.\n4. Controller pose packed into stock CUserCmd for multiplayer (no extra netcode).\n5. Server-side multi-trace reconstruction of physical melee from pose history.\n6. Explicit roomscale camera anchor with wall-clip correction and locomotion-state gating.\n7. Action-manifest-driven OpenVR Input mapped to legacy ClientCmd for maximum compatibility.\n\nLIMITATIONS (from source + observed behaviour): Throwables and world interactions still use face-aim; roomscale is disabled while the thumbstick is active; arms model is optionally hidden via DrawModelExecute material override; CPU cost of dual full-scene renders is high. The project is a working prototype, not a polished release.\n\nEVIDENCE LEVEL: All statements above are taken directly from the supplied source files (game.*, hooks.*, vr.*, offsets.h, sigscanner.h, dllmain.cpp). No claims rest solely on README text.";
CODE_AUDITS["seed_sihvr_case"] = "Source-audit (2026-09-05). VERIFIED FROM SOURCE: `Plugin.cs` is a BepInEx 5 `BaseUnityPlugin`; `Awake()` initializes settings, installs Harmony patches with `PatchAll`, creates a persistent `SiHVR.Host` GameObject and adds the `VRRuntime` component. `VRRuntime` subscribes to `SceneManager.sceneLoaded`, starts XR once through `XRBoot.Run()`, updates `CameraTracker` during `Update`, and performs controller/locomotion/camera work during `LateUpdate`. VERIFIED FROM SOURCE: `XRBoot.cs` loads `Unity.XR.Management` and `Unity.XR.OpenXR` assemblies from `Application.dataPath/Managed`, resolves `XRGeneralSettings`, `XRManagerSettings`, `XRLoader` and `OpenXRLoader` by reflection, creates the ScriptableObject instances, attaches the OpenXR loader, assigns the manager/settings singleton, enables available controller interaction-profile feature objects, invokes `InitializeLoaderSync` (or `InitializeLoader`) and then `StartSubsystems`. The loader setup has compatibility fallbacks that manipulate private fields such as `m_Loaders`/`m_RegisteredLoaders` and the XR settings singleton when public members are unavailable; failures are logged and initialization stops. `ConfigureOpenXRSettings()` separately reflects into `OpenXRSettings` to force a multi-pass-style render mode (matched by scanning the render-mode enum's member names for \"Multi\" rather than a hardcoded enum value, another version-tolerance fallback) and to instantiate and register five OpenXR controller-interaction-profile feature objects (Oculus Touch, Valve Index, HTC Vive, Microsoft Motion Controller, KHR Simple) by reflecting a features list/array field on the settings object, so the loader advertises broad controller-profile support without depending on which profiles the shipped OpenXR feature DLLs happen to expose at compile time. After `StartSubsystems` succeeds, `XRSettings.eyeTextureResolutionScale` is set to 1.4 as a fixed supersampling factor. VERIFIED FROM SOURCE: `CameraTracker.cs` classifies scenes after a 15-frame settling delay. `Custom` and `ADV` are forced to `VirtualScreen`; otherwise a fullscreen perspective screen camera that renders the Default layer establishes an immersive scene. The primary camera is selected by a culling-mask/depth score, stereo is enabled only on that camera, and `Application.onBeforeRender` becomes the late pose seam. At that point the mod resets Unity camera matrices, forces a fullscreen rect, reads `XRNode.CenterEye` local position/rotation, and applies the HMD pose through `Locomotion.GetRigRotation()` and `RigOffset` before rendering. VERIFIED FROM SOURCE: `Locomotion.cs` implements grip-drag by subtracting controller-local position deltas transformed through the current game/rig rotation, stick turning with a 0.2 deadzone and 45-degree-per-second base rate, recentering by solving a new rig rotation/offset from the current HMD pose, and a spawn-placement routine that waits for combined `SkinnedMeshRenderer` bounds to stabilize before placing the player relative to the posed character and floor. VERIFIED FROM SOURCE: `ControllerInput.cs` polls both hands every frame via `InputDevices.GetDeviceAtXRNode`, reading `CommonUsages.devicePosition/deviceRotation` (grip pose) plus grip/trigger/primary/secondary buttons, trigger analog value, thumbstick axis and click. It separately probes two custom, non-`CommonUsages` features, `InputFeatureUsage<Vector3>(\"PointerPosition\")` and `InputFeatureUsage<Quaternion>(\"PointerRotation\")`, explicitly documented in-source as the OpenXR \"aim\" pose distinct from the grip pose, exposed only if the runtime surfaces it through the legacy `InputDevices` layer; validity and full feature-name lists are logged once per hand for runtime diagnosis, and all button/axis state is force-reset when a device reports invalid. VERIFIED FROM SOURCE: `LaserPointer.cs` casts a ray for both hands every frame from that aim pose via `VRPose.AimRay(posed, hand, ...)`. Against UI targets it does not use `Physics.Raycast` at all: it transforms the ray into each registered quad's local space with `InverseTransformPoint`/`InverseTransformVector` (the vector form specifically to stay correct under non-uniform scale), solves for the local `z=0` plane crossing, and bounds-tests against a unit square, mapping the local hit to render-texture pixel coordinates for the fake cursor. In `Immersive` scenes with `Settings.CaressClick` enabled, it additionally runs a real `Physics.Raycast(rayOrigin, rayDir, out hit, Caress.Reach, Caress.LayerMask, QueryTriggerInteraction.Collide)` against the character's layer-19 trigger colliders, only overriding the UI-quad hit if the body hit is strictly nearer (UI keeps priority at equal/closer distance); on a body hit the cursor is projected through the posed camera's `WorldToScreenPoint` instead of quad-UV math. Because the game exposes only one mouse cursor for two independently-pointing hands, `SelectDriver()` implements a sticky arbitration: the current driver hand keeps control while still \"engaged\" (trigger held everywhere, plus grip/thumbstick-click in virtual-screen scenes only, since grip/stick are repurposed for locomotion/turning in Immersive scenes), otherwise driver follows whichever hand is hovering a target, with ties resolved by keeping the existing driver. A press-time cursor freeze (`_pressDownCursor`) held until the live cursor moves past a 30px `DragThresholdPixels` disambiguates a click from a drag, and per-hand last-valid-cursor/quad/world-hit state lets a drag continue briefly if the ray momentarily leaves the target. All of `WorldHitActive`, `WorldHitPoint`, `GameMouseActive`, `OnNonGameQuad`, `EffectiveCursorRTPos` and the per-button held/edge-down/edge-up flags are computed here and gate on `effectivelyOnQuad` for held/down states but explicitly not for edge-up, guaranteeing releases are never swallowed off-target. VERIFIED FROM SOURCE: `InputPatches.cs` is a set of Harmony prefix patches on `UnityEngine.Input` — `mousePosition`, `mousePresent`, `GetMouseButton(int)`, `GetMouseButtonDown(int)`, `GetMouseButtonUp(int)`, `GetAxis(string)`, `GetAxisRaw(string)` and `mouseScrollDelta` — each returning `false` to fully replace the native getter/method with `LaserPointer` state when the laser is active, and returning `true` (falling through to the real Unity input) otherwise. `mousePosition` has two source-driven branches: when `LaserPointer.WorldHitActive`, it projects `LaserPointer.WorldHitPoint` through `CameraTracker.Primary.WorldToScreenPoint`; when `LaserPointer.GameMouseActive`, it reports `LaserPointer.EffectiveCursorRTPos` (the render-texture cursor) directly. Trigger/grip/an equivalent-to-middle-click map to mouse buttons 0/1/2 respectively, using separately tracked held vs. edge-down vs. edge-up state from `LaserPointer`. `GetMouseButtonUp` deliberately skips the `GameMouseActive` gate the other patches use (only suppressing when `OnNonGameQuad`), so a release always reaches the game even after the cursor drifts off a surface mid-click, preventing a stuck drag/press state; NGUI's `GetAxis(Raw)(\"Mouse ScrollWheel\")` and UGUI's `mouseScrollDelta` are both patched from the same `LaserPointer.ScrollY` value so either UI stack scrolls correctly. VERIFIED FROM SOURCE: `CaressPatch.cs` documents (and `LaserPointer`/`InputPatches` jointly implement) the exact caress bridge: the game's own `Zng_Controller.Zng_Update`/`IC_Flick.Update` raycast `Main_Controller.MainCamera.ScreenPointToRay(Input.mousePosition)` against layer 19 only, hitting named body colliders (`BP_Breast_*`, `milk*`, `HS_pussy00_Coll`, etc.) that the main camera does not itself render. Rather than patching that game code, the mod raycasts its own laser against the same layer, then injects a synthetic `Input.mousePosition` equal to `WorldToScreenPoint` of that hit; the game's unmodified raycast re-casts through the same camera and world point, lands on the same collider, and its native `GetMouseButtonDown`-driven press logic fires normally. VERIFIED FROM SOURCE: `HandUI.cs` displays the game's existing NGUI `Camera_UI` overlay in world space rather than reimplementing it: `BindBestUICamera()` scans active cameras each frame for the highest-depth active orthographic camera not already targeting its own render texture, saves its `clearFlags`/`backgroundColor`/`cullingMask`, then sets `clearFlags=SolidColor` with a transparent color, ANDs the mod's own `VRLayer.Mask` out of its `cullingMask` (so the display quads are not captured by the camera displaying them, avoiding a feedback loop), and redirects `targetTexture` to a mod-owned `RenderTexture`; original state is restored on camera change or `Hide()`. Three `Quad` primitives (colliders destroyed) display that texture: one per hand, positioned via a fixed local hand-space offset/rotation each frame (`handPos + handRot*(0,0.04,0.10)`, `handRot*Euler(90,0,0)`), and one dockable panel toggled by either hand's secondary button, which captures and freezes the live pose of whichever hand's press triggered the toggle (falling back to `HandRoles.PrimaryHand`, or to a head-relative pose if no hand is tracked). Quad materials/shaders are resolved defensively through an ordered `Shader.Find` fallback list to survive shader stripping in the shipped build. VERIFIED FROM SOURCE: `HandRoles.cs` resolves only which hand *displays* the panel from `Settings.ImmersivePanelHand`; laser ownership is explicitly decoupled per an in-source comment (\"The laser is no longer owned here\") so both hands always cast independently and either can dock-then-point with the same controller for one-handed use. VERIFIED FROM SOURCE: `Hands.cs` is a two-method no-op stub (`Update`, `HideAll`) with an in-source comment that hand visuals were dropped because controller-driven hand animation needs animator-driven prefabs or hand-tracking joint data the author didn't have clean access to — no hand mesh, skeleton or finger animation exists in the reviewed source. FRAME TIMING: the source establishes an `Application.onBeforeRender` camera/pose update seam, but the reviewed public source does not expose a complete explicit `xrWaitFrame`/predictedDisplayTime -> simulation -> eye render -> `xrEndFrame` sequence; keep predicted-display scheduling/late-latching beyond Unity's `onBeforeRender` seam UNKNOWN. COORDINATE SPACES: the source explicitly separates XR CenterEye local pose, game camera transform, rig rotation and rig offset; controller-local locomotion deltas are transformed through the current game/rig rotation before changing the player anchor. INPUT: OpenXR interaction profiles are enabled reflectively (verified in `XRBoot.ConfigureOpenXRSettings`) and controller state is consumed through `ControllerInput`, which verifiably distinguishes grip pose from a separately-queried OpenXR aim pose; the exact per-profile action-path binding code inside Unity's OpenXR package itself was not independently inspected (that layer is upstream of this mod), so do not invent action-path strings. HANDS/UI: fully source-verified. `Hands.cs` confirms no hand mesh/skeleton/finger animation exists (explicit stub). `HandUI.cs`/`HandRoles.cs`/`LaserPointer.cs` confirm a complete, working world-space UI and dual-hand pointer/click/drag/scroll system built entirely on faked native `Input` state (via `InputPatches.cs`) and manual local-space quad raycasting, with no avatar IK anywhere in the reviewed source. CARESS: fully source-verified (previously inferred-only) — `LaserPointer` raycasts layer 19 with real `Physics.Raycast`, `InputPatches` projects the hit through `WorldToScreenPoint` into a faked `Input.mousePosition`, and the game's native `Zng_Controller`/`IC_Flick` raycast (unmodified) resolves the touch normally. WEAPONS/MELEE/MULTIPLAYER: UNKNOWN from the reviewed public source. REUSABLE PATTERN: dynamically bootstrap a missing Unity XR stack at runtime, isolate runtime-version assumptions behind reflection helpers (including scanning an unknown enum's member names for a substring match rather than hardcoding an enum value), keep scene classification/camera policy separate from XR initialization, use `Application.onBeforeRender` for the last camera-pose update available to Unity, and explicitly fall back to a render-to-texture/virtual-screen presentation for scenes whose camera graph is not safe to stereoize. Separately, and just as reusable: (1) a \"raycast-to-native-input-injection\" bridge — Harmony-patch the engine's low-level input surface (`Input.mousePosition`/`GetMouseButton*`/scroll) to feed a VR laser's hit point back through the game's own camera via `WorldToScreenPoint`, so completely unmodified native UI/interaction code (NGUI, or arbitrary raycast-driven gameplay logic like a body-touch system) keeps working without a single gameplay patch; (2) manual local-space plane-intersection raycasting against UI quads instead of physics colliders, avoiding physics-layer bookkeeping for pure display geometry; (3) sticky single-driver arbitration to resolve two independently-tracked hands down to the one cursor concept a legacy game actually understands, with hysteresis so an in-progress gesture never jumps hands; (4) capturing an existing 2D UI camera into an offscreen render texture and self-excluding the mod's own render layer from that camera's culling mask to avoid a capture feedback loop, letting a VR mod reuse an entire native UI system on a 3D quad instead of reimplementing it; (5) explicit separation of an OpenXR \"aim\" pose from the grip pose for pointing accuracy, discovered via a custom string-keyed `InputFeatureUsage` rather than `CommonUsages`. This is especially useful for BepInEx retrofits where the shipped game has no XR package references, where menus/cinematic camera graphs need a different presentation policy from gameplay, and where a legacy Unity UI/interaction stack needs VR input without being rewritten.";
CODE_AUDITS["seed_gvrmod_openxr_case"] = "Source-audit (2026-09-05). VERIFIED FROM SOURCE: `build.bat` compiles `vrmod_log.cpp`, `xr_input.cpp`, `d3d_hooks.cpp`, `xr_session.cpp`, `xr_render_d3d.cpp` and `lua_interface.cpp` into `gmcl_vrmod_xr_win64.dll`; the Windows OpenXR path uses `XR_KHR_D3D11_enable`, while project documentation distinguishes Windows D3D9/11 sharing from Linux OpenGL/GLX/togl texture/FBO sharing. VERIFIED FROM SOURCE: `src/input/xr_input.h` makes the native input boundary explicit: action sets and pose-action spaces are cached in native state; the module parses a SteamVR-format action manifest, creates/attaches OpenXR action sets, synchronizes them per frame, exposes boolean/float/vector2/pose queries, triggers haptics, suggests interaction-profile bindings, creates/tears down action spaces, and exposes physical controller-source IDs/values for rebinding. It also exposes `XR_GetSkeletalSummaryData`, an OpenVR-compatible summary that synthesizes finger curl/splay from controller trigger/grip/buttons rather than requiring OpenXR hand-tracking actions. VERIFIED FROM DOCUMENTATION: the Lua addon is the gameplay/UI/bindings layer; `require(\"vrmod_xr\")` selects the OpenXR native module while `require(\"vrmod\")` selects the sibling OpenVR module, with `vrmod_prefer_backend` controlling selection. VERIFIED FROM DOCUMENTATION: the current feature surface includes VR menus/hand panels, pickup, collisions, locomotion, Glide, climbing hooks and controller rebinding. MULTIPLAYER: Garry's Mod is multiplayer-capable, but the reviewed native source does not establish a complete network pose packet/interpolation design; keep that UNKNOWN. FRAME TIMING: `XR_UpdatePoses` and `XR_RefreshHMDPose` expose explicit pose-update seams, and the latter is documented as locating views at the current predicted time, but the reviewed public material does not prove the full `xrWaitFrame`→simulation→render→submit ordering; keep the complete timeline UNKNOWN. REUSABLE PATTERN: define a small XR ABI consisting of semantic actions, pose spaces, haptics, physical controller sources and backend identity, then keep gameplay in Lua. Pair that with backend-specific graphics-resource adapters so Windows and Linux can use different texture-sharing mechanisms without forcing platform checks into gameplay code. This is stronger and more general than treating OpenXR as a collection of one-off Lua bindings.";
CODE_AUDITS["seed_openmwvr_case"] = "VERIFIED FROM THE SUPPLIED FULL OPENMW-VR SOURCE SNAPSHOT (archive commit text 0f520f65c3e085369e66d6a90ce871e817d4533f). ARCHITECTURE: OpenMW-VR is a source-level OpenMW engine fork, not an injected patch against Bethesda's original Morrowind executable. The VR implementation is layered across `components/xr` (OpenXR runtime/session/actions/swapchains/reference spaces), `components/vr` (runtime-agnostic frame/layer/swapchain/viewer abstractions), `components/stereo` (OpenSceneGraph stereo/multiview/frustum handling), `apps/openmw/mwvr` (Morrowind-specific tracking, animation, input, GUI, pointer and combat), native OpenMW gameplay/rendering seams, and Lua VR scripts under `files/data/scripts/omw/vr`. This is a particularly useful reference for a source-accessible flat-to-VR port because XR lifecycle, renderer stereo state, game-world tracking anchors, animation, gameplay and UI can share explicit engine types rather than communicating through memory hooks.\n\nOPENXR FRAME OWNERSHIP / TIMING: `components/xr/session.cpp::syncFrameUpdate` calls `xrWaitFrame`, records `shouldRender`, `predictedDisplayTime` and `predictedDisplayPeriod`, and clears a per-frame pose cache. `components/vr/session.cpp::frameBeginUpdate` publishes that predicted time, invokes frame listeners, then opens a bounded `locateSpace` window; `updateSpaces` closes that window after space consumers have updated. `XR::Session::locateSpace` rejects calls outside frame sync, locates at `VR::getPredictedDisplayTime()`, classifies tracking as Good/Stale/Lost and caches each `(space, referenceSpace)` result for the frame. `VR::Viewer::updateView` locates both LOCAL-space eye views for compositor submission and VIEW-space eye views for rendering using the same predicted display time. The first stereo draw callback calls `xrBeginFrame`; the final eye callback resolves/blits the eye and optional depth images; the swap-buffers callback finally calls `xrEndFrame` with the original predicted display time. This is an explicit timeline: wait/predict -> update/listeners -> pose locate/cache -> stereo views -> begin XR frame at render start -> render/resolve -> end XR frame after the graphics swap. There is no separate source-demonstrated late-latch stage beyond this predicted-time sampling/caching design.\n\nSTEREO / PROJECTION / CULLING: `components/stereo/stereomanager.cpp` supports both brute-force OpenSceneGraph stereo and `OVR_multiview2`. The brute-force path gives OSG SceneViews explicit left/right projection and view-offset callbacks and unique cull-visitor identifiers. The multiview path disables OSG's ordinary stereo and supplies shader defines (`useOVR_multiview=1`, `numViews=2`) plus a multiview framebuffer. Every frame, each runtime eye receives its own pose and asymmetric `Stereo::FieldOfView`; separate normal and reverse-Z perspective matrices are built. The master OSG camera gets a union FOV containing both eyes, while `StereoFrustumManager` transforms both eye clip volumes into the master clip space and unions their bounding boxes; the same custom frustum can be supplied to shared shadow-map culling. Reusable rule: render with the physical per-eye matrices but cull against a conservative union so geometry visible to either eye survives CPU culling.\n\nSWAPCHAINS / GRAPHICS-API INTEROP: `components/xr/platform.cpp` negotiates the graphics binding rather than assuming one API. On Windows it can use native OpenGL via `XR_KHR_opengl_enable`, or—when the runtime/driver path supports it—select `XR_KHR_D3D11_enable` and create a D3D11 device while OpenMW continues rendering through OpenGL. `components/vr/directx.cpp` bridges D3D11 OpenXR images into GL through `WGL_NV_DX_interop2`. The format negotiation explicitly maps only exact DXGI<->GL equivalents; unsupported runtime formats are discarded, and the runtime-specific `disable texture format` list can blacklist troublesome formats. `DirectXSharedImage` locks/unlocks the interop object around GL use and, when an OpenXR runtime image cannot be directly registered, creates an intermediate D3D11 texture and `CopyResource`s it back into the runtime image. This is a concrete source-level solution for a legacy/OpenGL renderer whose OpenXR runtime exposes a D3D11 graphics path.\n\nDEPTH / REPROJECTION / POSTPROCESS: if `XR_KHR_composition_layer_depth` is enabled, OpenMW-VR creates per-eye depth swapchains and attaches `XrCompositionLayerDepthInfoKHR` to projection views. Reverse-Z is handled explicitly by swapping the near/far values submitted to OpenXR. If depth swapchain creation fails, `VR::Viewer::setupSwapchains` logs the failure and disables depth sharing instead of aborting VR. `XR_MSFT_composition_layer_reprojection` is queried for supported modes and depth reprojection is used only when available. The ordinary OpenMW postprocessor is adapted rather than bypassed: `MWVR::PingPongCallback` redirects final ping-pong output into the current VR eye/multiview framebuffer, and at the end copies the appropriate opaque/primary depth into the stereo target so the viewer can submit it. This preserves the engine's existing full-screen postprocess chain while making its output and depth destination VR-aware.\n\nCOORDINATE BOUNDARY / REFERENCE SPACES: `components/xr/typeconversion.cpp` centralizes the OpenXR<->OSG axis remap: XR `(x,y,z)` becomes OSG `(x,-z,y)` and quaternion `(x,y,z,w)` becomes `(x,-z,y,w)`. Positions remain typed as `Stereo::Position`, which distinguishes meters from Morrowind world units. The outbound quaternion conversion also replaces near-zero malformed quaternions with identity because runtimes may fail on invalid orientation data. `components/xr/space.cpp` implements LOCAL/VIEW/STAGE reference spaces and can recenter X/Y/Z independently by recreating the reference space with an offset measured against another reference. On session focus, horizontal and vertical recenter are requested. This keeps runtime coordinate conversion and recentering at one boundary instead of allowing gameplay code to invent ad-hoc axis swaps.\n\nPLAYER/WORLD TRACKING ANCHOR: `apps/openmw/mwvr/vranimation.cpp::VRAnimation::updateSpace` locates VIEW relative to LOCAL and treats the change in physical head yaw as native character yaw. It rotates the real player object through OpenMW's `World::rotateObject`; if some other game system rotated the character, it compensates `mCharLocalSpacePose.orientation` so tracking does not receive that same yaw twice. `updateLocalSpaceWorldPose` derives the player's world origin from the actual animation parent transform, adds measured character-head height, and writes `XR::Session::setReferenceWorldPose(originPose + mCharLocalSpacePose)`. All `locateInWorld()` consumers then use that explicit LOCAL->world anchor. This is the core spatial contract: XR LOCAL is stable physical tracking; the game character remains authoritative for world position/yaw; a rebased reference-world pose maps the two together.\n\nCAMERA: `apps/openmw/mwrender/camera.cpp` owns a dedicated `Mode::VR`. `Camera::onSpaceUpdate` locates the OpenXR VIEW space in world coordinates and stores it as `mTrackedPose`; VR `getPosition` and `getOrientation` return that tracked pose directly and `updateCamera` builds the OSG camera from it. Attempts to switch to ordinary non-VR camera modes are ignored while VR is active. Camera instant transitions are forwarded to VR session listeners so dependent spaces/UI can reset synchronously. This makes the tracked VIEW pose authoritative for the rendered camera while player/body rotation remains a separate gameplay state.\n\nINPUT / CONTROLLER CAPABILITIES: `files/openxrinteractionprofiles.xml` is a data-driven device database. It enumerates controller top-level paths and per-profile Boolean, float, axis, pose and haptic interactions, including interactions requiring optional OpenXR extensions. `components/xr/interactionprofiles.cpp` parses the database, expands `/user/hand/*` into both hands and collects required extensions. `apps/openmw/mwvr/openxrinput.cpp` walks that database to dynamically create every corresponding OpenXR action and action space in separate Lua, Pose and Haptics action sets. Before `xrSuggestInteractionProfileBindings`, bindings are filtered against enabled profile/interaction extensions and actually available paths. All action sets are then attached in the single `xrAttachSessionActionSets` call allowed by OpenXR. This avoids hard-coded Vive/Touch/Index branches inside gameplay code.\n\nSEMANTIC INPUT / HANDEDNESS / SCRIPT EXTENSION: `files/data/scripts/omw/vr/inputs/common.lua` enumerates the runtime-supported interaction paths exposed by the engine, creates raw per-path Lua input actions, splits 2D axes into independently bindable left/right/up/down semantic ranges, applies a 20% dead zone, and loads different per-interaction-profile defaults for right- and left-handed modes. It then maps those device paths to higher-level OpenMW actions/triggers grouped into gameplay/menu interaction sets. It even scans OpenMW settings after startup so mod-added input bindings can be surfaced into the VR binding UI. `apps/openmw/mwlua/vrbindings.cpp` exposes input values, interaction-profile names, derived spaces, frame-gated space location and haptic outputs to Lua. Haptic output is real OpenXR plumbing (`xrApplyHapticFeedback` with clamped amplitude), although this source snapshot does not contain a built-in gameplay system that calls the Lua output API.\n\nHANDS / ANIMATION: this is not full-body IK and not skeletal-finger tracking. `VRAnimation::TrackingController` locates each selected AIM space in world coordinates, converts it to a Morrowind-friendly base wrist orientation, removes the authored wrist child translation, applies user hand calibration and writes the tracked result onto the existing forearm transform. `HandController` overrides the hand-bone rotation with weapon-class-specific comfort angles; `FingerController` can straighten the first two index-finger bones for pointing by temporarily bypassing nested animation callbacks. In `VM_VRFirstPerson`, `updateParts` explicitly removes the head, hair, arms, torso, legs and other body parts, retaining the tracked hand presentation. Controllers are attached/removed cleanly when interaction-profile activity changes. This is a direct animation graft, not an elbow/shoulder/body solver.\n\nWEAPON / MAGIC AIM: a `WeaponDirectionController` creates one explicit aim transform parented under the right-hand model. For bows, crossbows, thrown weapons, spells, arrows/bolts and hand-to-hand it cancels the hand's comfort rotation and produces a stable forward aim; melee weapon presentation instead points up from the hand. Native gameplay code consumes that transform. `mwrender/weaponanimation.cpp::releaseArrow` changes the player projectile orientation to the VR aim node while keeping Morrowind's native charge-derived speed, projectile creation, inventory removal and bow/ammo logic. Thrown weapons use the actual animated weapon node position as launch position and still use native min/max throw speed from `attackStrength`; controller velocity is not used as throw speed. `mwworld/projectilemanager.cpp::launchMagicBolt` substitutes the preferred controller pose for player spell origin/orientation, while `World::castSpell` can raycast from the VR aim node. This is a high-value adapter pattern: override only spatial origin/direction at the native projectile/cast seam and leave damage, projectile state, enchantment, inventory and spell systems authoritative.\n\nREALISTIC MELEE: `apps/openmw/mwvr/realisticcombat.cpp` is an explicit Ready -> Launch -> Swing -> Impact -> Cooldown state machine. Crucially, it locates the tracked weapon hand in OpenXR LOCAL space, specifically so character/world movement does not contaminate measured swing speed. On tracking reacquisition it resets the previous position before calculating velocity to prevent a bogus high-speed strike. Weapon orientation defines thrust, sharp-edge and side axes; movement velocity is projected onto those axes to classify thrust/chop/slash, with weapon-class rules rejecting invalid blunt-side attacks. A minimum velocity arms the attack, a minimum traveled distance transitions Launch->Swing, peak velocity maps to attack strength, and falling below the threshold registers a miss. During Swing, `World::getVRMeleeHitContact` uses Morrowind's native weapon/hand reach and the VR aim node to query the existing physics `getHitContact`; a contact goes through native `evaluateHit` and `Class::hit(..., vr=true)`. It is physical velocity-driven melee, but the contact test is the engine's directional reach query rather than a swept weapon-volume solver.\n\nWORLD POINTER / PHYSICAL INTERACTION: `UserPointer` uses a `VR::SpaceTransform` sourced from a tracked space, raycasts through `Util::getPoseTarget`, respects native activation distance/telekinesis rules and distinguishes 3D GUI from world geometry. Activation adapts to native game state instead of inventing a second interaction system: drag/drop uses OpenMW's item model to place/drop into the world, console mode selects the object, inventory/container mode picks it up, normal activation calls the Lua manager's native `objectActivated`, and equipped lockpicks/probes reuse the existing `MWMechanics::Security` pick/probe logic. Placement additionally rejects wall-like surfaces by requiring the hit normal to be within 30 degrees of world up. This is a controller-ray-to-native-semantics bridge.\n\nVR GUI: MyGUI is decomposed into named VR layers. Each `VRGUILayer` creates a filtered MyGUI camera and `GUIRTT`, computes the bounding rectangle of the actual widgets/Lua elements, optionally auto-sizes physical extent from pixels-per-meter, and textures stereo-aware OSG quad geometry placed in a configured tracked/derived space. Pickable versus non-intersectable node masks keep controller rays from hitting decorative layers. `VRGUIManager::updateFocus` identifies a hit layer from OSG user data; `computeGuiCursor` maps the local quad hit back through the cropped rectangle into native MyGUI pixel coordinates. The ordinary mouse manager then receives cursor/mouse-wheel state, and clicks first attempt the existing MyGUI widget click path before falling back to native SDL mouse events. `VrVirtualKeyboard` is wired to MyGUI `EditBox` focus and injects ordinary MyGUI key/text events. The code contains `VR::QuadLayer` support scaffolding, but in this supplied source `mVrLayer` is default-null and no assignment was found; the live path therefore uses textured stereo world geometry rather than active OpenXR compositor quad layers.\n\nUI COMFORT / STATE: Lua VR UI code intentionally does not continuously drag menus after the controller/head. `ui/player.lua` captures/updates reference poses when the user enters a paused GUI state, when visible layer arrangement changes, or on recenter; otherwise the existing pose is frozen because continuously tracking the UI is described as uncomfortable/impractical. This is a useful state rule for diegetic/world menus: sample the desired anchor at state transition, then leave the panel stable until another deliberate transition.\n\nLOCOMOTION / TURNING / CROUCH: the baseline OpenMW movement model remains authoritative. Snap turn writes `self.controls.yawChange` in configured angular increments; smooth turn writes a frame-scaled yaw delta from semantic LookLeft/LookRight ranges, so both feed OpenMW's normal player control path instead of applying a renderer-only yaw. Physical sneak compares tracked VIEW height against a recenter/reference pose and returns that result through the ordinary `Sneak` action, optionally OR-ing it with conventional input. Hand-directed movement is implemented lower in the engine: `VRAnimation::updateSpace` locates the chosen hand AIM relative to VIEW, derives hand pitch/yaw without roll, stores it in `VR::Session::movementAngleOffset`, and `mwphysics/mtphysics.cpp` adds that offset to the player physics rotation before native movement simulation. The supplied source does not expose a Doom-style collision-reconciled roomscale translation system; physical tracking is anchored to the native player world pose rather than directly moving the collision body from HMD X/Y displacement.\n\nPOSTPROCESS / MIRROR: the VR viewer owns a multiview framebuffer even when brute-force stereo is used, and blits the resolved per-eye color/depth into acquired XR swapchain images. A configurable desktop mirror can show left, right or both eye targets. Postprocessing gets a VR-specific ping-pong callback so the last full-screen pass resolves into the correct current VR destination rather than the ordinary window FBO. In multiview the callback addresses the center/multiview target; in sequential stereo it chooses left/right based on the frame-pass ordering. This is a practical example of preserving an existing postprocess graph while changing only the final destination and depth-export seam.\n\nMULTIPLAYER / NETWORKING: this OpenMW-VR source is the ordinary single-player OpenMW engine fork. No XR hand/head pose replication path is present in the supplied source, so remote VR avatar reconstruction/network packet design should not be inferred from it.\n\nREUSABLE ARCHITECTURE: OpenXR session/predicted frame -> frame-gated cached spaces/actions -> VIEW/LOCAL tracking -> explicit LOCAL-to-game-world anchor -> tracked camera and hand/forearm graft -> semantic OpenMW actions plus native physics -> native projectile/spell/melee/activation systems; in parallel, asymmetric eye views -> OSG brute-force or multiview stereo -> conservative stereo culling/postprocess -> optional depth -> OpenXR projection submission. The source's strongest general lesson is to keep XR timing, coordinate conversion, game-world anchoring, animation presentation and native gameplay authority as separate seams with explicit data contracts.\n\nEVIDENCE BOUNDARIES: VERIFIED FROM SOURCE for the OpenXR frame loop, stereo/multiview projections, swapchains/interops, coordinate conversion/reference spaces, camera/world anchor, action database, Lua input bridge, tracked forearm/hand graft, projectile/spell seams, realistic melee, pointer/UI, native turning/sneak/hand-directed movement and postprocess/depth route. VERIFIED FROM BUNDLED DOCUMENTATION for user-facing VR setup/realistic-combat descriptions. NOT ESTABLISHED / NOT IMPLEMENTED IN THIS SNAPSHOT: full-body IK, OpenXR skeletal-finger retargeting, controller-velocity throw speed, swept weapon-volume melee, remote XR pose networking, collision-driven roomscale body translation, or an active GUI `VR::QuadLayer` path. The source contains compositor-layer scaffolding, but `mVrLayer` is never assigned in the supplied tree.\n\nIMPORTANT SOURCE FILES: `components/xr/session.cpp`, `platform.cpp`, `space.cpp`, `interactionprofiles.cpp`, `typeconversion.cpp`, `components/vr/session.cpp`, `viewer.cpp`, `directx.cpp`, `components/stereo/stereomanager.cpp`, `frustum.cpp`, `apps/openmw/mwvr/openxrinput.cpp`, `vranimation.cpp`, `realisticcombat.cpp`, `vrgui.cpp`, `vrpointer.cpp`, `vrutil.cpp`, `vrinputmanager.cpp`, `vrvirtualkeyboard.cpp`, `vrpingpongcallback.cpp`, `apps/openmw/mwrender/camera.cpp`, `weaponanimation.cpp`, `postprocessor.cpp`, `pingpongcanvas.cpp`, `apps/openmw/mwworld/worldimp.cpp`, `projectilemanager.cpp`, `apps/openmw/mwphysics/mtphysics.cpp`, `files/openxrinteractionprofiles.xml`, and Lua VR input/UI modules.";
CODE_AUDITS["pattern_openmwvr_scriptable_vr_surface"] = "VERIFIED FROM SOURCE. `mwlua/vrbindings.cpp` exposes supported interactions, active controller/profile state, raw input values, derived-space creation, space location, world-space location and haptic output. Space location from Lua is subject to the same frame-gating rule as native C++ and throws outside `onVRFrame`, preserving timing correctness across language boundaries. Lua UI code uses derived spaces to place layers relative to head/hands/world and input scripts use the same path database to build semantic actions. Haptic output clamps intensity and routes to `xrApplyHapticFeedback`; this snapshot exposes the mechanism but does not demonstrate built-in gameplay calls to it. Reusable rule: a scripting API should expose *validated spaces/actions*, not raw runtime handles, and should inherit the engine’s timing/lifecycle invariants.\n\nSOURCE AUDIT FILES: `apps/openmw/mwlua/vrbindings.cpp`; `apps/openmw/mwvr/openxrinput.cpp`; Lua modules under `files/data/scripts/omw/vr`. Key API: interaction/profile discovery, derived spaces, frame-gated locate, world locate and `_setOutputValue` -> `ActionSet::applyHaptics` -> `xrApplyHapticFeedback`.\n\nGENERALIZATION: Make XR concepts first-class scripting primitives so per-game/per-mod VR behavior can be authored above the engine without duplicating runtime plumbing.";


// ---- CyberpunkVR focused subsystem methodology entries (source audit 2026-10-10) ----
CODE_AUDITS["pattern_cyberpunk_staged_hook_registry"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `Hooks/Registry.cpp` registers hooks from static constructors but stores the head in a function-local static to avoid initialization-order loss, then sorts by stage/order before installation. Stages include PreDevice, Boot and PostStereo. `Stereo/DetourRegistry.cpp` does the same for engine detours. `Stereo/EngineRvas.hpp` is an explicitly documented table of verified Cyberpunk2077.exe offsets rather than scattered constants, while individual patches check expected instruction bytes before modification.\n\nIMPLEMENTATION ARCHITECTURE: Create named installation stages around lifecycle boundaries that actually matter to the target engine. Keep every absolute address/signature in one build table with discovery notes. At each patch site verify the expected bytes or structural invariant, log ok/disabled/FAILED distinctly, and let a rejected patch disable only its dependent subsystem. This gives reverse-engineered VR code a traceable compatibility contract instead of optimistic writes into changed binaries.\n\nVALIDATION AND FAILURE MODES: Test a known supported executable, then intentionally alter one expected byte/RVA and verify only that hook fails. Verify static registration order changes do not alter final hook order. On a new game build, require re-verification of the centralized table before enabling patches.\n\nEXACT SOURCE SURFACE: `src/Hooks/Registry.cpp`, `src/Stereo/DetourRegistry.cpp`, `include/Stereo/EngineRvas.hpp`, `include/Utils/AobScanner.hpp`, `src/Main.cpp`. Important nuance: the project is not purely signature-scanned. It combines centralized build-specific RVAs, byte checks, RTTI/structural evidence and some scanner-based discovery. Treat the technique as verified-build integration, not as a universal pattern scanner.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";
CODE_AUDITS["pattern_cyberpunk_openxr_existing_d3d12"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `OpenXRManager.cpp` requires `XR_KHR_D3D12_enable`, queries OpenXR graphics requirements, and creates the XR session using the Cyberpunk process’s captured `ID3D12Device` and `ID3D12CommandQueue`. It creates PRIMARY_STEREO views plus LOCAL and VIEW reference spaces. Runtime selection remains OpenXR: SteamVR support is implemented by selecting SteamVR’s OpenXR runtime manifest before instance creation, not by adding a separate OpenVR compositor path.\n\nIMPLEMENTATION ARCHITECTURE: Hook graphics creation early enough to retain the engine device/queue, then initialize XR against those exact objects. Keep runtime selection before `xrCreateInstance`; enumerate extensions before assuming optional depth support. This avoids cross-device copies and keeps the game renderer authoritative while XR owns headset presentation.\n\nVALIDATION AND FAILURE MODES: Validate adapter/device identity, D3D12 graphics requirements, queue lifetime, runtime switching before instance creation, and teardown order. Test runtime failure without leaving stale D3D objects or an active session. Do not call an OpenVR runtime-selection helper evidence of an OpenVR rendering backend.\n\nEXACT SOURCE SURFACE: `src/Runtimes/OpenXRManager.cpp`, `src/Main.cpp`, `src/Runtimes/OpenXRCapture.cpp`. Optional `XR_KHR_composition_layer_depth` is enabled only when advertised; color presentation remains valid without it.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";
CODE_AUDITS["pattern_cyberpunk_runtime_paced_submit_thread"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `OpenXRFrameLoop.cpp` owns the XR cycle: `xrWaitFrame`, `xrBeginFrame`, one target locate time, view/controller location, image transfer, and `xrEndFrame`. The code can move XR pacing to a dedicated submit thread because SteamVR-style pacing can block the game’s Present path. If the game has no new completed frame, it can re-submit the most recent completed snapshot using that snapshot’s own render pose rather than pretending fresh pixels were rendered at a new pose.\n\nIMPLEMENTATION ARCHITECTURE: Choose one owner for `xrWaitFrame`/`xrBeginFrame`/`xrEndFrame`. Publish the predicted target time to camera/tracking consumers. If compositor cadence exceeds game cadence, treat a repeated frame as an immutable image+pose transaction; never pair an old image with the newest head pose. Use bounded synchronization/resource leasing so the game cannot overwrite a texture still consumed by the submitter.\n\nVALIDATION AND FAILURE MODES: Test runtimes with different pacing behavior, game FPS below headset refresh, missing/new frames, pause/loading transitions and thread teardown. Verify repeated images retain their original render-pose identity and that Present no longer blocks on runtime pacing when submit-thread mode is active.\n\nEXACT SOURCE SURFACE: `src/Runtimes/OpenXRFrameLoop.cpp`, `src/Runtimes/OpenXRPresent.cpp`, `src/Runtimes/OpenXRCapture.cpp`. The current source explicitly removes the older custom motion-prediction/AER assumptions. Runtime predicted display time plus compositor reprojection are the normal late-motion stages.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";
CODE_AUDITS["pattern_cyberpunk_pose_image_identity"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `Camera/ImagePoseIdentity.cpp` and the OpenXR capture/submit path maintain identity for rendered resources. The existing source audit records `StoreRenderEyePose`/rendered-pose queues keyed by engine sequence and matching MAIN/VRCAM capture serials. The identity is not just a pointer tag: resource reuse is accounted for so a recycled D3D object address cannot silently inherit a previous frame’s pose label. Recentered game-relative camera poses are converted back to the raw LOCAL-space form expected by OpenXR submission.\n\nIMPLEMENTATION ARCHITECTURE: Assign a monotonically meaningful frame/eye identity at render ownership, not at submit. Store render pose, tracking-origin serial and eye identity beside the image lease. Reject or fall back when the two eye serials do not belong together. When the game uses a recentered coordinate basis but the compositor expects runtime-local space, explicitly reverse the recenter transform before submitting the render pose.\n\nVALIDATION AND FAILURE MODES: Stress GPU lag, capture-buffer reuse, recenter events, repeated frames and missing one-eye captures. A CPU frame number alone is insufficient if the GPU can overwrite a shared resource before submission; verify identity follows the actual resource generation/lease.\n\nEXACT SOURCE SURFACE: `src/Camera/ImagePoseIdentity.cpp`, `include/Camera/ImagePoseIdentity.hpp`, `src/Runtimes/OpenXRCapture.cpp`, `src/Runtimes/OpenXRPresent.cpp`, `src/Runtimes/OpenXRFrameLoop.cpp`. This is one of the most reusable synchronization patterns in the project: render pixels and their render pose must have the same lifetime and ownership semantics.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";
CODE_AUDITS["pattern_cyberpunk_native_second_view_identity"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `Stereo/SyncStereo.cpp` drives an authored `entRenderToTextureCameraComponent` as a genuine REDengine view. `Stereo/VrcamSelection.cpp` selects/recognizes the VR camera by engine camera identity/name/hash and structural context. The architecture intentionally rejects the common shortcut “anything not VRCAM is MAIN”; reflection, desktop, braindance and other auxiliary views must pass without eye-specific mutations. The same camera path receives OpenXR eye geometry/projection rather than post-processing one mono render into stereo.\n\nIMPLEMENTATION ARCHITECTURE: Prefer the target engine’s own additional-camera/view mechanism when it can run the full world renderer. Give every view a stable semantic identity before applying projection, culling, temporal or HUD patches. Feed OpenXR eye offsets/FOV into only the two headset views and leave unrelated captures alone. Increase engine resource budgets such as descriptor capacity when an extra full view consumes allocations the flat game never provisioned.\n\nVALIDATION AND FAILURE MODES: Test mirrors/reflections, menus, scripted cameras, desktop output, braindance/device views and transitions. Log view identity during discovery so a new auxiliary camera cannot silently be mutated as an eye. Verify actual geometry/parallax is produced independently for both headset views.\n\nEXACT SOURCE SURFACE: `src/Stereo/SyncStereo.cpp`, `src/Stereo/VrcamSelection.cpp`, `src/Hooks/LocateCamera.cpp`, `src/Hooks/PatchCamera.cpp`, `src/Hooks/FinalCamera.cpp`. OpenXR asymmetric/canted eye geometry is injected into the engine camera path; this entry is not a depth-reprojection or mono-to-stereo technique.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";
CODE_AUDITS["pattern_cyberpunk_framegraph_feature_reconcile"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `Stereo/FrameGraph.cpp` and companion stereo modules observe REDengine’s per-view feature bits and graph behavior. The source audit records that REDengine regenerates those flags each frame, so VRCAM-required groups must be reasserted at the writer. The project separates per-view needs such as culling/depth/composition from frame-global or shared resources; simply copying MAIN state or rerunning every node caused eye disagreements and missing dependencies.\n\nIMPLEMENTATION ARCHITECTURE: For each engine graph feature, identify whether it is (a) a per-view producer that must run, (b) a per-view consumer whose prerequisite must exist, or (c) frame-global state that should be shared. Instrument MAIN and second-view feature masks and node execution, then patch the authoritative per-frame writer rather than a one-time initialization value.\n\nVALIDATION AND FAILURE MODES: Validate daylight/interiors, scanner/vision modes, dynamic weather, effects and any state that changes graph feature bits. Check both missing producer failures and accidental duplicate frame-global work. Treat “feature flag present” and “valid resource produced for this view” as separate questions.\n\nEXACT SOURCE SURFACE: `src/Stereo/FrameGraph.cpp`, `include/Stereo/FrameGraphFeatures.hpp`, `src/Stereo/NodeDispatch.cpp`, `include/Stereo/EngineRvas.hpp`. Reusable distinction: enabling a consumer flag does not prove its inputs were built for that view. Audit producer/consumer ownership explicitly.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";
CODE_AUDITS["pattern_cyberpunk_shared_view_reuse"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `Stereo/ViewReuse.cpp` exists specifically to coordinate resources that REDengine naturally treats as shared/once-per-frame. The source audit documents examples including sun/shadow cascades, foliage/wind, environment/composition and other resources whose independent second-eye execution can either waste work or leave the two views on different global state. Other data such as view-dependent depth/culling must remain per-eye.\n\nIMPLEMENTATION ARCHITECTURE: Build a classification table for render products: frame-global reusable, view-dependent, or view-dependent consumer of shared global data. For reusable products, transfer or reference the completed MAIN result at the precise engine seam expected by VRCAM. For view-dependent products, rerun with VRCAM matrices. Avoid “copy all” and “rerun all” because both erase important ownership distinctions.\n\nVALIDATION AND FAILURE MODES: Profile correctness before performance. Verify shared resources are complete before VRCAM consumes them, are not mutated concurrently, and remain valid when render order changes. Compare temporal consistency and GPU cost across weather, foliage, shadows and vision effects.\n\nEXACT SOURCE SURFACE: `src/Stereo/ViewReuse.cpp`, `src/Stereo/FrameGraph.cpp`, `src/Stereo/Grading.cpp`, `src/Stereo/VisionLayer.cpp`, `include/Stereo/EngineRvas.hpp`. The reusable lesson is the ownership taxonomy; the exact resources named by this project are REDengine-specific.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";
CODE_AUDITS["pattern_cyberpunk_per_eye_temporal_history"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `Stereo/Dlss.cpp` plus `Hooks/Ngx.cpp`/resolution hooks route VRCAM through separate Streamline/DLSS view state. The source audit explicitly identifies reuse of MAIN’s temporal/upscaler viewport as invalid for true stereo because history from one eye would feed the other. The implementation also coordinates feature-group selection and per-view dimensions when MAIN uses DLSS.\n\nIMPLEMENTATION ARCHITECTURE: Treat temporal history as part of view identity. Every eye needs its own history key/context, jitter sequence interpretation, dimensions and reset policy. If a third-party temporal system is keyed by “viewport”, create or route a distinct second-eye viewport instead of only changing camera matrices around one shared history object.\n\nVALIDATION AND FAILURE MODES: Test camera motion, disocclusion, resolution changes, DLSS on/off, menu transitions and history reset. Look specifically for ghost trails that jump between eyes or converge toward the other eye’s previous frame.\n\nEXACT SOURCE SURFACE: `src/Stereo/Dlss.cpp`, `src/Hooks/Ngx.cpp`, `src/Hooks/DlssRes.cpp`. Independent temporal ownership applies to TAA/upscalers generally even though the concrete integration here is Streamline/DLSS.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";
CODE_AUDITS["pattern_cyberpunk_native_hud_stereo_panel"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `Stereo/Hud.cpp` and `Render/HudPanel.cpp` handle native HUD composition for the second eye; the main source audit notes that the native plugin performs the part an external HUD editor cannot: getting the engine’s own HUD composite into VRCAM. CET/redscript modules then handle aspect/layout policies for specific interfaces, while HUDitor owns individual widget transforms. The implementation therefore separates render transport from UX placement.\n\nIMPLEMENTATION ARCHITECTURE: Hook the engine’s final HUD/composite surface rather than recreating game state in a parallel UI. Duplicate that surface into the headset view(s), choose zero-disparity or finite-distance placement intentionally, and expose placement/layout to a higher-level policy layer. Avoid having two systems both rewrite the same widget hierarchy.\n\nVALIDATION AND FAILURE MODES: Test subtitles, phone/list interfaces, scanner, dialogue, tutorials, world map and F10 overlay. Verify UI remains readable in both eyes and native state updates once. Exercise resize/aspect changes and scene transitions without stale panels.\n\nEXACT SOURCE SURFACE: `src/Stereo/Hud.cpp`, `src/Render/HudPanel.cpp`, `mods/cet/CyberpunkVRPort_WorldMap/init.lua`, `mods/cet/CyberpunkVRPort_WristHud/init.lua`. This is native HUD reuse/spatialization, not proof that every Cyberpunk widget is individually reconstructed by the C++ layer.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";
CODE_AUDITS["pattern_cyberpunk_world_marker_stereo_depth"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `Hooks/WorldMarkers.cpp` and `Render/WorldMarkerProjection.hpp` provide a dedicated world-marker path. The source separates ordinary HUD duplication from markers that originate in world space and therefore need eye-specific projection. Marker shader code is kept separate from the flat HUD path so world-linked elements can respect stereo camera geometry.\n\nIMPLEMENTATION ARCHITECTURE: Classify UI elements by semantic space. Pure HUD can share a comfortable panel plane, but world annotations must start from a world position and pass through each eye’s view/projection. Keep depth/visibility policy explicit so a marker is not merely rendered at different pixels while still behaving like a flat overlay.\n\nVALIDATION AND FAILURE MODES: Test near/far markers, large IPD/world-scale changes, canted/asymmetric FOV, camera takeover states and occlusion/depth policy. Confirm left/right projected positions converge with distance and do not inherit stale MAIN matrices.\n\nEXACT SOURCE SURFACE: `src/Hooks/WorldMarkers.cpp`, `include/Render/WorldMarkerProjection.hpp`, `src/Render/WorldMarkerShader.cpp`. The source establishes a distinct stereo marker projection subsystem; exact game marker classes and occlusion behavior remain title-specific.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";
CODE_AUDITS["pattern_cyberpunk_animation_epoch_vrik"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `Hooks/AnimPose.cpp` detours the pose-apply path and measures/identifies fresh animation epochs. The existing source audit records that one fresh VRIK solve is cached for relevant bones and replayed on later pose passes in the same batch. Two-hand authored-pose capture occurs before VR writes, and ownership transitions invalidate the cache so a pose from the previous owner is not replayed after control changes.\n\nIMPLEMENTATION ARCHITECTURE: Find the engine’s true animation evaluation boundary. On the first local-player pose application in a new epoch, solve tracked-body IK and cache the resulting bone transforms. On duplicate render/animation passes for that same epoch, replay the cached result rather than sampling controllers again or recomputing against a different camera state. Invalidate on ownership/lifecycle transitions.\n\nVALIDATION AND FAILURE MODES: Log pose-apply timings and epoch IDs. Test multiple render views, pause/resume, camera takeovers, weapon/vehicle transitions and any path that applies the same skeleton more than once. Look for one-eye/one-pass body phase errors.\n\nEXACT SOURCE SURFACE: `src/Hooks/AnimPose.cpp`, `src/Anim/CharacterRig.cpp`, `include/Anim/VrikState.hpp`. This solves an engine phase problem: renderer frame count and animation evaluation count are not necessarily the same clock.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";
CODE_AUDITS["pattern_cyberpunk_full_body_planted_feet"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `Anim/CharacterRig.cpp` contains the body placement solver described in the existing source audit: capture foot positions, infer physical squat/drop from HMD height with filtering/deadzone/clamp, move the hips under the head anchor while retaining torso length, perform repeated spine/neck correction to reduce head residual, solve both legs back to planted feet with forward-knee constraints, and rotate the head bone to the VR camera. Body yaw remains a separate heading policy.\n\nIMPLEMENTATION ARCHITECTURE: Separate root placement, vertical crouch mapping and facing direction. Preserve pre-solve foot contacts as IK targets, reposition pelvis/torso to satisfy the tracked head, then solve legs back to the contacts. Distribute remaining head error across spine/neck rather than telescoping one bone. Publish solved landmarks for interaction systems instead of making every script rediscover them.\n\nVALIDATION AND FAILURE MODES: Test standing, crouching, leaning, turning in place, uneven animation states and large height calibration differences. Verify body-root yaw does not chase every small HMD yaw and that feet do not drift when the player bends.\n\nEXACT SOURCE SURFACE: `src/Anim/CharacterRig.cpp`, `src/Hooks/AnimPose.cpp`, `include/Anim/VrikState.hpp`. The source demonstrates a full local-body visual IK solve, not physics-driven tracked legs or external waist/foot trackers.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";
CODE_AUDITS["pattern_cyberpunk_anatomical_arm_ik"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `CharacterRig.cpp` scales upper-arm/forearm rest translations toward measured user arm length within safety clamps. Its arm solve uses body axes to construct an anatomical bend plane, handles cross-body and near-extension cases, adds clavicle/shoulder protraction for far reaches, distributes twist and applies wrist calibration after converting XR controller pose into avatar/model space. The hand target can also be stopped/clamped by interaction ownership such as reload.\n\nIMPLEMENTATION ARCHITECTURE: Calibrate skeleton segment lengths first, then solve target position in a stable body/model frame. Let the shoulder girdle contribute near maximum reach; calculate an elbow pole from torso anatomy rather than a fixed world vector; smooth the pole/twist and handle near-singular extension. Keep raw tracked pose global, and apply calibration/collision constraints only in the arm consumer.\n\nVALIDATION AND FAILURE MODES: Test cross-body reach, hand behind/above head, near-full extension, two-handed weapons, handedness and abrupt tracking loss. Verify calibration changes the avatar arm geometry rather than merely multiplying controller offset.\n\nEXACT SOURCE SURFACE: `src/Anim/CharacterRig.cpp`, `src/Hooks/AnimPose.cpp`, `include/Anim/VrikState.hpp`. Filtering at the visual arm/attachment layer preserves low-latency raw controller state for gameplay systems that need it.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";
CODE_AUDITS["pattern_cyberpunk_roomscale_body_yaw"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `Hooks/RoomscaleMove.cpp`, `Hooks/OnFootMoveXY.cpp` and camera/body-heading code separate consumed physical HMD displacement from engine/world locomotion. Movement sources can be Game, HMD, LeftHand or RightHand; hand-relative movement uses controller aim orientation. Optional physical body rotation writes headset yaw through the engine heading channel so mesh/collision/weapon/movement share facing while the HMD remains an additive view transform.\n\nIMPLEMENTATION ARCHITECTURE: Maintain explicit values for tracking-space displacement, the portion already consumed into player movement, render-camera offset and body heading. Convert roomscale delta into the engine’s native movement/heading interface, then remove only the consumed component from camera anchoring. For yaw, feed intentional physical rotation to the body/engine while never feeding that body yaw back into the headset view.\n\nVALIDATION AND FAILURE MODES: Test walking around the play area, artificial movement at the same time, snap/smooth turning, hand-relative locomotion, recenter and transitions into vehicles/cinematics. Look for double translation, orbiting camera or body yaw feedback loops.\n\nEXACT SOURCE SURFACE: `src/Hooks/RoomscaleMove.cpp`, `src/Hooks/OnFootMoveXY.cpp`, `src/Hooks/BodyYawFollow.cpp`, `include/Hooks/RoomscaleMove.hpp`. No teleport system is established by these files. This is continuous/roomscale integration and heading ownership.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";
CODE_AUDITS["pattern_cyberpunk_physicalray_spread_rotation"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `Hooks/WeaponAim.cpp` and `docs/cp2077-hitscan-physicalray-muzzle.md` identify `gameEffectObjectProvider_PhysicalRay::Execute` callsites as the production firearm ray path. The wrapper calls the original evaluator, verifies the effect belongs to the local player weapon, sanity-checks the current VR muzzle against the native origin, moves origin to the muzzle, snapshots both the native cone center and muzzle forward, and rotates each already-generated ray by the camera-cone→barrel-cone rotation.\n\nIMPLEMENTATION ARCHITECTURE: Hook as late as possible after the game has generated authoritative projectile/spread rays. Preserve each ray’s angular offset inside the cone, but rotate the entire cone to the physical barrel and move origin to the live muzzle. Filter for the local player/weapon and reject stale muzzle data using spatial/time invariants. Leave ammo, fire rate, damage and hit processing native.\n\nVALIDATION AND FAILURE MODES: Test single-ray guns, shotguns, hip fire, ADS, recoil, weapons with unusual muzzle offsets and stale/unarmed weapon state. A shotgun should retain pellet distribution, not collapse into one ray. Validate that foreign PhysicalRay users are untouched.\n\nEXACT SOURCE SURFACE: `src/Hooks/WeaponAim.cpp`, `docs/cp2077-hitscan-physicalray-muzzle.md`. Weapon visual pose, muzzle transform and projectile ray are intentionally separate data paths; do not assume moving the model alone changes combat.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";
CODE_AUDITS["pattern_cyberpunk_authored_twohand_grip"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `Anim/TwoHandGrip.cpp` captures one native two-hand animation frame with VRIK disabled and stores support-wrist transform relative to the primary wrist plus finger rotations in per-weapon INI files. Runtime reconstructs that support point from the live primary wrist, previews by proximity and commits on a fresh/unspent grip edge. Aim correction uses support-hand tracking error with smoothing/deadzone/caps and leverage weighting: long rifle baselines can steer strongly; short pistol baselines deliberately receive less angular authority.\n\nIMPLEMENTATION ARCHITECTURE: Provide a calibration/capture mode that samples the target game’s authored hold before VR overwrites the pose. Store the relative support transform and finger pose as weapon data. At runtime arbitrate grip ownership before activation, then constrain/steer the weapon based on support-hand error. Scale steering authority by hand separation to prevent centimeters of noise from creating huge pistol rotations.\n\nVALIDATION AND FAILURE MODES: Test capture/reload of configs, weapon aliases/reskins, grip/release edges, very short and long baselines, support hand crossing the primary hand, and conflicts with reload/holster/wheel interactions. Ensure a single grip press cannot be spent by two systems.\n\nEXACT SOURCE SURFACE: `src/Anim/TwoHandGrip.cpp`, `include/Anim/TwoHandGrip.hpp`, `mods/config/CyberpunkVR_TwoHandGrip_lexington.ini`. The supplied source tree contains many per-weapon capture/config files; these are data for one shared mechanism rather than separate algorithms.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";
CODE_AUDITS["pattern_cyberpunk_hand_recoil_ads_optics"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `Anim/Recoil.cpp` implements a damped spring where shots add velocity impulse and integration uses bounded small substeps; per-weapon/class tuning and two-hand support scale the response. `AdsEyeAlign.cpp`/`AdsMuzzleStabilizer.cpp` adapt the game’s authored ADS transition around an eye/weapon pivot without letting it redirect the live muzzle. `Shaders/sight_reflex_ps.hlsl` computes reticle displacement from eye-to-sight geometry so the dot behaves like a collimated optic rather than a decal stuck to glass.\n\nIMPLEMENTATION ARCHITECTURE: Apply firing impulse to the visual/IK weapon owner, not to head/camera orientation. Integrate a damped spring with stable timestep behavior and let support-hand leverage attenuate it. For ADS, preserve native state/animation but reconcile it against the actual dominant-eye line. For reflex optics, calculate reticle direction from the eye and sight optical frame and pass stable world-size/calibration data explicitly.\n\nVALIDATION AND FAILURE MODES: Test rapid automatic fire at variable FPS, one- vs two-hand grip, entering/exiting ADS, head translation around the sight and temporal-upscaler jitter. The reticle should stay optically collimated while the gun recoils independently of the HMD.\n\nEXACT SOURCE SURFACE: `src/Anim/Recoil.cpp`, `src/Anim/AdsEyeAlign.cpp`, `src/Anim/AdsMuzzleStabilizer.cpp`, `src/Shaders/sight_reflex_ps.hlsl`. No camera-kick requirement is inferred; the source intentionally implements weapon/hand recoil for comfort.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";
CODE_AUDITS["pattern_cyberpunk_data_driven_physical_reload"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `mods/cet/CyberpunkVRPort_Reload/reload/reload.lua` is the shared state/geometry layer. It consumes live weapon-rig part transforms from the native pose bridge and models magazine grab/extraction/carry/insertion/drop plus slide/palm interaction. Magazine travel follows the well/path; slide travel projects hand motion onto the measured slide/barrel axis. Finger poses, wrist lock/hand stop and ownership state keep the hand attached to the manipulated part. Weapon-specific modules provide geometry/pose data. `revolver.lua` treats a cylinder/speedloader/cases as a distinct mechanism rather than forcing it through box-magazine logic.\n\nIMPLEMENTATION ARCHITECTURE: Define a small mechanism state machine around physical thresholds, not animation time. Convert controller/hand motion into weapon-local space; constrain moving parts to their mechanical rails/axes; keep ammo/action/audio commits at explicit state transitions. Store per-weapon wells, paths and hand/finger poses as data. When a weapon family has a different topology—such as a revolver—provide a mechanism adapter with the same external ownership contract.\n\nVALIDATION AND FAILURE MODES: Test grabbing before/after empty, dropping and regrabbing a magazine, partial insertion, slide manipulation, handedness, tracking discontinuity and grip conflicts. Verify native auto-reload cannot race the physical state. For revolvers, test individual case retention/ejection and speedloader transitions separately.\n\nEXACT SOURCE SURFACE: `mods/cet/CyberpunkVRPort_Reload/reload/reload.lua`, `mods/cet/CyberpunkVRPort_Reload/reload/revolver.lua`, `src/Hooks/AnimPose.cpp`, `src/Anim/ReloadPose.cpp`. The source demonstrates tuned weapon modules plus a shared core. Exact ammo/audio calls remain Cyberpunk-specific; the portable lesson is geometry/state separation and explicit interaction ownership.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";
CODE_AUDITS["pattern_cyberpunk_motion_melee_native_authority"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `CyberpunkVRPort_Weapon/init.lua` gates blade contact on physical weapon velocity. `mods/redscript/CyberpunkVRPort_Melee/vrport_melee.reds` models the blade as a finite segment, caps physical reach below flat-game lunge range, samples candidate NPC body heights and chooses the closest valid contact with a per-target repeat cooldown. It then builds the weapon’s own `Attack_GameEffect`; a damage-calculation bridge restores the intended queued melee damage before native armor/crit/marker processing when script-initiated attacks would otherwise be zeroed.\n\nIMPLEMENTATION ARCHITECTURE: Separate recognition from authority. First require credible swing speed and segment/body contact. Once accepted, call the target game’s normal attack/effect system using the equipped weapon record, instigator and contact direction rather than applying raw health damage. Add a minimal compatibility bridge only where the engine rejects an otherwise native effect because its original button-driven state machine was bypassed.\n\nVALIDATION AND FAILURE MODES: Test slow touches, fast slash through multiple targets, repeat contact on one NPC, reaching to holster, blocked/armored targets and failure to create the native attack effect. Confirm effects/reactions/damage numbers come from native combat rather than duplicate VR code.\n\nEXACT SOURCE SURFACE: `mods/cet/CyberpunkVRPort_Weapon/init.lua`, `mods/redscript/CyberpunkVRPort_Melee/vrport_melee.reds`, `mods/redscript/CyberpunkVRPort_WeaponUp/vrport_weapon_up.reds`. The fallback queued hit is secondary; the high-confidence production methodology is spatial intent -> native `Attack_GameEffect`/DamageSystem.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";
CODE_AUDITS["pattern_cyberpunk_body_relative_holsters"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `CyberpunkVRPort_Holster/init.lua` consumes solved/published wrist-to-body anchors for right hip, left hip and back zones. It supports visual-slot classification and a simpler fixed-slot mode, applies proximity/cooldown/cross-body rules, and suppresses holster logic during states such as smoking. The wider source audit records that wheel/reload/carry interactions can pre-claim the grip so reaching for another system does not accidentally equip or unequip a weapon.\n\nIMPLEMENTATION ARCHITECTURE: Publish stable torso/hip/back landmarks from the body solver. Define holster zones relative to those landmarks, not head/world coordinates. Before interpreting a grip edge as holster intent, run a central ownership/arbitration check against every higher-priority interaction. Once a zone transition is accepted, invoke the game’s native equipment action and impose a short cooldown/intent window so the same reach cannot become a melee swing.\n\nVALIDATION AND FAILURE MODES: Test crouch/lean/body-yaw changes, cross-body reaches, seated/vehicle states, simultaneous reload or steering grips, rapid enter/exit of a zone and visual-vs-simple slot mode. Confirm body calibration moves zones with the avatar rather than with the HMD alone.\n\nEXACT SOURCE SURFACE: `mods/cet/CyberpunkVRPort_Holster/init.lua`, `src/Anim/CharacterRig.cpp`, `src/Anim/TwoHandGrip.cpp`, `src/Anim/WheelGrab.cpp`. This is a semantic zone/arbitration pattern, not a claim that a physical holster mesh provides rigid-body collision.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";
CODE_AUDITS["pattern_cyberpunk_ladder_grip_climb"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `CyberpunkVRPort_Ladder/init.lua` explicitly says Lua bridges ladder geometry/state only; tracking and grip movement remain native. It reads the game `LadderDescription` and optional finisher-rail transforms and publishes them through `SetVRLadderState`/`SetVRLadderTopRails`. `LadderInput.cpp` builds both hands from the same latched body/view frame, locates closest rail/rung/top-rail contacts, uses grip hysteresis (release/press thresholds), anchors a held palm, rejects implausible tracking jumps, constrains the VRIK hand to the physical contact, and converts vertical tracked pull into a bounded native MoveY axis via `Climber::Debt()`. Near the top, an intentional upward pull can request the game’s own ladder finish rather than teleporting the player.\n\nIMPLEMENTATION ARCHITECTURE: Use the game’s authoritative ladder object to supply geometry and state. Convert tracked palm contact into explicit anchors only on a grip edge within a capture radius. While held, constrain visual IK to the anchor and accumulate player movement from controller motion in tracking space, then feed that as the game’s ordinary ladder input. Use origin/sequence freshness, grip hysteresis and motion discontinuity rejection. Let the native state machine perform top exit.\n\nVALIDATION AND FAILURE MODES: Test one- and two-hand climbing, grabbing rails vs rungs, releasing/regrabbing, moving the HMD while holding, tracking recenter/origin change, ladder switching, top finisher rails and manual stick input. The code cancels physical override when ordinary movement input is significant, which is an important coexistence check.\n\nEXACT SOURCE SURFACE: `mods/cet/CyberpunkVRPort_Ladder/init.lua`, `src/Natives/Ladder.cpp`, `src/Hooks/LadderInput.cpp`, `include/Runtimes/LadderClimbing.hpp`, `include/Anim/LadderRungWrist.hpp`. `Climber::Update` stores a target height and “debt” between tracked pull and current native ladder height, then outputs a bounded axis until the game catches up. `Constrain` converts the world-space palm anchor back into the body/model frame supplied by the caller, keeping visual hands attached without moving the skeleton in Lua.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";
CODE_AUDITS["pattern_cyberpunk_breaststroke_swimming"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `CyberpunkVRPort_Swimming/init.lua` bridges swimming/water state and merges only four actions (MoveY, ToggleSprint, Jump, Dive) for the local player. `SwimmingInput.cpp` samples both controller hands and head from one gesture frame. `SwimmingGesture.hpp` implements a Reach→Pull→Recover breaststroke with timing, travel, symmetry, velocity and discontinuity checks, a separate downward two-hand `AscendStroke`, provisional early propulsion that expires quickly if a stroke aborts, and boost hysteresis based on sustained filtered hand velocity. `SwimmingMovement.hpp` redirects native horizontal swim velocity by tracked head heading while intentionally preserving the game’s existing vertical component/buoyancy.\n\nIMPLEMENTATION ARCHITECTURE: Recognize gestures in tracking/head-local space so artificial/world movement does not invent a stroke. Require a stable ready/reach pose, then evaluate actual bilateral travel and velocity over time; reject tracking jumps and origin changes. Emit semantic native actions for a bounded glide, boost or ascent instead of directly setting world position. Preserve native vertical movement when the game already includes pitch/buoyancy to avoid double-applying it.\n\nVALIDATION AND FAILURE MODES: Test gentle/fast strokes, aborted partial pulls, moving the head without moving hands, tracking jumps, surface/diving transitions, existing fast-swim state, manual stick input and pausing. Verify a partial early pull cannot grant a full glide and that boost does not chatter on noisy velocity samples.\n\nEXACT SOURCE SURFACE: `mods/cet/CyberpunkVRPort_Swimming/init.lua`, `src/Natives/Swimming.cpp`, `src/Hooks/SwimmingInput.cpp`, `include/Runtimes/SwimmingGesture.hpp`, `include/Runtimes/SwimmingMovement.hpp`. `InstallActions` patches the Cyberpunk 2.31 action-table read only for this player’s swimming reads and validates expected bytes first; it does not replace the entire input table.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";
CODE_AUDITS["pattern_cyberpunk_wheel_animation_handoff"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `Anim/WheelGrab.cpp` detects hand proximity/grip at the authored wheel. When a hand grabs, the implementation captures/restores the animation-driven hand and returns that arm to the native driving pose, including rest translations so VRIK arm scaling/protraction does not distort the wheel contact. Steering derives from controller geometry with one- and two-hand variants, deadzone/lock-angle policy and wheel-hub horn proximity. Source comments emphasize that merely skipping an IK solve is insufficient if cached solves or translation writes still replay afterward.\n\nIMPLEMENTATION ARCHITECTURE: For interactions where authored animation is visually superior, transfer ownership at the consumer layer. On grab, restore the native/rest transforms required by the animation, invalidate any cached VR solve for that limb, and stop all competing translation/rotation writes. Continue using controller positions to compute semantic steering/horn/fire intent, then blend/reacquire VRIK on release.\n\nVALIDATION AND FAILURE MODES: Test one-hand/two-hand steering, hand entering/leaving the grab zone, weapon drawn while driving, throttle latch/trim, horn proximity and rapid grab transitions. Specifically verify no stale same-tick VRIK cache reattaches the arm after ownership was handed to animation.\n\nEXACT SOURCE SURFACE: `src/Anim/WheelGrab.cpp`, `include/Anim/WheelSteering.hpp`, `include/Anim/TrackedWheelSteering.hpp`, `src/Hooks/XInput.cpp`. This is a reusable animation-ownership lesson: “do not solve” is not equivalent to “give the engine ownership” unless every downstream replay/translation writer is also released.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";
CODE_AUDITS["pattern_cyberpunk_xinput_input_ownership"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `OpenXRManager.cpp` creates separate grip pose and aim pose actions plus stick, trigger, grip, click, face and menu actions with bindings for several controller profiles. `Hooks/XInput.cpp` merges VR state into Cyberpunk’s XInput path and contains gameplay-specific policies such as movement tiers, sprint detent, crouch/dash, scanner gesture and quickhack paging. Its comments explicitly require menus and braindance to receive raw controller behavior because VR remaps that are helpful in gameplay can steal buttons from UI.\n\nIMPLEMENTATION ARCHITECTURE: Define semantic XR actions first, then translate them at the legacy game-input boundary instead of patching every gameplay system. Maintain an input-ownership state machine: gameplay remaps/chords active only when gameplay owns input; UI/cinematic modes get ordinary controller values. Use head/hand-local geometry only for gestures, with hysteresis/debounce, and keep the actual action press in the native button channel.\n\nVALIDATION AND FAILURE MODES: Test opening/closing UI while buttons are held, scanner gesture near its boundary, sprint/crouch/dash state changes, quickhack paging and simultaneous physical interactions. Verify one gesture cannot leak a remapped button into a menu after the UI becomes active.\n\nEXACT SOURCE SURFACE: `src/Runtimes/OpenXRManager.cpp`, `src/Hooks/XInput.cpp`. The source does not establish `XR_EXT_hand_tracking` skeletal hand tracking or OpenXR haptic-output actions. This entry is motion-controller action translation.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";
CODE_AUDITS["pattern_cyberpunk_native_xr_framegen"] = "SOURCE-AUDITED CYBERPUNKVR METHODOLOGY. `Framegen/Inputs.cpp` hooks Streamline input publication and copies matching depth/motion resources into per-view records keyed by frame, pose, origin, view and command queue. `Framegen/Generator.cpp` uses FidelityFX frame interpolation/depth-motion inputs; the NVIDIA backend replaces only the optical-flow stage with NVIDIA OFA while retaining FidelityFX interpolation. `Framegen/Presenter.cpp` requires matching stereo/input identity, resets on tracking-origin/projection discontinuity, generates a midpoint image when two valid real frames can be interpolated, and assigns the synthetic frame a pose interpolated between the two real eye poses. It reuses the port’s existing color captures—no private XR swapchain or second presenter. `Framegen.cpp` adds output pacing plus real/generated/repeat CPU/GPU/VRAM telemetry.\n\nIMPLEMENTATION ARCHITECTURE: Capture interpolation inputs at the renderer point where their camera constants, depth and motion vectors are known, and key them to the same identity used for the color frame. Generate only when consecutive frames have compatible origin/projection and both eyes have valid inputs. Keep interpolation as a producer feeding the existing XR presenter; do not create a competing submission loop. For a synthetic midpoint, use a corresponding midpoint render-pose estimate rather than labeling it with either endpoint’s pose.\n\nVALIDATION AND FAILURE MODES: Test scene cuts/reset, menus/untracked views, projection/origin change, missing depth or motion vectors, GPU queue mismatch, low game FPS and external frame-generation layers. Verify generated/repeated/real frames are separately counted and that interpolation disables cleanly when inputs become incompatible.\n\nEXACT SOURCE SURFACE: `src/Framegen/Inputs.cpp`, `src/Framegen/InputCopy.cpp`, `src/Framegen/Generator.cpp`, `src/Framegen/Presenter.cpp`, `src/Framegen/Framegen.cpp`, `cmake/NativeFramegen.cmake`. `Generator.hpp` explicitly states that framegen consumes the port’s existing color snapshots and creates no private XR swapchains, duplicate color-capture ring, readback or second presenter. The CMake module pins FidelityFX frame interpolation/optical-flow components; NVIDIA OFA is an optional optical-flow source, not a separate interpolation/presentation architecture.\n\nEVIDENCE BOUNDARY: This record describes behavior directly supported by the supplied source snapshot. Portable recommendations are identified as transfer guidance rather than claims about every VR mod.";


// ---------- Skate 3 VR / ReXGlue source-audited subsystem expansion ----------
CODE_AUDITS["seed_skate3vr_case"] = "VERIFIED FROM THE USER-SUPPLIED SKATE3VR SOURCE SNAPSHOT.\n\nARCHITECTURE: This project has four separable layers: (1) ahead-of-time PowerPC-to-C++ code generation for the Xbox 360 executable/module set; (2) a ReXGlue runtime supplying Xbox-style memory, kernel/XAM, graphics, audio, input, exports and XEX launch semantics; (3) Skate-specific guest-function overrides and a native scene reconstruction path; (4) a same-device D3D12/OpenXR bridge installed at ReXGlue’s guest-output/presentation seam. It should not be described as “Xenia with an OpenXR hook” or as a runtime PPC JIT. ReXGlue explicitly says it is rooted in Xenia research but emits portable C++ ahead of time.\n\nRENDERING: `src/skate3_native_render.cpp` hooks selected recompiled renderer functions to capture dynamic mesh state, sorted world lists, palettes and frame boundaries. `rex/graphics/native_guest_renderer` exposes a backend-neutral callback from the guest swap path and can suppress visual execution of emulated draws while keeping PM4 parsing, fences, queries and memory-export/composition behavior alive. OpenXR consumes the native output only after the D3D12 command processor has submitted the producer work.\n\nFRAME / CAMERA: `src/vr/openxr_bridge.cpp` keeps the XR predicted-display-time view sample, body/render anchors and output submission in one lifecycle. The body anchor comments explicitly distinguish the guest tick from the headset render tick and avoid racing raw guest/culling anchors against interpolated render anchors.\n\nINPUT: `src/vr/touch_input.h` defines Xbox-compatible control semantics. The implemented PCVR path writes OpenXR-derived state into ReXGlue XAM synthetic input, preserving the game’s Xbox 360 input contract.\n\nBOUNDARIES: The uploaded snapshot does not contain `src/skate3_native_scene.cpp` or `src/skate3_native_scene_gpu.cpp`, though CMake/manifest metadata references them. Therefore exact internals of the complete native scene/GPU implementation are not claimed beyond the available headers, post-processing code, capture hooks and ReXGlue seam.\n\nSOURCE FILES: `README.md`; `CMakeLists.txt`; `third_party/rexglue-sdk/README.md`; `third_party/rexglue-sdk/include/rex/runtime.h`; `src/skate3_native_render.cpp`; `src/skate3_native_scene.h`; `src/vr/openxr_bridge.cpp`; `src/vr/openxr_bridge.h`; `src/vr/touch_input.h`; `patches/rexglue-openxr.patch`.";
CODE_AUDITS["pattern_skate3_rexglue_static_recomp_architecture"] = "VERIFIED SOURCE.\n\nMECHANISM: ReXGlue is an ahead-of-time static recompiler. The source describes a pipeline that reads Xbox 360 images/configuration, analyzes PPC functions and emits C++ source. At runtime the generated functions operate against a guest virtual-memory base and ReXGlue-provided platform services. Xenia is credited as foundational Xbox 360 research/tooling; that lineage should not be confused with running Skate 3 under Xenia’s normal dynamic emulator/JIT execution path.\n\nPORTABLE IMPLEMENTATION RECIPE: For another console recompilation VR project, keep three contracts explicit: generated guest code, guest-platform ABI/services, and title-specific host extensions. Do not bake VR logic into the instruction translator if it can live at stable guest-function or platform-service boundaries. That separation allows renderer/input/VR work to evolve without reimplementing the CPU translation pipeline.\n\nVALIDATION: Confirm emitted code uses the runtime’s guest memory base and resolved exports; verify known guest functions produce identical side effects before inserting title-specific overrides; keep codegen deterministic for a fixed binary/config set.\n\nBOUNDARY: Static recompilation does not eliminate Xbox 360 platform behavior. The Runtime still owns virtual memory, VFS, KernelState, graphics, audio, input, function dispatch and export resolution.\n\nSOURCE FILES: `third_party/rexglue-sdk/README.md`; `third_party/rexglue-sdk/src/codegen/codegen.cpp`; `third_party/rexglue-sdk/src/codegen/project_recompiler.cpp`; `third_party/rexglue-sdk/include/rex/runtime.h`.";
CODE_AUDITS["pattern_skate3_rexglue_runtime_guest_services"] = "VERIFIED SOURCE.\n\nMECHANISM: `rex::Runtime` is the host-side container for the recompiled Xbox program. It creates virtual address space, mounts game/update/user storage, owns kernel objects, installs function/export dispatch, and receives injectable graphics/audio/input backends. Recompiled guest functions receive/access the virtual memory base instead of ordinary process pointers to original Xbox addresses.\n\nARCHITECTURAL VALUE: This boundary lets title-specific VR code choose where to integrate. Input can enter at XAM; rendering can enter at the graphics command processor/guest-output seam; game semantics can be intercepted through recompiled function overrides. None of those need to modify the PPC translator.\n\nPORTABLE RECIPE: Define platform interfaces first, then add title-specific extension points at the smallest stable service boundary. Keep guest addresses and host pointers distinct. Expose only deliberate native interop resources to subsystems that actually need them.\n\nVALIDATION: Boot/load the exact XEX/module set, test guest memory mapping and exported service calls, and ensure tool-mode analysis can run without initializing a GPU.\n\nSOURCE FILES: `third_party/rexglue-sdk/include/rex/runtime.h`; `third_party/rexglue-sdk/src/codegen/codegen.cpp`.";
CODE_AUDITS["pattern_skate3_tu3_multibinary_codegen"] = "VERIFIED SOURCE.\n\nMECHANISM: The build’s update preparation extracts/stages updated default and EAWebKit XEX images plus patch files, configures `patched_file_path` into the codegen manifests, selects a TU-specific function list, then invokes ReXGlue codegen for both modules. This avoids generating host C++ from retail functions while executing updated data/layouts at runtime.\n\nPORTABLE RECIPE: Identify every executable module whose code participates in the title. Hash/version the base and update package, materialize the exact post-update image set used by analysis/codegen, namespace secondary-module symbols, and bind the runtime to the same update package.\n\nVALIDATION: Compare hashes/sizes before codegen; assert all expected module outputs exist; run symbol/function-list checks against the updated binary rather than assuming retail addresses survive.\n\nSOURCE FILES: `README.md`; `CMakeLists.txt`; `cmake/CodegenTargets.cmake`; `cmake/ExtractTitleUpdateXexp.py`; `manifests/skate3.toml.in`; `manifests/eawebkit.toml.in`; `config/skate3_tu_functions.toml`.";
CODE_AUDITS["pattern_skate3_generated_cpp_patch_hooks"] = "VERIFIED SOURCE.\n\nMECHANISM: After ReXGlue codegen, the build script enumerates emitted translation units, finds exact generated function patterns, checks whether a patch is already present, then replaces/inserts host helper calls. Required targets have explicit failure conditions. This is materially different from a runtime byte patch: the modified code is compiled normally and can use typed host helpers.\n\nPORTABLE RECIPE: Keep generated-code patches small and declarative. Anchor them to function IDs plus a narrow statement shape, make application idempotent, hard-fail when zero or ambiguous matches occur, and place complex behavior in hand-written host functions rather than injecting large generated snippets.\n\nVALIDATION: Re-run codegen from a clean tree; verify each required patch applies exactly once; compile with the patch disabled/enabled and unit-test the host helper separately where possible.\n\nSOURCE FILES: `cmake/ApplySkate3CodegenPatches.cmake`; `cmake/CodegenTargets.cmake`; `src/skate3_fov.cpp`; `src/skate3_ultrawide_guest.h`.";
CODE_AUDITS["pattern_skate3_recompiled_function_override_hooks"] = "VERIFIED SOURCE.\n\nMECHANISM: Recompiled guest functions have stable generated C symbols. Skate supplies strong override definitions for selected functions and uses imported aliases to invoke the generated original. Arguments are read from PPC context registers (`ctx.r3`, etc.) and guest structures are reached through the guest memory base.\n\nPORTABLE RECIPE: Prefer symbol overrides over raw host-address hooks in AOT recomp projects. Keep each wrapper narrowly scoped, call the original on the same ABI path, and record exact register/structure contracts established by reverse engineering. Use before/after placement based on when the original guest function materializes the data you need.\n\nVALIDATION: Compare return values/register state with an unmodified build; instrument call counts/order; ensure virtual dispatch and direct calls both resolve to the override where expected.\n\nSOURCE FILES: `src/skate3_native_render.cpp`; `config/skate3_functions.toml`; `config/skate3_tu_functions.toml`.";
CODE_AUDITS["pattern_skate3_rexglue_native_guest_output_seam"] = "VERIFIED SOURCE.\n\nMECHANISM: ReXGlue’s guest swap determines output size, prepares a native-RHI frame, wraps the presenter output, and calls `TryRenderNativeGuestOutput`. A `true` return means the native renderer produced the frame; `false` means it yielded and the normal emulated output can continue. Skate’s patch exposes native D3D12 handles only during the callback and adds an after-submit notification.\n\nPORTABLE RECIPE: Define a renderer callback in backend-neutral terms first. Pass stable device-level resources plus frame-scoped command recording. Require the callback to restore the output resource to the documented state. Add native API escape hatches only for compositor/runtime interop and invalidate them after the callback.\n\nVALIDATION: Test output resize, renderer disabled, renderer yield, shutdown, and both native-rendered and emulated frames. Resource states must be identical at callback exit to the contract expected by the command processor.\n\nSOURCE FILES: `third_party/rexglue-sdk/include/rex/graphics/native_guest_renderer.h`; `third_party/rexglue-sdk/src/graphics/native_guest_renderer.cpp`; `third_party/rexglue-sdk/src/graphics/d3d12/command_processor.cpp`; `patches/rexglue-openxr.patch`.";
CODE_AUDITS["pattern_skate3_native_scene_capture_architecture"] = "VERIFIED FROM PRESENT SOURCE CONTRACTS; PARTIAL IMPLEMENTATION SNAPSHOT.\n\nMECHANISM: Guest-function overrides identify world sorted lists, dynamic mesh submissions, settled palettes, texture registration and frame end. These events feed `native_scene`. The source tree contains native HLSL and post-processing code plus public scene state/interfaces.\n\nPORTABLE RECIPE: Capture semantic resources and per-draw state, not screenshots. Normalize guest pointers/IDs into durable host-side identifiers. Preserve draw ordering only where it carries visual meaning; otherwise classify by material/pass. Decouple guest-capture cadence from headset-view generation.\n\nVALIDATION: Compare a flat native-render frame with the original guest renderer before enabling stereo; inspect world/dynamic/skinned objects, alpha ordering, shadows, 2D phases and resource lifetime across loads.\n\nBOUNDARY: `src/skate3_native_scene.cpp` and `src/skate3_native_scene_gpu.cpp` are referenced by CMake/manifest metadata but absent from the uploaded snapshot. Therefore exact internal scene-build batching/GPU algorithms are not asserted here.\n\nSOURCE FILES: `src/skate3_native_render.cpp`; `src/skate3_native_scene.h`; `src/skate3_native_scene_state.h`; `src/skate3_native_scene_post.cpp`; `src/native/shaders/scene.hlsl`; `src/native/shaders/scene_char.hlsli`; `src/native/shaders/overlay2d.hlsl`; `VR_PATCH_MANIFEST.json`.";
CODE_AUDITS["pattern_skate3_native_renderer_state_capture_timing"] = "VERIFIED SOURCE.\n\nMECHANISM: `sub_82795AD8` snapshots `DrawSequence`, invokes the generated original, tests whether the sequence advanced, and calls `OnRenderMesh` after the original. Source comments identify the internal pending-constant flush as the reason. If no draw occurred inside the call, using the constant bank would be stale, so the mesh is handled by a later fixup path. Palette hooks also run post-call once packed upload matrices are settled.\n\nPORTABLE RECIPE: Instrument the original renderer to discover where state becomes final. For each captured datum specify pre-call, post-call or post-draw ownership. Attach a sequence/epoch to deferred work so repair can match the state that actually reached the GPU.\n\nVALIDATION: Render many moving skinned entities and deliberately interleave different transforms; a one-draw-late bug becomes obvious as entities inherit their predecessor’s transform/palette. Include deferred/multipass materials in the test scene.\n\nSOURCE FILES: `src/skate3_native_render.cpp`; `src/native/skate3_native_palette.cpp`; `src/native/skate3_native_palette.h`.";
CODE_AUDITS["pattern_skate3_hybrid_gpu_suppression"] = "VERIFIED SOURCE.\n\nMECHANISM: `ShouldSuppressEmulatedDraws`, `ShouldSuppressPassAtPitch` and `ShouldSuppressExemptDepthOnlyDraws` gate execution while native output is active. The comments explain why draw and resolve suppression must agree: executing one half leaves invalid EDRAM/copy behavior. Mode 2 retains lightmap/CAS memory-composition passes; menu/fallback frames execute normally because native output yields.\n\nPORTABLE RECIPE: Trace dependencies before suppressing anything. Keep packet parsing, synchronization, queries and data-export operations that affect guest CPU logic. Preserve intermediate render-to-memory passes that native shaders/resources sample. Couple draw suppression with the corresponding resolve/copy policy.\n\nVALIDATION: Compare gameplay, menus, pause/loading, customization/composite assets and guest query/fence behavior under every suppression mode. A performance win is invalid if it silently removes a texture/page that the native renderer later reads.\n\nSOURCE FILES: `third_party/rexglue-sdk/src/graphics/native_guest_renderer.cpp`; `third_party/rexglue-sdk/include/rex/graphics/native_guest_renderer.h`; `third_party/rexglue-sdk/src/graphics/d3d12/command_processor.cpp`.";
CODE_AUDITS["pattern_skate3_native_renderer_live_fallback"] = "VERIFIED SOURCE.\n\nMECHANISM: The callback result becomes `g_native_output_active`. Suppression is conditional on active native output, and the command processor receives a definitive rendered/yielded result. Output-aspect code also accounts for a native frame followed by an emulated fallback.\n\nPORTABLE RECIPE: Treat each frame as a render-owner decision. Define a fallback-safe resource state, explicit sizing rules and a callback result. Never suppress the legacy renderer until the replacement has positively claimed the frame.\n\nVALIDATION: Transition repeatedly gameplay -> pause -> menu -> gameplay, resize the output, and force a native-render early-out. Check there is no stale VR frame, aspect mismatch, or suppressed emulated frame during ownership changes.\n\nSOURCE FILES: `third_party/rexglue-sdk/include/rex/graphics/native_guest_renderer.h`; `third_party/rexglue-sdk/src/graphics/native_guest_renderer.cpp`; `third_party/rexglue-sdk/src/graphics/d3d12/command_processor.cpp`; `src/skate3_native_scene.h`.";
CODE_AUDITS["pattern_skate3_openxr_same_d3d12_device"] = "VERIFIED SOURCE.\n\nMECHANISM: Skate’s ReXGlue patch adds native device/queue pointers to the guest-output context. XR initialization queries `xrGetD3D12GraphicsRequirementsKHR`, checks adapter LUID and minimum feature level, then constructs `XrGraphicsBindingD3D12KHR` from the producer objects. The implementation expects two primary stereo views.\n\nPORTABLE RECIPE: Ask OpenXR for graphics requirements before session creation. Match adapter identity, validate feature level, and use the existing rendering queue if the runtime permits. Keep one device lifetime owner; the XR bridge should borrow, not recreate, engine resources.\n\nVALIDATION: Log both LUIDs and feature levels; test multi-GPU systems; reject mismatches deterministically; ensure shutdown waits for the producer queue before releasing compositor interop.\n\nSOURCE FILES: `src/vr/openxr_bridge.cpp`; `src/vr/openxr_bridge.h`; `patches/rexglue-openxr.patch`; `third_party/rexglue-sdk/include/rex/graphics/native_guest_renderer.h`.";
CODE_AUDITS["pattern_skate3_xr_frame_submission_boundary"] = "VERIFIED SOURCE.\n\nMECHANISM: `BeginFrame` stores predicted display time and located views/space. The native scene renders during ReXGlue’s guest-output callback. The patched command processor submits its frame and then invokes the submission callback. `Finish` consumes the output with explicit D3D12 transitions/fence synchronization and uses the exact view/FOV records associated with that frame before `xrEndFrame`.\n\nPORTABLE RECIPE: Identify the producer’s real command-queue submission boundary. Place runtime wait/locate early enough to drive view matrices, then place swapchain copy/submission only after producer commands are ordered. Carry a frame token so a yield or failure cannot accidentally submit an unrelated image.\n\nVALIDATION: Force renderer yield, device resize and late GPU frames. Verify no XR swapchain image is released before copy completion and no projection layer references a frame whose producer submission failed.\n\nSOURCE FILES: `src/vr/openxr_bridge.cpp`; `src/vr/openxr_bridge.h`; `third_party/rexglue-sdk/include/rex/graphics/native_guest_renderer.h`; `patches/rexglue-openxr.patch`.";
CODE_AUDITS["pattern_skate3_doublewide_stereo_split"] = "VERIFIED SOURCE.\n\nMECHANISM: `StereoFrame` stores two `Eye` structures plus `eye_width`. In VR, guest-output width is partitioned evenly. `Finish` selects x offset/fraction per eye and records a copy/composite pass to the corresponding acquired OpenXR D3D12 image. The source resource is transitioned and returned to its original ReXGlue state.\n\nPORTABLE RECIPE: Treat stereo packing as an intermediate transport format. Define exact eye extents at render time, preserve per-eye FOV/projection separately, and split only at compositor handoff. Avoid accidentally applying desktop aspect or post-process sampling across the eye boundary.\n\nVALIDATION: Use asymmetric runtime FOVs, render an eye-border test pattern and confirm no cross-eye bleed. Test output resize and verify resource-state restoration on every exit path.\n\nSOURCE FILES: `src/vr/openxr_bridge.cpp`; `src/vr/openxr_bridge.h`; `src/vr/stereo_math.h`.";
CODE_AUDITS["pattern_skate3_guest_xr_coordinate_bridge"] = "VERIFIED SOURCE.\n\nMECHANISM: The math layer constructs row-vector transforms, converts OpenXR tangent-angle FOVs to D3D projection coefficients, and derives camera axis orientation from the guest projection. Physical translation is scaled separately. This allows the rest of the VR bridge to consume a consistent physical camera representation.\n\nPORTABLE RECIPE: Define one canonical host/XR basis; implement guest-view -> canonical and canonical -> guest-view as inverses; keep unit conversion explicit and one-way. Unit-test identity, pure yaw/pitch/roll, asymmetric FOV and handedness/reflection cases without booting the game.\n\nVALIDATION: Verify inverse round trips, eye separation direction, head translation scale, canted/asymmetric projection and near/far depth behavior.\n\nSOURCE FILES: `src/vr/stereo_math.h`; `src/vr/openxr_bridge.cpp`.";
CODE_AUDITS["pattern_skate3_body_anchor_clock_reconciliation"] = "VERIFIED SOURCE.\n\nMECHANISM: The bridge has two publication channels with freshness/ownership logic. `BeginFrame` obtains predicted-time tracking and reconciles it against the most recent coherent render/body anchors. Camera override logic distinguishes first-person body ownership from authored/spectator cameras and avoids oscillating between timelines.\n\nPORTABLE RECIPE: Assign explicit clocks/epochs to simulation body, render-interpolated body and XR tracking. Convert all of them into one world reference before composing. Never overwrite the simulation anchor with the interpolated anchor; doing so creates feedback and double application.\n\nVALIDATION: Test high headset refresh with lower guest tick, hitch/freeze the guest for several XR frames, transition first/third-person authored cameras, and inspect body/world stability while physically moving the head.\n\nSOURCE FILES: `src/vr/openxr_bridge.h`; `src/vr/openxr_bridge.cpp`; `src/vr/presentation_smoothing.h`; `src/vr/body_ik.cpp`; `src/vr/body_ik.h`.";
CODE_AUDITS["pattern_skate3_vr_screen_space_effect_policy"] = "VERIFIED SOURCE.\n\nMECHANISM: VR startup changes renderer cvars/policies before the OpenXR path runs. This is a correctness gate, not evidence that the effects are impossible in VR; the repository contains SSAO/SSR/HDR shaders and post code, but the VR configuration chooses safety over unverified stereo behavior.\n\nPORTABLE RECIPE: Inventory screen-space and temporal effects. For each, classify whether it needs per-eye depth, per-eye motion/history, eye-local viewport coordinates or view-independent inputs. Disable unknown cases, then re-enable one subsystem at a time with stereo tests.\n\nVALIDATION: Use high-depth-contrast geometry near eye edges, head translation and rapid rotation to expose mono depth/history contamination. Test each eye independently.\n\nSOURCE FILES: `src/vr/openxr_bridge.cpp`; `src/skate3_native_scene_post.cpp`; `src/native/shaders/ssao.hlsl`; `src/native/shaders/ssr.hlsl`; `src/native/shaders/hdr.hlsl`.";
CODE_AUDITS["pattern_skate3_xam_synthetic_gamepad"] = "VERIFIED SOURCE.\n\nMECHANISM: OpenXR action state is converted to a runtime-independent `touch::Pad`. The PCVR publisher builds ReXGlue `SyntheticGamepadState` and calls `SetSyntheticGamepadState`. XAM applies that state during `XamInputGetState`, while retaining queued/tap behavior used by boot/UI flows. Session/focus loss clears stale synthetic state.\n\nPORTABLE RECIPE: Map XR actions to the original console device abstraction at the lowest point that is still semantically meaningful. Keep button bitmasks, normalized axes, trigger ranges and packet/change semantics faithful. Make input ownership/focus loss explicit and clear held state on disconnect.\n\nVALIDATION: Log XR action -> synthetic pad -> XAM returned state; test held sticks, trigger ramps, simultaneous buttons, focus loss and boot/menu interactions. Ensure only one virtual player/device owns the target slot.\n\nSOURCE FILES: `src/vr/touch_input.h`; `src/vr/openxr_bridge.cpp`; `third_party/rexglue-sdk/include/rex/kernel/xam/input_injection.h`; `third_party/rexglue-sdk/src/kernel/xam/xam_input.cpp`.";
CODE_AUDITS["pattern_skate3_guest_occlusion_dispatch_filter"] = "VERIFIED SOURCE.\n\nMECHANISM: The recompiled `SceneRenderView` wrapper receives the guest vector plus first/count. Native capture runs on the full list. A temporary compaction changes only what the original dispatcher sees, and restoration occurs immediately after. This preserves the guest object/list lifetime and host scene knowledge.\n\nPORTABLE RECIPE: Separate “what exists” from “what legacy GPU work should execute.” Use conservative previous-frame visibility, keep the optimization world-static-only until motion/occlusion latency is safe, and never destroy guest-owned collection contents permanently.\n\nVALIDATION: Disable/enable the filter live; compare popping, fast camera turns and newly visible geometry. Assert the guest list is byte-for-byte restored after dispatch.\n\nSOURCE FILES: `src/skate3_native_render.cpp`; `src/skate3_native_scene.h`.";
CODE_AUDITS["pattern_skate3_sdk_patch_pinning"] = "VERIFIED SOURCE.\n\nMECHANISM: Build configuration treats the ReXGlue patch as an ABI prerequisite. It detects already-applied state, validates clean application, aborts on mismatch, and keeps OpenXR loader acquisition hash-pinned. The patch itself adds native D3D12 resource pointers and the after-submit callback used by the XR bridge.\n\nPORTABLE RECIPE: Minimize upstream changes, isolate them in one reviewable patch, pin the upstream revision, and validate patch application before compiling title code. If the seam becomes generally useful, upstream the abstraction rather than accumulating title-specific forks.\n\nVALIDATION: Configure from a clean pinned checkout, from a checkout with the patch already applied, and from an intentionally wrong SDK revision; only the first two should proceed.\n\nSOURCE FILES: `cmake/Skate3OpenXR.cmake`; `patches/rexglue-openxr.patch`; `README.md`; `VR_PATCH_MANIFEST.json`.";
CODE_AUDITS["pattern_skate3_guest_memory_composition_bridge"] = "VERIFIED SOURCE.\n\nMECHANISM: Suppression policy uses surface-pitch/pass classification to keep memory-composition work alive while removing replaced scene/post passes. The rationale in source specifically names lightmap pages and CAS/outfit composite surfaces as native-render dependencies.\n\nPORTABLE RECIPE: Trace every guest render target that is later read back, sampled from guest memory or converted into host resources. Mark those passes as data producers. Suppress only their downstream visual consumers if the native renderer replaces those consumers.\n\nVALIDATION: Exercise dynamic outfits/customization, lightmap/page changes and scene loads while toggling suppression. Compare guest-memory products against the fully emulated pipeline.\n\nSOURCE FILES: `third_party/rexglue-sdk/src/graphics/native_guest_renderer.cpp`; `third_party/rexglue-sdk/include/rex/graphics/native_guest_renderer.h`.";

function escapeHtml(s){ return (s||'').replace(/[&<>"]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }
function escapeAttr(s){ return escapeHtml(s); }


/* OBLIVION_PHYSICS_AUDITS_BEGIN */
CODE_AUDITS["seed_oblivionvr_case"] = "CORRECTED DEEP SOURCE AUDIT (2026-10-11) — `Profile 2.0 Physics Combat.zip` is the authoritative supplied snapshot for this record. IMPORTANT SOURCE BOUNDARY: this is UEVR Lua/profile source and bundled Lua libraries, not UEVR’s native renderer/OpenXR implementation. Therefore native stereo, projection/swapchain ownership and compositor prediction remain UEVR-owned and are not reverse-engineered here.\n\nBOOTSTRAP / COMPATIBILITY: `Config/CONFIG.lua` declares required UEVR commit count 1343 and uses `functions.get_total_commits()` to surface older/equal/newer runtime state. Configuration is persisted through `json.load_file`/`json.dump_file` in `main-config.json`. `MainHandler.lua` composes game-specific subsystems and uses three callback phases: `on_xinput_get_state` for raw-input capture/remapping; `on_pre_engine_tick` for native state, pose, camera, attachments, holsters, melee and HUD; `on_post_calculate_stereo_view_offset` for the active `UpdatePhysicsConstraintLogic` call.\n\nTRACKING / OBJECT LIFETIME: `Subsystems/Trackers.lua` creates level-owned left/right tracker actors with `MotionControllerComponent`, and an HMD actor with `SceneComponent`. The HMD is connected to UObjectHook tracking with `set_hand(2)` and `set_permanent(true)`. The code conditionally writes `.Hand` only when that property exists, making the tracker scaffold tolerant of engine-version API differences. Level changes compare `world.PersistentLevel`; reset paths clear or destroy tracker actors, and `pcall` is used because the source explicitly notes that an object can still be unusable even after an existence check. `MainHandler::OnLevelChange` independently invalidates constraints, anchors, weapon caches, stats/camera refs and controller refs.\n\nPOSE / GAME-STATE CONTRACT: `GlobalDataCustom.lua::CalculateHelperVectors` snapshots left/right/HMD locations/rotations plus inter-hand and hand-to-head vectors each game tick. `UpdateBowStatus`, `UpdateRidingStatus`, `UpdateMenuStatus`, `UpdateCombatStanceStatus` and `UpdateSprintStatus` translate native game state into semantic VR flags used by downstream modules. This keeps profile logic coupled to a small adapter surface rather than scattering Altar property checks across every feature.\n\nBODY / COORDINATES: `Attachements.lua::update_Body_Meshes` reads native `Root` and `head` socket transforms, subtracts their positions and explicitly documents conversion from UE coordinates to UEVR motion-controller offset coordinates (X->Z, Y->-X, Z->-Y). It hides lower-arm bones and selected body children, keeps desired hand/body presentation, and drives the mesh through HMD UObjectHook state. `GetHmdYawOffset` integrates head yaw, clamps it to ±70°, recenters it more aggressively during locomotion and applies a bow-specific bias; this is a visual torso-swivel heuristic rather than full IK. Ragdoll/riding paths call `remove_motion_controller_state`, demonstrating explicit ownership handback.\n\nBOW / CAMERA / LOCOMOTION: `update_weapon_offset` binds the bow mesh to left hand and drawn arrow mesh to right hand. During draw, bow rotation is computed from inter-controller rotators and left-hand roll; arrow orientation is corrected relative to right-hand rotation. `CameraManager::UpdateCameraManager` can call `ClientSetRotation` from bow/hand aim. It computes HMD and hand planar headings and `AlphaDiff`; `CameraInput` rotates the captured movement stick by `-AlphaDiff` so locomotion remains in the intended head frame even when control rotation is weapon-driven. Ordinary locomotion calls native `pawn:AddMovementInput` with HMD or right-controller forward/right vectors and forces UEVR `VR_MovementOrientation=0` to avoid double orientation. Stereo-view callbacks can anchor riding camera position to `Rider.MainSkeletalMeshComponent:GetSocketLocation(\"Head_Socket\")` and otherwise use a pawn-height origin. A `ViewTarget.Target` cinematic detector exists in source, but its pre-engine-tick call is commented in this snapshot; it is evidence of intended camera-ownership arbitration, not claimed active coverage of all cinematics.\n\nPHYSICS-CONSTRAINED WEAPON MASS: `PhysicsMassEmu.lua::CreateConstraintLogic` spawns helper actors, hidden static-mesh affected bodies, pawn-side `VHitSphere` anchors, an HMD-parent hitbox and right/left `PhysicsConstraintComponent`s. `ConfigureConstrainMeshes` assigns proxy collision object types 30/31, turns control anchors to IgnoreAll, and establishes tick dependency: anchor in group 0 -> constraint in group 2 -> affected mesh in group 2 via `AddTickPrerequisiteComponent`. `SetConstrainAttachLogic` attaches primary/support anchors to hand components and a parent anchor/constraint to HMD. `ConfigureConstraintComp` locks primary linear axes, enables linear position+velocity drives and SLERP angular drives, while the support-hand constraint uses bounded 20° angular limits and no linear velocity drive. This avoids two equally rigid six-DOF masters. `SetItemToConstrain` applies a title collision profile, suppresses proxy/self channels, disables gravity while controlled and restores gravity on release. `CounterMoveAffected` measures horizontal pawn displacement and moves anchors by that delta so locomotion does not create false spring extension. `SetPhysicsHandlerAttachLogic` demonstrates reparenting the real weapon mesh to the proxy and disabling the mesh’s own collision. `UpdatePhysicsConstraintLogic` is the active MainHandler path; the separate `PhysicsMassEmu-OneHandedbb.lua` is present but not the required implementation.\n\nMELEE / NATIVE AUTHORITY: `Melee.lua` samples raw UEVR controller pose with `vr.get_pose` and derives hand motion. The native weapon `VHitBox` is enabled/attached and queried with `GetOverlappingComponents`; unarmed fallback uses `RightHandHitBox_FP` / `LeftHandHitBox_FP`. The shield path can add `VHitBoxClass` at runtime with calibrated relative location/extent. Valid NPC contacts can temporarily enable skeletal simulation below `spine_01`, apply an impulse around `spine_02`, then `UpdateRagdolls` blends physics weight back out. Native combat remains authoritative: accepted contacts call `SendMeleeHitOnPairedPawn`, stamina/fatigue is checked/consumed through native state, and block paths use `SendBlockHit` / `SendBlock(false)`. A separate forward `LineTraceSingle` plus controller-motion threshold/cooldown gates `MeleeInput`; on acceptance it toggles the game’s right-trigger XInput value to send a normal attack edge. This shows two complementary semantic seams: direct native target hit function and native input-state transition.\n\nSPATIAL ZONES / HOLSTERS: `HolsterScript.lua` converts each hand from world space to HMD-yaw-relative coordinates by subtracting HMD position and rotating XY by negative HMD yaw. It separately converts the opposite hand into the dominant-hand/weapon local frame by inverse yaw/roll/pitch operations. Body-relative boxes therefore represent hip/chest/head/shoulder zones, while weapon-local boxes represent interactions such as reload/mode/attachment gestures. The module stores current/last zones for haptic/action edge gating and routes accepted interactions into the game’s quick-slot/input/UI vocabulary.\n\nUI / RETICLE / RADIAL MENU: `VRHud.lua` finds the live `WBP_ModernHud_Reticle_C` instance belonging to `VAltarHud`, removes it from the viewport, puts the same widget into a new controller-owned `WidgetComponent`, applies a translucent no-depth widget material and attaches it to the right hand. `Reticle.luabb` actively spawns a controller-attached emissive reticle mesh, scales it with placement range and rebuilds its actor/components on level/menu transitions. The file also contains SceneCapture2D/render-target/FOV-by-eye-distance scope code, but major creation/attachment sections are commented; do not describe a fully active optical scope from this snapshot. `RadialQuickMenu.lua` freezes the right-hand transform when the menu opens, transforms later hand positions into that local frame, applies a 3 cm deadzone, quantizes eight sectors, converts the sector to right-stick X/Y and writes it in `on_xinput_get_state`; it can use `CheatManager:Slomo(0.1)` during selection.\n\nHANDS: `Main/hands.lua` creates reusable hands from a config/animation layer and hides the original first-person hand skeletal mesh. Bundled hand code drives named joint animation from XInput grip and UEVR action handles such as controller thumb-rest touch. This is controller-driven poseable-hand animation; no optical hand-tracking extension is established.\n\nREUSABLE ARCHITECTURE: native game state -> semantic VR policy flags; UEVR tracking -> stable Unreal tracker components; tracker geometry -> camera/body/bow/zones; tracked anchor -> PhysicsConstraint proxy -> native visual weapon; physical overlap/velocity -> native attack/block semantics; native UMG widget -> tracked WidgetComponent. The core strategy is selective authority transfer: VR owns pose and physical intent only where necessary, then hands gameplay back to existing Altar systems.\n\nLIMITATIONS / EVIDENCE: exact classes, collision channels, sockets, function names and profile constants are Altar/build-specific. The profile contains commented/alternate implementations; audits above distinguish active MainHandler paths from present-but-inactive experiments. No claim is made about UEVR native rendering internals, OpenXR frame timing, multiplayer replication or server authority beyond what this Lua package exposes.";
CODE_AUDITS["pattern_oblivion_uevr_world_tracker_scaffold"] = "VERIFIED FROM SUPPLIED `Profile 2.0 Physics Combat.zip`. `Subsystems/Trackers.lua::spawn_hand_actors` spawns three ordinary actors in the current `GameViewport.World`, adds `MotionControllerComponent` for left/right and `SceneComponent` for HMD, assigns `MotionSource`, conditionally assigns `.Hand`, then installs a UObjectHook motion-controller state on the HMD with hand index 2 and `set_permanent(true)`. `reset_hand_actors`, `reset_hand_actors_if_deleted` and the `on_pre_engine_tick` level check harden this scaffold against map lifetime. Broad UEVR lesson: convert runtime tracking into engine-native components early, then let downstream code use Unreal attachment, transform and collision APIs rather than carrying two parallel pose representations.";
CODE_AUDITS["pattern_oblivion_uevr_tracker_lifetime_hardening"] = "VERIFIED FROM `Subsystems/Trackers.lua` and `MainHandler.lua`. `reset_hand_actors` uses both `UEVR_UObjectHook.exists` and guarded method invocation; `on_level_changed` assumes level-owned actors are deleted; `MainHandler::OnLevelChange` clears physics, weapon, camera and stats references and reacquires controller/HMD objects. For broad UEVR work, design every spawned actor/component subsystem with an explicit reset contract and treat `PersistentLevel` transitions as invalidating game-owned and profile-owned references unless proven otherwise.";
CODE_AUDITS["pattern_oblivion_uevr_shared_pose_geometry_cache"] = "VERIFIED FROM `Subsystems/GlobalDataCustom.lua::CalculateHelperVectors` and `Subsystems/Trackers.lua` pre-engine-tick callback. The cached fields include `Diff_Vector_LR`, `Diff_Rotator_LR`, `Diff_Vector_HR`, `Diff_Rotator_HR`, `RightRotator`, `LeftRotator`, `HmdRotator`, and world locations. Generalize this as a profile-level pose snapshot consumed by semantic interaction code; do not confuse it with UEVR’s internal render prediction.";
CODE_AUDITS["pattern_oblivion_uevr_profile_build_guard"] = "VERIFIED FROM `Config/CONFIG.lua::uevr_version_check` and its JSON-backed UI helpers. This is a safety pattern for broad UEVR profiles: surface runtime compatibility explicitly, persist configuration outside code, and fail visibly at setup rather than letting low-level profile assumptions produce intermittent runtime errors.";
CODE_AUDITS["pattern_oblivion_uevr_callback_phase_separation"] = "VERIFIED FROM `MainHandler.lua` callbacks. This source is useful precisely because it does not treat “UEVR Lua tick” as one undifferentiated phase. For a new profile, document which callback owns each state transition, whether that callback is per-frame or per-eye, and which data crosses the boundary. The supplied source does not expose low-level OpenXR `xrWaitFrame/xrEndFrame`; UEVR owns that layer.";
CODE_AUDITS["pattern_oblivion_uevr_native_state_policy_adapter"] = "VERIFIED FROM `Subsystems/GlobalDataCustom.lua::{UpdateBowStatus,UpdateRidingStatus,UpdateMenuStatus,UpdateCombatStanceStatus,UpdateSprintStatus}` and `MainHandler.lua` pre-engine-tick ordering. Reusable pattern: build a title adapter that translates game-native state into semantic VR flags; keep downstream VR systems ignorant of title-specific class/property details.";
CODE_AUDITS["pattern_oblivion_uevr_hmd_body_socket_rebase"] = "VERIFIED FROM `Main/Attachements.lua::update_Body_Meshes`, especially socket reads and the source comment documenting axis conversion. Broad UEVR method: choose a stable native skeletal reference pair, derive the local pivot error, explicitly convert coordinate conventions, then feed that offset into UObjectHook tracking state. Keep geometry-visibility policy separate from the transform math.";
CODE_AUDITS["pattern_oblivion_uevr_soft_body_yaw_lag"] = "VERIFIED FROM `Main/Attachements.lua::{GetHmdYawOffset,update_Body_Meshes}`. Portable recipe: integrate relative HMD yaw into a bounded body offset, define explicit recenter triggers (locomotion, weapon pose, snap turn), and apply that offset only to the visual/body ownership layer—not to raw HMD orientation.";
CODE_AUDITS["pattern_oblivion_uevr_contextual_tracking_release"] = "VERIFIED FROM `Main/Attachements.lua::update_Body_Meshes`. General UEVR guidance: every `get_or_add_motion_controller_state` path should have a documented removal path keyed to native state changes. Test ragdoll, vehicles/mounts, cutscenes, death/respawn, menu transitions and camera-mode changes.";
CODE_AUDITS["pattern_oblivion_uevr_poseable_hand_config"] = "VERIFIED FROM `Main/hands.lua`, `addons/hands.lua`, `addons/hand_animations.lua` and bundled `libs/hands.lua`/`libs/animation.lua`. Broad UEVR pattern: create a poseable presentation hand, detach finger visuals from native weapon animation, then map semantic controller contacts/buttons to reusable pose layers. Preserve the game’s native action calls separately.";
CODE_AUDITS["pattern_oblivion_uevr_two_hand_bow_split_ownership"] = "VERIFIED FROM `Main/Attachements.lua::update_weapon_offset` and shared `Diff_Rotator_LR*` fields. Reusable UEVR method: assign independently tracked visual/game objects to distinct hands, derive the primary object’s orientation from the controller baseline while an interaction is active, and make ownership conditional so native equipment state can still hide/detach the objects.";
CODE_AUDITS["pattern_oblivion_uevr_aim_locomotion_frame_decoupling"] = "VERIFIED FROM `Main/CameraManager.lua::UpdateCameraManager` (HMD/hand heading and `AlphaDiff`) and `CameraInput` (inverse rotation of XInput left stick). General recipe: identify the native frame used for movement, identify the VR frame users expect, and transform the input vector between them whenever aim policy changes native control rotation.";
CODE_AUDITS["pattern_oblivion_uevr_native_movement_from_trackers"] = "VERIFIED FROM `Main/CameraManager.lua::UpdateCameraManager`. Broad UEVR lesson: prefer feeding spatial intent into the game’s existing movement function over directly translating the pawn; when the profile supplies the orientation basis, disable any second orientation transform in the injector/runtime layer.";
CODE_AUDITS["pattern_oblivion_uevr_stereo_socket_camera_anchor"] = "VERIFIED FROM `Main/CameraManager.lua` `on_early_calculate_stereo_view_offset` callbacks. Transfer guidance: compute a mono/base camera origin from the native animated socket, write that base origin for each eye, and let UEVR layer the eye separation/projection. Test mount animation, dismount transitions, crouch/scale changes and per-eye callback ordering.";
CODE_AUDITS["pattern_oblivion_uevr_viewtarget_ownership_detection"] = "SOURCE-PRESENT METHOD from `MainHandler.lua::CinematicStatus`; current call site in the pre-engine tick is commented. It is still a valuable broad UEVR seam: `PlayerCameraManager.ViewTarget` is an engine-native ownership signal. A production profile should gate camera/input mutation on that signal and test transitions into/out of dialogue, killcams, cutscenes and scripted devices.";
CODE_AUDITS["pattern_oblivion_uevr_constraint_weapon_mass_proxy"] = "VERIFIED FROM `Main/PhysicsMassEmu.lua::{CreateConstraintLogic,SetConstrainAttachLogic,ConfigureConstraintComp,UpdatePhysicsConstraintLogic}`. Architecture: tracked MotionController component -> small anchor primitive -> `PhysicsConstraintComponent` drive -> simulated affected body -> native visual weapon mesh. General UEVR use case: physical weight/lag/contact for held objects while keeping native inventory/fire/damage authority. Do not confuse this with simply interpolating the weapon transform; the solver owns the intermediate body.";
CODE_AUDITS["pattern_oblivion_uevr_constraint_tick_order"] = "VERIFIED FROM `Main/PhysicsMassEmu.lua::ConfigureConstrainMeshes`. Reusable rule: model the dependency graph explicitly—tracking target first, constraint update second, visual/affected body consumer third. If a held physics object jitters only during movement, inspect update order before only increasing stiffness/damping.";
CODE_AUDITS["pattern_oblivion_uevr_constraint_collision_partition"] = "VERIFIED FROM `Main/PhysicsMassEmu.lua::{ConfigureConstrainMeshes,SetItemToConstrain}`. Broad UEVR pattern: assign explicit collision identities to profile-created control bodies, suppress collisions among the control chain, and separately choose which world/game channels the visible/physical weapon should contact. Document this matrix as part of the profile.";
CODE_AUDITS["pattern_oblivion_uevr_physics_locomotion_compensation"] = "VERIFIED FROM `PhysicsMassEmu.lua::CounterMoveAffected` and `MainHandler` pre-engine tick. Reusable physics principle: choose the inertial frame for your VR constraint. Subtract motion of the player/root/platform that should transport the entire rig, leaving only hand motion relative to that frame as the driver of physical lag.";
CODE_AUDITS["pattern_oblivion_uevr_physics_grab_release_handoff"] = "VERIFIED FROM `PhysicsMassEmu.lua::{SetItemToConstrain,UpdatePhysicsConstraintLogic}`. General UEVR method: define `Acquire`, `Held`, `Release`, `Restore` states for any native object you put under profile physics. At each boundary set all relevant properties—attachment, simulate physics, gravity, collision profile/channels, constraint references—so interrupted transitions cannot leave corrupt state.";
CODE_AUDITS["pattern_oblivion_uevr_asymmetric_two_hand_constraints"] = "VERIFIED FROM `Main/PhysicsMassEmu.lua::ConfigureConstraintComp`. Broad physical-weapon lesson: two tracked hands are an over-constrained system if both are hard six-DOF targets. Give each hand a different authority model—primary pose ownership, support directional/leverage constraint—and tune drives independently.";
CODE_AUDITS["pattern_oblivion_uevr_visual_weapon_proxy_attachment"] = "VERIFIED FROM `Main/PhysicsMassEmu.lua::SetPhysicsHandlerAttachLogic`. Reusable UEVR architecture: do not necessarily spawn a replacement gun/sword. Insert a proxy transform/physics body into the visual hierarchy and move the native mesh under it, preserving the game object that authoritative gameplay code references.";
CODE_AUDITS["pattern_oblivion_uevr_native_hitbox_melee"] = "VERIFIED FROM `Main/Melee.lua::Melee`. Broad UEVR technique: find a game-owned collision volume already associated with the correct weapon/hand, make it follow the VR-controlled object, use it for spatial candidate detection, then call native combat authority rather than damaging actors directly.";
CODE_AUDITS["pattern_oblivion_uevr_partial_ragdoll_contact_feedback"] = "VERIFIED FROM `Main/Melee.lua::{Melee,UpdateRagdolls}`. Reusable pattern: use local skeletal physics to sell contact, but keep damage/status effects on the native attack path. Track every body you temporarily simulate and provide a deterministic blend/disable cleanup path.";
CODE_AUDITS["pattern_oblivion_uevr_overlap_trace_melee_gate"] = "VERIFIED FROM `Main/Melee.lua` trace block and `MeleeInput`. Broad VR interaction lesson: separate *proximity/contact* from *intent*. Compose collision, direction/range and velocity/cooldown evidence before firing a semantic game action.";
CODE_AUDITS["pattern_oblivion_uevr_physical_attack_native_input_edge"] = "VERIFIED FROM `Main/Melee.lua::MeleeInput` and `SendMeleeHitOnPairedPawn` call sites. Broad UEVR method: physical gesture -> validated semantic intent -> native input/function seam. This preserves animation/state compatibility better than bypassing the combat system with direct health subtraction.";
CODE_AUDITS["pattern_oblivion_uevr_pose_block_semantics"] = "VERIFIED from active sword-sideways and shield-collision block paths in `Main/Melee.lua`; some shield-angle-only activation lines are commented. Transferable design: require a pose to remain in a valid region for a short dwell, latch semantic state, then use the game’s own block/start/stop functions and haptics.";
CODE_AUDITS["pattern_oblivion_uevr_runtime_collision_component_injection"] = "VERIFIED FROM `Main/Melee.lua` shield path. General UEVR pattern: when the game has a useful native component type but a specific actor lacks an instance, dynamically add/configure it and use it as a VR sensor. Prefer native component classes when they already integrate with the title’s collision conventions.";
CODE_AUDITS["pattern_oblivion_uevr_body_space_holster_zones"] = "VERIFIED FROM `Main/HolsterScript.lua::HolsterScript` local-coordinate math and zone predicates. Reusable VR design: transform tracked points into the semantic owner’s local frame first, then implement interactions as simple geometry there. This is usually more stable than moving world-space trigger volumes every frame.";
CODE_AUDITS["pattern_oblivion_uevr_weapon_local_interaction_zones"] = "VERIFIED FROM `Main/HolsterScript.lua` weapon-local coordinate conversion and weapon-zone checks. Broad UEVR methodology: choose the object that semantically owns an interaction, transform the controller into that object’s local coordinates, then run simple proximity/state logic. This scales to magazines, slides, bolts, safeties and attachment points.";
CODE_AUDITS["pattern_oblivion_uevr_zone_edge_haptics"] = "VERIFIED from `Main/HolsterScript.lua` zone-state/haptic paths and `Config/CONFIG.lua` `Holster_Haptic_Feedback`. General UEVR rule: model spatial interactions as a finite-state machine (`outside -> hover -> grabbed/activated -> outside`) and attach haptic cues to transitions, not continuous proximity.";
CODE_AUDITS["pattern_oblivion_uevr_native_widget_reparent"] = "VERIFIED FROM `Main/VRHud.lua::UpdateHudOnLevelChange`. Reusable UEVR UI technique: prefer reusing the live native widget when it already contains all game state. Move presentation ownership to a tracked/world `WidgetComponent`, and keep gameplay/UI state ownership in the game.";
CODE_AUDITS["pattern_oblivion_uevr_controller_depth_reticle"] = "VERIFIED ACTIVE PATH from `Reticle.luabb::{spawn_reticle_plane,attach_components_to_weapon,UpdateReticleDistance,on_pre_engine_tick}`. The file also contains an inactive/commented SceneCapture/render-target scope scaffold and eye-distance FOV math; those are evidence of design work but are not promoted here as active functionality.";
CODE_AUDITS["pattern_oblivion_uevr_radial_menu_open_frame"] = "VERIFIED FROM standalone `RadialQuickMenu.lua`. Reusable UEVR method: freeze an interaction reference transform at activation, convert future controller motion into that stable local space, quantize to native menu semantics, and inject the gamepad axis instead of rebuilding the menu. Explicitly distinguish standalone supplied modules from modules proven to be required by the main script.";
CODE_AUDITS["pattern_oblivion_uevr_input_capture_then_suppress"] = "VERIFIED FROM `MainHandler.lua::UpdateInput` and its `on_xinput_get_state` dispatch order. Broad UEVR input pattern: snapshot raw native input, derive semantic intent, then suppress/remap only the channels whose ownership moves to VR. Do not zero inputs before dependent modules read them.";
/* OBLIVION_PHYSICS_AUDITS_END */

function renderFeatureNavigation(){
  const bar = document.getElementById('featureBar');
  const detail = document.getElementById('featureDescription');
  if(!bar || !detail) return;

  const featureKeys = Object.keys(FEATURE_DEFS);
  const tabs = ['all', ...featureKeys];
  bar.innerHTML = tabs.map(k=>{
    const active = filters.feature===k;
    const count = k==='all' ? DB.length : DB.filter(e=>cachedEntrySubsystems(e).includes(k)).length;
    const label = k==='all' ? 'All' : featureShortLabel(k);
    const hint = k==='all' ? 'Show every registry entry.' : FEATURE_DEFS[k].hint;
    return `<button type="button" class="feature-tab${active?' active':''}" data-feature-select="${k}" role="tab" aria-selected="${active?'true':'false'}" title="${escapeAttr(hint)}"><span>${escapeHtml(label)}</span><span class="feature-tab-count">${count}</span></button>`;
  }).join('');

  if(filters.feature==='all'){
    detail.innerHTML = `<div class="feature-selection-copy">
      <div class="feature-selection-kicker">All implementation references</div>
      <h3>Browse everything, or choose a subsystem above</h3>
      <p>Subsystem filters change both the visible entries and the structure of the LLM export. Selecting a specific feature keeps the exported context focused on the implementation problem you are solving.</p>
    </div>
    <div class="feature-selection-actions"><span class="feature-result-count">${DB.length} source-audited references</span><button type="button" class="btn secondary compact" data-export-focus>Export all</button></div>`;
  } else {
    const def = FEATURE_DEFS[filters.feature];
    const count = DB.filter(e=>cachedEntrySubsystems(e).includes(filters.feature)).length;
    detail.innerHTML = `<div class="feature-selection-copy">
      <div class="feature-selection-kicker">Selected subsystem</div>
      <h3>${escapeHtml(def.label)}</h3>
      <p>${escapeHtml(def.hint)}</p>
    </div>
    <div class="feature-selection-actions"><span class="feature-result-count">${count} matching references</span><button type="button" class="btn secondary compact" data-export-focus>Export this focus</button></div>`;
  }
}

function hasRefinements(){
  return filters.type!=='all' || filters.engine!=='all' || filters.api!=='all' || filters.injection!=='all' || !!filters.query.trim();
}

function renderResults(){
  const results = applyFilters();
  const focus = filters.feature==='all' ? 'All subsystems' : FEATURE_DEFS[filters.feature].label;
  const shown=Math.min(visibleResultCount,results.length);
  document.getElementById('countLine').innerHTML = `<div class="result-count-copy"><strong>${results.length}</strong> of ${DB.length} references${filters.feature!=='all' ? ` · <span class="result-count-focus">${escapeHtml(focus)}</span>` : ''}${results.length>shown?` <span class="result-page-note">showing ${shown}</span>`:''}</div>${hasRefinements()?'<button type="button" class="clear-refinements" data-clear-refinements>Clear refinements</button>':''}`;
  const list = document.getElementById('cardList');
  if(!results.length){ list.innerHTML=`<div class="empty">Nothing matches this combination. Try clearing a refinement or choosing another subsystem.</div>`; return; }
  const cards=results.slice(0,shown).map(cardHTML).join('');
  const more=shown<results.length ? `<div class="results-more"><button class="btn secondary" type="button" data-show-more>Show ${Math.min(RESULT_PAGE_SIZE,results.length-shown)} more</button></div>` : '';
  list.innerHTML=cards+more;
}

function render(){
  renderFacets();
  renderFeatureNavigation();
  renderResults();
}

document.addEventListener('click', (ev)=>{
  const preset = ev.target.closest('[data-explore-preset]');
  if(preset){ openExplorePreset(preset); return; }
  const showMore = ev.target.closest('[data-show-more]');
  if(showMore){ visibleResultCount += RESULT_PAGE_SIZE; renderResults(); return; }
  const featureSelect = ev.target.closest('[data-feature-select]');
  if(featureSelect){
    filters.feature = featureSelect.dataset.featureSelect;
    resetResultPage(); render();
    return;
  }
  const clearRef = ev.target.closest('[data-clear-refinements]');
  if(clearRef){
    filters.type='all'; filters.engine='all'; filters.api='all'; filters.injection='all'; filters.query=''; resetResultPage();
    const search=document.getElementById('searchInput'); if(search) search.value='';
    render();
    return;
  }
  const exportFocus = ev.target.closest('[data-export-focus]');
  if(exportFocus){
    document.getElementById('exportBtn')?.click();
    return;
  }
  const fac = ev.target.closest('.facet-opt');
  if(fac){
    filters[fac.dataset.key] = fac.dataset.val;
    resetResultPage(); render();
    return;
  }
  const toggle = ev.target.closest('[data-toggle]');
  if(toggle){
    const id = toggle.dataset.toggle;
    expanded[id] = !expanded[id];
    render();
    return;
  }
  const jump = ev.target.closest('[data-jumpfeature]');
  if(jump){
    const k = jump.dataset.jumpfeature;
    if(DB.filter(e=>cachedEntrySubsystems(e).includes(k)).length){
      filters.feature = k;
      resetResultPage(); render();
      document.querySelector('.layout')?.scrollIntoView({behavior:'smooth'});
    } else {
      showToast('No audited references are available for that subsystem yet.');
    }
    return;
  }
  const vote = ev.target.closest('[data-vote]');
  if(vote){
    const id = vote.dataset.vote;
    const entry = DB.find(e=>e.id===id);
    if(entry){
      entry.votes = (entry.votes||0) + parseInt(vote.dataset.delta,10);
      render();
      saveDB();
    }
    return;
  }
});

document.addEventListener('change', (ev)=>{
  const select = ev.target.closest('[data-filter-select]');
  if(!select) return;
  filters[select.dataset.filterSelect] = select.value;
  resetResultPage(); render();
});

let searchRenderTimer = 0;
document.getElementById('searchInput').addEventListener('input', (ev)=>{
  filters.query = ev.target.value;
  resetResultPage(); syncFilterStateToURL();
  clearTimeout(searchRenderTimer);
  searchRenderTimer = setTimeout(renderResults, 60);
});

// ---------- Modal helper ----------
function closeModal(){ document.getElementById('modalRoot').innerHTML = ''; }

// ---------- Export modal ----------
document.getElementById('exportBtn').addEventListener('click', ()=>{
  const results = applyFilters();
  const focus = filters.feature;
  const focusLabel = focus!=='all' ? (FEATURE_DEFS[focus]?.label||focus) : 'All implementation subsystems';
  const guidance = focus!=='all' ? FEATURE_EXPORT_GUIDANCE[focus] : 'Each entry is normalized into implementation-oriented sections. Preserve source-backed distinctions and do not infer features that are absent from an entry.';
  const md = results.map(e=>formatLLMEntry(e,focus)).join('\n\n---\n\n');
  const usedFeatures = Object.keys(FEATURE_DEFS).filter(k=>results.some(e=>cachedEntrySubsystems(e).includes(k)));
  const legend = usedFeatures.length ? `# Subsystem tags represented in this export\n${usedFeatures.map(k=>`- **${FEATURE_DEFS[k].label}** — ${FEATURE_DEFS[k].hint}`).join('\n')}\n\n---\n\n` : '';
  const exportHeader = `# Hook Registry — normalized LLM implementation export\n\n**Active subsystem focus:** ${focusLabel}\n\n**How to use this export:** ${guidance}\n\nFor each entry, distinguish the source-backed implementation from limitations/evidence boundaries. Adapt architectural patterns to the target game; do not copy engine-specific symbols or assume an unlisted subsystem exists.\n\n---\n\n`;
  // The UEVR primer is useful only when the filtered result set actually contains UEVR material; it is
  // intentionally no longer prepended to unrelated exports such as Body IK or legacy-engine rendering.
  const hasUEVR = results.some(e=>/uevr/i.test([e.title,e.engineFamily,e.injectionMethod,e.sourceLinks].join(' ')));
  const uevrPrimer = hasUEVR ? `# UEVR technical primer\n\nUEVR is a universal Unreal Engine VR injector for UE4/UE5. Its reusable substrate includes native/sequential/alternating stereo modes, OpenVR/OpenXR runtime integration, engine-object access and Lua/native extension seams. Treat UEVR as infrastructure only: hands, IK, physical weapon aiming, melee, UI and native gameplay integration still require per-game source/profile evidence.\n\nSources: https://github.com/praydog/UEVR/blob/master/README.md, https://github.com/praydog/UEVR/blob/master/src/mods/VR.hpp\n\n---\n\n` : '';
  const fullMd = exportHeader + uevrPrimer + legend + md;
  const root = document.getElementById('modalRoot');
  root.innerHTML = `
  <div class="overlay" id="overlay2">
    <div class="modal">
      <h2>Export for LLM context</h2>
      <p class="sub">${results.length} entries matching your current filters. Focus: ${escapeHtml(focusLabel)}. Each entry is normalized into implementation sections before export.</p>
      <div class="field"><textarea class="export-area" id="exportArea" readonly>${escapeHtml(fullMd)}</textarea></div>
      <div class="modal-actions">
        <button class="btn secondary" id="closeExport">Close</button>
        <button class="btn" id="copyExport">Copy to clipboard</button>
      </div>
    </div>
  </div>`;
  document.getElementById('closeExport').addEventListener('click', closeModal);
  document.getElementById('overlay2').addEventListener('click', (e)=>{ if(e.target.id==='overlay2') closeModal(); });
  document.getElementById('copyExport').addEventListener('click', ()=>{
    const ta = document.getElementById('exportArea');
    ta.select();
    try{ document.execCommand('copy'); showToast('Copied normalized markdown to clipboard.'); }
    catch(e){ showToast('Could not copy automatically — select the text manually.'); }
  });
});


// ---------- Theme ----------
(function(){
  const key='hook_registry_theme';
  const saved=localStorage.getItem(key);
  const prefersDark=window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
  const initial=saved || (prefersDark ? 'dark' : 'light');
  document.documentElement.dataset.theme=initial;
  function update(){
    const dark=document.documentElement.dataset.theme==='dark';
    const b=document.getElementById('themeBtn');
    if(!b) return;
    b.querySelector('.theme-icon').textContent=dark?'☀':'☾';
    b.querySelector('.theme-label').textContent=dark?'Light mode':'Dark mode';
    b.setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');
    b.title=dark?'Switch to light mode':'Switch to dark mode';
  }
  document.addEventListener('DOMContentLoaded',function(){
    update();
    document.getElementById('themeBtn')?.addEventListener('click',function(){
      const next=document.documentElement.dataset.theme==='dark'?'light':'dark';
      document.documentElement.dataset.theme=next; localStorage.setItem(key,next); update();
    });
  });
})();


// Overlord Beta 5 source-audit: case-study and reusable patterns added 2026-10-10.
CODE_AUDITS["seed_overlord_mw2cr_vr_case"] = "EVIDENCE / VERSION: Audited from the supplied `Overlord-main` source archive, including the C++ implementation, profile registries, documentation, and focused tests. The supplied `version.json` identifies **Beta 5, file version 0.1.0.5, prerelease=true**. README calls the project an actively changing beta and explicitly warns that crash/missing-visual reports exist and many combinations have only been tested on the author's machine. This is a case study of an unusually ambitious implementation, not a claim of universal stability or final HMD acceptance.\n\nARCHITECTURE / BOOTSTRAP: `src/client/main.cpp` owns launch-mode and supported-game-build gating. It distinguishes launcher process from the game process, handles `-singleplayer`, obtains a target binary only after size/version checks, and creates an ASLR-patched working copy of the known game binary before loading. `verify_version()` checks a build-specific unsigned value; the relevant offsets and instruction signatures are build contracts, not portable constants. Native code installs hooks through guarded/verified call sites instead of assuming that a signature scan alone proves semantic compatibility. The VR component defers its runtime/render owner lifecycle until the D3D11 Present owner exists. A failed compatibility check should refuse a patch/hook or leave the native path intact instead of partially installing a mix of incompatible offsets.\n\nRENDERER / TRUE STEREO: This is not just a desktop-image copy or a post-Present head-look overlay. `engine_stereo_renderer.cpp` hooks the game's D3D11 renderer internals and establishes a native scene-view pair. It publishes finalized generator-view records through `publish_generator_views()` before native draw-surface generation so the stereo backend can claim the correct view family. Scene CPU data is copied only after the H2 job pump/wait barriers complete the native initial, surface, and effect production phases, and after the four producer-completion flags and frontend identity agree. Those flags mean CPU production finished; they do not mean GPU execution completed or that a compositor released a texture. The source explicitly separates these completion/ownership boundaries.\n\nThe native camera view finalizer (build-specific address noted by the rendering document at `0x14077F550`) writes rotation/projection and eye-origin inverse view data into different matrix fields. The implementation does not require left/right projection matrices to differ numerically for a symmetric FOV; it does require genuinely distinct eye transforms and rejects copied center-eye view matrices. `engine_stereo_owner_pass` owns admission and per-view execution. A native stereo pair is admitted only after an execution-context/GPU census can account for relevant render work: unknown immediate contexts or opaque command lists keep the native path/gate from claiming the scene. This is a fail-closed compatibility rule, because an unrecorded renderer worker could otherwise write the wrong eye's state or submit an incomplete scene. Tracking can be alive while production stereo still waits for a complete scene census.\n\nEach eye gets a private transaction for camera data, model/scene submission state, dynamic uploads, eye target and temporal images. The implementation has to preserve native renderer ordering rather than call `R_RenderScene()` twice from an arbitrary place. Shared terrain visibility/tessellation needs to cover both eyes; eye-private image and camera state must not turn shared scene visibility into an eye-0-only result. The owner pass also accounts for a selected auxiliary view (for selected optical/special views) separately from left and right. Eye and auxiliary ownership is explicit, not inferred from current backbuffer dimensions.\n\nXR FRAME TIMING / SUBMISSION: `runtime_backend.cpp` fixes backend choice at construction; OpenXR is default and OpenVR/SteamVR compatibility is manually selectable. OpenXR's `openxr_runtime.cpp` owns session state, predicted display time, locate-view result, frame begin/end, native-pair admission, and frame retirement. The runtime does not silently replace a failed default backend with a different runtime: explicit selection, lifecycle status, and errors remain diagnosable. The render/present path uses a per-frame prediction record (including frame-open, view validity, whether a native pair was admitted, menu-only state, menu layer readiness, pending presents, and the frame pair) so a menu/desktop present cannot accidentally inherit a gameplay pair.\n\nEye poses and projection metadata belong to one predicted frame / immutable slot. The native eye pair is accepted together, not one eye sampled from frame N and the other from frame N+1. In OpenVR mode the output resources are D3D11 textures on the same D3D11 device, with matching dimensions/format/generation and strict texture-contract checks (including ordinary 2D, single-sample, RT/SRV capabilities, and no CPU access or misc flags in the default route). Compositor ownership is confined to the present pre/post transaction. A call returning failure is not treated as proof that the compositor no longer owns an earlier texture. Submitted pairs are retained until the next successful pose-wait/ownership boundary; resizing is coalesced until the safe Present-pre boundary, GPU idle is awaited before swapchain destruction, and generations prevent stale texture reuse. Focus loss is recoverable; an incomplete submission does not erase ownership evidence.\n\nPOST-PROCESS / TEMPORAL IMAGE STATE: The mod reuses selected native post-AA materials (FXAA, SMAA 1x, SMAA T2x and the Filmic SMAA variants) after the native eye PostFX stage and before the eye is copied for headset submission. It keeps per-eye histories (and a separate history for a selected auxiliary optical view); temporal history commits only for a complete view pair. AA mode changes, resource changes, discontinuous frames and camera resets invalidate incompatible history. SMAA temporarily uses the scene depth buffer for edge detection and restores it before depth-tested VR composition. Native SSAA remains separate from post-AA. SSR history is isolated by eye, image identity and camera generation; bindings are isolated before the first history read and restored at scope boundaries. It must not seed both eyes from the desktop image or reuse stale history after a resize/recenter/camera cut. These are state-lifetime rules, not simply per-eye shader calls.\n\nCAMERA / COORDINATE CONTRACTS: `head_pose_bridge.cpp` is the common runtime-to-game boundary. It keeps validated tracking/reference data, calibration, world scale (default 39.3700787 game-units-per-meter), yaw/heading state, command history, and camera/body snapshots. Controller and HMD snapshots are value data rather than a long-lived game object pointer. Invalid/non-finite or non-orthonormal rotations are rejected. `camera.cpp`, `scripted_camera.hpp`, `camera_rig.hpp`, `scripted_view.hpp`, and `scripted_position.hpp` compose HMD pose and native camera pose at the final native view boundary. Native view/tag lookup is outside the tracking mutex; the policy core itself does not call the script VM or keep engine entity pointers. Head rotation, head translation, script rotation, native rotation axes, native pose source (final view or named tag), and entry alignment are separate policy dimensions.\n\nScene identity and phase decide who owns the view. Typical ordinary play allows free head rotation and tracked translation; fixed optics can own the full pose; vehicles and mounted weapons preserve scene-selected heading while letting the player look around; story sequences may add native yaw, ignore later scripted rotation after one-time alignment, attenuate translation, or temporarily lock the head to a native impact. Entry alignment is epoch-scoped and remains pending until its required tag exists; recenter/repeated samples must not consume it twice. Checkpoint/load rollback clears stale camera/command baselines and reinitializes tracking when the scene is valid. Rotation is composed once for the shared camera, while left/right eye offsets and projection are applied per eye.\n\nROOMSCALE / TURN: `roomscale_origin.hpp` keeps the world origin coherent when accepted native yaw changes. It turns about the *current tracked head position*, not the old recenter point, compensates the same tracking/world frame used by camera, hands, body and equipment, and tracks bounded command-time history so prediction/replay doesn't integrate one turn repeatedly. Native accepted yaw is observed after the controller's HMD contribution is accounted for. Recenter and load reset clear the compensation. Native H2 movement, collision, grounding, and physics still own player motion; this is a coordinate-space reconciliation layer, not a replacement character controller. The core uses a documented forward/left/up basis with meter translation, converting to engine units at adapters.\n\nINPUT / NATIVE COMMANDS: OpenXR action recipes and the OpenVR/SteamVR path feed the same runtime-independent input snapshot. OpenXR actions include move/turn vectors, sprint/jump/menu/recenter semantics, trigger/squeeze/touch/button values, per-hand grip and aim pose spaces, and haptic output. `refresh_profiles()` verifies that the runtime's active interaction profile matches the recipe; pose-space/input is invalidated rather than trusting data from a mismatched profile. The snapshot has sample time, focus/validity, reference generation and continuity; `controller_input.cpp` filters and bounds controller transforms. The Standard OpenXR-coordinate controller pipeline remains opt-in/experimental and keeps a distinct calibration bank from Legacy. The documented, primary validated pairing is Quest/Touch with SteamVR/OpenXR; OpenVR/Index has separate limited testing. Do not claim every runtime/controller combination is supported.\n\n`controller_component.cpp` hooks the H2 command path at verified build-specific instructions. It lets native input finish first, then mutates the live `game::usercmd_s` before it enters the native command-history ring. It preserves/ORs native button state rather than treating every command as VR-owned. Static assertions constrain known command layout, and hook bytes are checked. Left-stick locomotion is translated into H2 movement axes relative to horizontal head heading; right stick emits smooth yaw-rate or release-rearmed snap turns. Sprint, jump, duck/prone, menu and interaction actions enter native command/bind routes instead of a second simulation. Discontinuous turns clear/advance temporal-history state only when needed, avoiding a reset every smooth-turn command. Weapon input is gated in scripted story phases, vehicles, climbs, turrets, menus/focus loss, stale tracking, and weapon readiness. The provider/action owner neutral-arms after changes so a held trigger after a context switch cannot become a fresh shot.\n\nBODY / ARM IK: This is robust bilateral arm IK and hand/weapon rig solving, not generic motion-capture full-body IK. `gameplay/hands/pose_solver.hpp` uses the native skeleton's parent graph, native bone transforms, and explicit left/right shoulder-elbow-wrist chains; the rig is capped at 256 bones. It has explicit `gun`, weapon tag, muzzle, rear-grip wrist, laser and weapon-bone ownership metadata. Rig binding (`rig_builder.hpp`) checks exact named topology, parent ordering, duplicates/aliases, expected model/profile, weapon descendants and incompatible overlapping chains before accepting a rig. Ambiguous or unexpected asset topology is rejected instead of guessed.\n\nThe two-bone solve uses limb segment lengths and a stable elbow-pole derived from the authored bend in the torso/body frame. It uses a law-of-cosines reach solve and rejects non-finite/invalid lengths and frames. Maximum stretch ratio is 1.25; beyond that reach is limited instead of pulling shoulders off their anatomical anchor. `arm_plane_normal()` retains the authored shoulder frame for straight-arm degeneracy; `orient_arm()` transports both upper- and lower-arm segments through the same oriented bend plane. This avoids the 360-degree elbow flips possible if each segment is independently rotated via shortest arc. The solver works in temporary pose arrays and commits only after a complete valid solve; weapon bones are excluded while arm chains are solved and only descendants of the intended shoulder/elbow/wrist are rewritten. That atomic/limited write discipline keeps a bad solve from partially corrupting a skeleton.\n\nA tracked grip target and a gun-aim orientation are separate. The wrist target carries the controller's grip position; the selected grip calibration rotates the native wrist-to-weapon relationship without conflating aim pose and palm position. Rear-hand pose is derived from an explicit rear-grip wrist / authored rear offset instead of reusing the weapon's old support-hand rest pose. That is critical for a rifle with an off-hand foregrip: the hand nearest the receiver has firing controls and trigger/index finger poses, while the forward hand supports the fore-end. Finger pose library entries are semantic (`open`, `primary_grip`, `support_grip`, `mag_grip`, `charging_handle`, `slide_release`, `shell_pinch`, `device_grip`) and are anchored per interaction, with optional controller curl layered where available. Invalid hand/controller data falls back to native animation or rejects that interaction, rather than inventing wrist/bone transforms.\n\nSTORY ARMS / IK OWNERSHIP: `scripted_arms_runtime` shares the rig solver but is admitted only for an explicit story sequence/body/model/phase. In the Cliffhanger opening, native `viewbody_arctic` provides the armature and initial authored pose. The native crouch pose remains until the native stand-up animation starts; each arm blends toward its tracked wrist based on native animation playback progress, not a timer. Shoulders, torso, root, camera and legs remain native. The code executes after native skeleton calculation during `DObjCalcSkel` while its DObj lock is held; only approved arm descendants are modified and the solve is processed once per skeleton frame, including failed attempts. Existing `tag_weapon_left/right` child prop ownership is retained, preventing a second pair of VR ice picks. Free climbing explicitly hands arm ownership back to the ordinary hand system. This is a narrow, scene-specific adapter, not a claim of arbitrary scripted-body or leg IK.\n\nWEAPON POSE / MOUNTING: `weapon_registry.hpp`, `weapon_registration.hpp`, `weapon_profile_binding.hpp`, `weapon_attachments.hpp`, `weapon_profiles.hpp` and `weapons/<family>/profile.hpp` define a reviewed assembly catalog instead of spreading `weaponName == ...` checks across gameplay code. A recipe describes chassis/weapon identity, attachment role, bone topology, grip anchors, muzzle/aim frame, activity bones, capabilities, and the primary vs underbarrel module. Catalog entries are immutable and capability-specific views are bounded/deduplicated. The profile system checks actual weapon/model identity and attachment structure; it doesn't infer all mechanics from WeaponDef flags or names alone. Documentation's registry tests refer to dozens of detachable-magazine recipes and individual-shell recipes; that count is versioned test/catalog data, not proof every profile has passed headset acceptance.\n\nThe firing transform is a weapon's validated muzzle frame, not simply the current camera ray. `weapon_interaction.cpp` publishes/invalidate muzzle geometry with revisions and ties it to the held native instance/current pose. Weapon aim/ADS optics use native optic/sight pose policies and preserve native controls/accuracy rules where eligible. Support-grip ownership is explicit; placing the hand near a foregrip is insufficient to count as a mechanically established two-hand grip. First/second-hand selection, release, transfer, world pickup and holster operations are separate transactions through the carry adapter. Some dual-wield cases have dedicated independent fire pathways but arbitrary mixed-weapon dual wield remains an explicit non-goal/pending acceptance in the architecture docs; do not promote all mixed dual wield to established capability.\n\nNATIVE FIRING / DAMAGE: `native_ballistics.cpp` is a guarded adapter. `initialize()` verifies byte signatures for the native bullet wrapper, weapon-type/descriptor/spread path, trace function, player-state firing gate, and native-ammunition initialization. Signature constants and offsets are game-build-specific and must not be transplanted. `fire_owned()` requires the adapter to be verified; it rejects recursion/emission, cheat/state transitions, wrong scheduler pipeline (must be native server phase), uninitialized cgame, command-time mismatch, invalid or disallowed player/script state, pause/active menu catcher, malformed muzzle geometry, unsupported non-firearm class, missing/empty current native inventory, out-of-range muzzle origin, shield obstruction, and obstruction between eye and muzzle. The eye-to-muzzle `G_TraceCapsule` check prevents a gun whose muzzle passes through near cover from firing through it. Native spread and weapon definition are read for the selected weapon and sanity-checked.\n\nAfter admission, ammunition is projected for the correct weapon identity and committed through `native_ammunition::commit_carried` with an expected snapshot compare. It then settles the mechanical owner callback before entering native bullet execution, because the native bullet may execute damage or script callbacks. `emitting` prevents reentrant shot paths. Once the native bullet function is entered, the code deliberately does not refund ammunition on a later error because irreversible game callbacks may already have run. It calls the game's bullet function with the adjusted geometry/spread and native actor/time arguments, then observes post-shot ammunition. This is a transaction/authority boundary—not custom hit detection or a replacement damage system.\n\nThe native fire path resolves weapon timing through native descriptor-driven mode/interval/delay accessors rather than assuming one universal shots-per-second value. `WeaponDef` and native class/attachment timing are respected when admitted. Scope/ADS uses dedicated sight/optic rules; the shot geometry and mechanical reload state must agree before a trigger commits. A profile may support alternate/underbarrel modules only when those modules have a registered feed/muzzle/action contract.\n\nWEAPON MECHANICS / RELOAD: The physical reload subsystem is split into weapon-family adapters: `physical_reload_runtime.cpp`, `reload_item_runtime.cpp`, `native_ammunition.cpp`, `cylinder_runtime.cpp`, `tube_runtime.cpp`, `break_action_runtime.cpp`, `launcher_runtime.cpp`, `underbarrel_runtime.cpp`, and profile headers. Detachable magazine, loose shell/tube loading, cylinder, hinged break action, launcher, and underbarrel mechanisms are not forced into one unrealistic “reload” action. Semantically different things—hand contact, held item, grip/trigger edge, mag well, release catch, chamber/action gesture, ammo reserve, loaded magazine/clip, weapon identity, and actual native ammo—are represented separately.\n\nThe reload item system owns physical magazine/round objects and lifecycle/presentation, including waist supply, world physics, fall/expiry/refund semantics. The carry system owns weapon identity, inventory, holster/draw, world weapon interactions and hand leases. The ammunition adapter is the only native ammo read/write authority; it snapshots native carried ammo, validates identity and counts, and performs expected-state commits on the server scheduler. A separate per-instance ledger preserves mechanical state across drop/pickup when the native world weapon entity changes, keyed by identity/generation rather than just weapon index. Draw/stow should not silently refill/reset the chamber.\n\nReload interaction is transactional: select a valid registered receiver/feed; acquire the correct spatial item/part through the central arbiter; establish target/hand ownership from current snapshots; validate weapon identity, context, reserve/capacity and current mechanical stage; then commit the ammo transfer on the native owner thread. A stale/invalid item, wrong owner, changed weapon, over-capacity transfer, or context switch rejects or reconciles without creating free ammunition. Physical reload handoffs are staged and settled through the coordinator so support grip, magazine grip, slide/charging-handle ownership and trigger firing cannot claim the same hand concurrently. Some architecture documents retain older “design target” wording for portions of the reload/mechanical state machine; the more current implementation modules and focused tests show multiple feed adapters are present. That mismatch is explicitly a documentation caveat, and runtime/HMD acceptance is still incomplete.\n\nRecoil is a viewmodel/weapon-body presentation effect, not a forced HMD jerk. An accepted shot adds upward pitch to the physical weapon's recoil state; automatic fire accumulates, then exponentially recovers toward controller aim. The firing wrist/fingers pitch with the receiver and support hand follows the foregrip via arm IK; raw tracking/controller pose and HMD remain unchanged. Current tuning derives an expected pitch-speed magnitude from native `hipGunKickPitch*` values, handles descending/sign-crossing endpoint ranges, converts 50 ms of speed to a bounded impulse, multiplies by posture baseline (standing 3x, crouched 2x, prone 1x), weapon-family scaling, and optionally a 4x unsupported single-hand penalty for eligible weapons (default `long`; prone disables the single-hand penalty). Recoil clamps at 55 degrees and decays with a 0.22 s exponential constant (exactly zero at two seconds). It is explicitly not a complete native recoil simulator: no horizontal recoil, random per-shot sample, full ADS interpolation or native kick acceleration sequence.\n\nHOLSTER / CARRY / DUAL WIELD: `weapon_carry_runtime.cpp` owns native inventory and weapon-instance transitions; `weapon_interaction.cpp` owns trigger/aim/muzzle integration; mechanical feed modules own their own state. Body holsters are typed (waist/back) and interact with weapon size/profile rules. Physical world pickup still delegates to native existence/ownership/physics and transfers current game state. Releasing one hand, switching controller roles, a reference-space rebase or losing focus must cancel/rebase leases; they must not leave a stuck support hand or fire on the first trigger sample after tracking resumes. Profile registry can authorize individual dual-side instance behavior, but generic/unreviewed mixed dual-wield is not universal. World weapon dropping, native inventory transfer, presentation of falling items, and mechanical loaded/reserve ledger are coordinated but intentionally not the same state object.\n\nINTERACTION COORDINATOR: `interaction_coordinator.cpp` sequences named providers through a checked schedule: report settled identities; synchronize hand input; exchange underbarrel supply; collect reload/equipment/world/ladder proposals; resolve all candidates once through `hand_interaction`; settle the granted operations in declared order; reconcile support/carry; update equipment/world-use; publish feedback and finish. Provider ID/phase-binding static validation rejects missing report/collect/settlement/lifecycle coverage. `hand_interaction/core.hpp` has input-edge cursors keyed to action generation, fresh sequence/time, reference generation and continuity. Stale or discontinuous input invalidates edges; a held trigger/grip is not reinterpreted as a new press after recovery. Candidates include domain, actor, source/destination identity, priority, contact/orientation, event and exclusivity; resolution rejects invalid, no-edge, incompatible, occupied-target, lower-priority, capacity, commit-failed and wrong-route cases explicitly. The bounded resolver orders proposals deterministically and maintains sessions/leases instead of each subsystem independently polling “is the grip near me?”\n\nENVIRONMENT / LOCOMOTION: Native H2 remains responsible for movement velocity, collision, ground contact, sprint/crouch/prone, player capsule and most mission movement. The mod translates analog stick/turn into the original command route and adds carefully selected physical adapters. Physical ladders are an opt-in/setting-controlled alternate for validated static or single-model ladder meshes only. `ladder_scene.cpp` extracts real horizontal indexed LOD0 edges incrementally; it does not invent rungs by slicing a bounding box. Candidates/contact points must also pass current native `SURF_FLAG_LADDER` and visibility checks. Animated/multi-model/unknown scaled geometry is rejected. `ladder_runtime.cpp` uses an invisible non-solid script-owned carrier and native link/ground reference operations; grip displacement yields body pull through full player capsule sweeps and collision-approved absolute positions. Two-hand goals are averaged (not summed), remaining grips rebase when one releases, blocked motion is consumed to prevent a delayed launch, and rendered preview is limited to a server-tested segment. Rendering never performs server collision traces or writes physics. Source docs say the trainer/basic behavior works, but hand-fit/upper-rail comfort and gameplay acceptance on representative ladders remain open.\n\nCliffhanger free climbing is distinct from the scripted opening-arm adaptation. The story scene grants two tracked ice-pick supports with collision-tested tip sweeps and phase ownership; body motion is computed relative to anchored picks, and native story logic relinquishes/restores arm/weapon control as the player exits the phase. This is a mission-specific adapter—not proof that any surface can be climbed. Scripted climbing body/camera/ice pick ownership must be transferred explicitly to avoid duplicate props or two competing hand solvers.\n\nVehicle adaptations are deliberately narrow: the `af_chase` Zodiac and the `cliffhanger` snowmobile are admitted only when the living player is linked to the expected native vehicle parent and the expected `zodiac_player`/`snowmobile_player` animation is active. Head rotation remains separate from driving yaw. Vehicle sticks combine steering/throttle vectors and clamp the resultant magnitude; right-stick view turning is suspended. Snowmobile hand grips attach to the native animated handle only within a 12 cm acquisition radius and are routed through the same hand arbiter; animated handle/wrist/finger poses are preserved. The driver weapon uses the native `tag_flash` origin/native magic-bullet pathway. These are not universal vehicle controls.\n\nMELEE / EQUIPMENT / OBJECTS: `native_melee.cpp`, special melee/equipment adapters, grenade/throwback, night vision, heartbeat, underbarrel and world interaction each register through the common interaction schedule. The original damage/collision/mission mechanism remains the downstream authority where invoked. Supported knives and mission equipment have explicit profiles and collision/contact semantics; don't infer a general physics-based sword system. Throwable/equipment interactions use their own native action/projectile paths and state constraints. Trigger/grip is routed by context so a free hand can interact with a magazine/part without accidentally firing the held gun.\n\nUI / HUD / PRESENTATION: Native H2 LUI/menu output is captured through source-aware render paths. `native_menu.cpp` and `menu_overlay.cpp` reuse native menu image, cursor/mask, native command/navigation and input state rather than recreating menu widgets in a separate framework. For OpenVR, menu panels use curved frontend surfaces and flat in-game surfaces; OpenXR has native quad/cylinder layer helpers. VR ray/cursor coordinates are fitted back into the native desktop layout; transparent padding cannot accept clicks, and UI ray ownership is relinquished only on deliberate desktop input, not idle mouse polling. Menus neutral-arm after stack/tracking/binding/hand/context changes. Gameplay native HUD/reticles/waypoints/captions and selected overlays have separate capture/presentation code. The in-game panel's 1920x1080 output is a proportional presentation canvas, not proof that game layout itself became independent 16:9. Per-eye menu blur is bounded to the active native-content rectangle and preserves eye/depth semantics.\n\nHAPTICS / DIAGNOSTICS: Runtime action adapters own haptic outputs; gameplay providers send semantic interaction/shot/collision feedback after accepted state changes. Diagnostics are extensive: `vr_status`, `vr_*_status`, controller/frame/hand/weapon/menu/ladder status and CSV/ZIP capture. The repo has many deterministic unit/contract tests and GPU WARP probes for stereo, AA/SSR history, eye-resource isolation, input, profile selection, IK, recoil, physical reload, menu mapping, ladders, vehicles and lifecycle. Tests establish local mathematical/contracts and recorded probes, not overall end-to-end headset acceptance. Actual runtime compatibility requires a supported binary, matching runtime/controllers, real campaign scenes, and device-specific validation.\n\nREUSABLE DESIGN RULES: (1) define one immutable input/body/camera snapshot and pass copies across domains; never query XR from game, render and gameplay domains independently; (2) isolate eye resources and commit temporal history only after a complete pair; (3) make build-specific hook/texture/bone assumptions guarded and reject unknown cases; (4) use stable entity/profile/generation identity instead of bare indices across lifecycle changes; (5) separate physical intention/presentation from native committed gameplay state; (6) settle interaction ownership centrally; (7) preserve native collision/damage/inventory/mission logic; (8) model mission/story cameras as policies with explicit owner, phase, tag and lifecycle; (9) treat device and HMD acceptance as a separate evidence tier.";
CODE_AUDITS["pattern_overlord_native_stereo_pair_transaction"] = "VERIFIED FROM SOURCE/DOCS: `engine_stereo_renderer.cpp` publishes generator-view identity before native surface generation and uses `engine_stereo_owner_pass` to admit the paired scene. `engine_scene_completion.cpp`/the job-capture path keeps CPU scene production, owner-pass completion and runtime/compositor resource retirement as separate boundaries. An execution-context census has to establish that relevant render work is accounted for; unknown contexts/opaque command lists prevent production stereo from claiming the scene. OpenXR's `openxr_runtime.cpp` stores per-frame `native_pair_admitted`, views validity and presentation state; the OpenVR route uses the same D3D11 eye output device and generation checks.\n\nPATTERN: (1) Define the exact native hook that owns a scene view. (2) Publish immutable pair metadata (pair/frame ID, views/projections, resource generations) before producers need it. (3) Wait only for documented CPU producer barriers on their owner, not from arbitrary worker threads. (4) Admit neither eye unless both belong to the same frame family. (5) preserve textures/resources until an explicit successful runtime ownership boundary. (6) On incomplete data, continue native rendering or render a separately qualified UI-only frame; don't fabricate an eye from the desktop backbuffer. This is why Overlord avoids naïvely calling the scene renderer twice or using the most recent left eye with a stale right-eye image.\n\nTRANSFER: Use when hooking a mature deferred renderer with worker contexts and persistent resources. Treat hook addresses, matrix fields and D3D11 capabilities as build-specific contracts and fail closed when the actual renderer schedule differs. GPU census and automated probes do not establish headset acceptance.";
CODE_AUDITS["pattern_overlord_per_eye_temporal_history_isolation"] = "VERIFIED FROM SOURCE/DOCS: `native_post_aa.cpp` reuses selected H2 native AA materials after native PostFX and before the image is copied for VR. SMAA T2x/Filmic histories are per eye and separate for selected auxiliary optical views. History commits only after a complete pair; AA mode/resource changes, discontinuous frames, camera resets and device changes invalidate dependent histories. `engine_stereo_eye_resources.cpp` and the SSR logic isolate state by eye, image identity and camera generation, including bindings around the first history read.\n\nPATTERN: temporal state is keyed by `(view identity, image/resource generation, camera generation, mode)` instead of one global “last frame” texture. Do not let each eye advance a shared ring independently, and don't seed both eyes from the desktop backbuffer. Reset only state that depends on the invalidated resource; preserve unrelated histories. For SMAA depth reuse, restore native depth before subsequent depth-tested optics/composition.\n\nTRANSFER: Essential when stereo conversion changes the number/order of renderer invocations. A visually correct first frame can still ghost badly after turn, scope entry, resize or focus regain if history keys are incomplete. `ssr_history_probe.cpp` and eye resource probes offer local regression seams; final motion quality still needs HMD validation.";
CODE_AUDITS["pattern_overlord_scene_owned_camera_policy_and_roomscale_origin"] = "VERIFIED FROM SOURCE/DOCS: `camera_rig.hpp`, `scripted_camera.hpp`, `scripted_view.hpp`, `scripted_position.hpp` and `gameplay/campaign/sequences/camera_policies.hpp` separate head rotation (`fixed/pitch_roll/limited/free`), translation (`fixed/attenuated/tracked`), native script rotation (`override_view/additive/ignore`), native rotation axes, source pose/tag and one-time entry alignment. Game-thread adapters publish values; named-tag lookup occurs outside the tracking mutex, and camera composition doesn't retain native object pointers. Rotation composes once for the shared camera; eye offsets/projections remain per-eye. `roomscale_origin.hpp` rotates around the tracked head origin, compensates camera/hand/body/equipment space after accepted native yaw and uses bounded command-time history to avoid replay/double application.\n\nPATTERN: model camera as a prioritized policy/ownership decision, not a global “replace view angles” patch. Make tracking yaw, command yaw, script yaw, locomotion displacement and roomscale origin separate state. Scope entry alignment to an owner/lifecycle epoch and keep it pending until its tag is valid; invalidate it on load/recenter/relink, not on every poll. A scripted camera may accept native yaw but attenuate HMD translation, while a fixed optic may own both rotation and translation.\n\nLIMITS: scene policies explicitly list special sequences. Native collision/movement remains authoritative; this is not a full roomscale physics controller. Use mission evidence before generalizing a map-specific policy.";
CODE_AUDITS["pattern_overlord_immutable_input_snapshot_native_usercmd_bridge"] = "VERIFIED FROM SOURCE: `openxr_input.cpp`, `steamvr_input.cpp`/OpenVR adapter, `controller_input.cpp`, `head_pose_bridge.cpp` and `controller_component.cpp` feed a single input frame carrying time, focus, pose validity, action edges and reference/continuity generations. Action profile refresh validates the active interaction profile. `controller_component.cpp` wraps native input after original input and before `game::usercmd_s` is stored in H2's command history; static layout assertions and signature checks guard the build-specific hook. Native buttons are preserved/ORed instead of globally cleared. Invalid/stale samples and context switches invalidate edges and require neutral re-arming.\n\nPATTERN: one provider snapshot is the temporal contract shared by gameplay, hand interaction, IK and render-facing presentation. Domain systems must consume that snapshot rather than polling XR separately, or one trigger press can be a fire edge for one subsystem and a magazine edge for another. Mutate the live input command only at a verified owner stage; never alter prediction history retroactively. Keep raw grip, squeeze, trigger, trigger touch, grip pose and aim pose distinct.\n\nLIMITS: OpenXR Standard coordinate pipeline remains a manually selected trial separate from Legacy calibration. The README identifies Quest/Touch + SteamVR/OpenXR as primary validated; OpenVR/Index has a separate limited acceptance note. A valid input contract does not prove ergonomic acceptance of every device.";
CODE_AUDITS["pattern_overlord_validated_bilateral_two_bone_arm_ik"] = "VERIFIED FROM SOURCE: `gameplay/hands/pose_solver.hpp` has a 256-bone cap, explicit shoulder/elbow/wrist chains, named gun/tag/muzzle/rear-grip/laser bones and a 1.25 maximum arm stretch ratio. It validates finite lengths, parent topology and frames. A law-of-cosines solve targets hand position; the elbow pole comes from authored bend in the body frame, with an optional pole hint and source-plane fallback for degenerate geometry. `arm_plane_normal` retains authored anatomical axes for straight source arms; `orient_arm` transports upper and lower segments through one oriented bend plane rather than independently shortest-arc rotating them, which avoids sudden 360-degree elbow rolls. The pose is solved in temporary storage and copied atomically only after validation; owned weapon bones are not rewritten as ordinary arm descendants. `rig_builder.hpp` rejects duplicate/ambiguous/incompatible bone hierarchies instead of guessing.\n\nPATTERN: separate geometry solve from native model binding. Bind only a known rig/profile; clamp unreachable targets; make degenerate cases deterministic; update only the intended descendant chains; validate the entire result before mutation. A held weapon target is not automatically a full-body IK target. Overlord establishes bilateral arm solving and selected scripted upper-limb control, not full-body leg/waist tracking.\n\nTRANSFER: Reuse the solver mathematics where units/handedness are normalized. Rebuild the rig mapping per target game/model and preserve native body root, shoulders and non-arm bones unless those are explicitly authorized. Offline IK tests cannot prove final wrist fit or elbow comfort in the headset.";
CODE_AUDITS["pattern_overlord_weapon_profile_assembly_and_module_capabilities"] = "VERIFIED FROM SOURCE/DOCS: `weapon_registry.hpp`, `weapon_registration.hpp`, `weapon_profiles.hpp`, `weapon_profile_binding.hpp`, `weapon_attachments.hpp`, and `weapons/<family>/profile.hpp` form the profile system. It checks model/topology/attachment roles/cardinality and muzzle requirements, exposes bounded/deduplicated capability views, and derives detachable-magazine, tube and break-action catalogs from the registration source of truth. Each assembly can provide grip and aim anchors, hand/finger pose sets, activity bones, loading points and separate primary/underbarrel modules, including each module's own feed/action/muzzle/ammo binding. Profiles are explicit because WeaponDef class flags and bone-name guesses are not a full mechanical specification.\n\nPATTERN: inventory identity and visual model are related but not identical. Admit a feature only when the current native weapon/attachment identity matches an audited profile; maintain a stable instance/revision across pickup, stow, draw and animation/model rebuild. Treat underbarrel equipment as a separate firing/loading module, not decoration on the rifle. Capability lists should reject overflow/duplicate registrations rather than silently truncate.\n\nLIMITS: reviewed catalog and unit tests do not mean every attachment, animation, dual-wield combination or weapon has passed headset acceptance. The weapon-architecture docs explicitly keep arbitrary mixed-weapon dual wield as a non-goal/pending boundary.";
CODE_AUDITS["pattern_overlord_muzzle_validated_native_ballistics_transaction"] = "VERIFIED FROM SOURCE: `native_ballistics.cpp::initialize()` verifies masked instruction bytes for the bullet wrapper, weapon descriptors/spread path, weapon type, native trace and player-state firing gate, then initializes native ammunition access. `fire_owned()` is server-scheduler-only and checks cgame/player/command-time/state/focus/pause, validated finite muzzle geometry, native identity, supported firearm type, loaded ammo, muzzle distance, shield obstruction and an eye-to-muzzle `G_TraceCapsule`. It reads the original WeaponDef/spread values and rejects missing/out-of-range values. `native_ammunition::commit_carried()` performs expected-snapshot ammo validation/commit. The mechanical observer settles before the native bullet call because that call can synchronously trigger damage/scripts; `emitting` prevents reentry. Once native execution begins it is not rolled back/refunded as if the transaction were side-effect-free. The native function still owns damage, collision and scripts.\n\nPATTERN: treat a shot as a one-way transaction with a strict order: validate identity/context and geometry -> validate line of muzzle exit -> validate/debit ammo -> settle mechanical state -> enter native fire once -> observe result. The eye-to-muzzle test matters in VR because the tracked controller can put a muzzle through nearby cover while the eye remains behind it. Keep camera ray, controller aim ray, weapon muzzle and projectile gameplay separate. Store/revision-check the muzzle transform; a stale muzzle from the previous hand pose must not fire.\n\nLIMITS: byte signatures and offsets are exact-build-specific; no address should be copied to another executable without verification. This is guarded native fire integration, not custom ballistics or proof every attachment/shot scenario works.";
CODE_AUDITS["pattern_overlord_physical_reload_ammunition_conservation"] = "VERIFIED FROM SOURCE/DOCS: `physical_reload_runtime.cpp`, `reload_item_runtime.cpp`, `native_ammunition.cpp`, `cylinder_runtime.cpp`, `tube_runtime.cpp`, `break_action_runtime.cpp`, `launcher_runtime.cpp`, and `underbarrel_runtime.cpp` separate detachable magazines, segmented shells/tubes, cylinders, break-actions, launchers and underbarrel feeds. Native ammo reads and writes are centralized in `native_ammunition`; expected state snapshots and carried weapon identity gate writes on the native server scheduler. Reload-item objects have their own physical ownership, world/waist supply, expiry/fall/refund policies. Weapon/carry identity and physical magazine presentation are distinct. Per-instance clip/mechanical ledger and generation identity are used to reconcile drop/pickup rather than automatically resetting a feed when the entity/model changes.\n\nPATTERN: the controller gesture only means *intent*. Commit requires a known weapon profile, correct current item, compatible hand lease, valid feed stage, reserve/capacity and still-current native weapon/ammo state. Mutate game ammo on its owner thread through one adapter; do not independently decrement ammo in a visual component, native hook and reload module. If native state changed externally or the owner changed, reconcile or reject without manufacturing rounds. Settle hand ownership before firing/reload callbacks so trigger/reload state cannot race in two domains.\n\nEVIDENCE CAVEAT: older `vr-weapon-interaction-architecture.md` text still calls a larger mechanical model a design target, while current modules and focused tests implement multiple feed adapters. Report each family as source-implemented/test-covered but do not treat every profile, campaign state or headset experience as accepted. Individual magazines with persistent rounds remain a stated non-goal.";
CODE_AUDITS["pattern_overlord_central_hand_lease_arbitration"] = "VERIFIED FROM SOURCE: `interaction_coordinator.cpp` uses an explicit provider table and checked schedule covering reporting, collection, settlement and lifecycle. `hand_interaction/core.hpp` normalizes press/release edges using action generation, input sequence, sample age, reference generation and continuity. A stale/inactive sample resets the edge cursors; tracking recovery is not treated as a fresh trigger-down. Candidate decisions expose rejection reasons (invalid/no edge/incompatible/occupied/lower priority/capacity/commit failed/wrong route). The coordinator collects reload items, detachable/tube/cylinder/break-action reloads, underbarrel, equipment, grenades, mission equipment, night vision, heartbeat, world use and ladder proposals, resolves the batch once, and settles granted domains in a checked order. The same hand cannot independently be claimed by a magazine, a support grip and world-use subsystem.\n\nPATTERN: use a single “semantic intent -> candidates -> deterministic arbitration -> granted lease -> native commit -> reconciliation/presentation” pipeline. Lease identity should include input sequence, reference generation, context/target revision and native object generation so recenter, weapon swap, ownership changes or stale entities invalidate sessions. Make rejection a first-class result and keep bounded candidate/session capacity. Domains expose adapters and proposals; the coordinator should not know the internals of each reload family.\n\nTRANSFER: applies to any VR game with overlapping spatial actions (grab vs use vs reload vs climb). It prevents multiple features from responding to the same squeeze/trigger. Context changes should neutral-arm the controls; no stuck/duplicate acquisition should occur just because two domains both poll proximity.";
CODE_AUDITS["pattern_overlord_mission_camera_and_scripted_arm_handoff"] = "VERIFIED FROM SOURCE/DOCS: `gameplay/campaign/sequences/camera_policies.hpp`, `scripted_camera_reference.cpp`, and the `scripted_arms_runtime` adapter select explicit native scene identity, owner entity, model and animation phase. In the Cliffhanger opening, arms remain native for the authored crouch; tracked wrists blend in based on native stand-up animation progress, while shoulders, torso, legs, root, camera and mission ice-pick attachment remain native. The arm solver runs after the native skeleton calculation under the DObj lock, writes only the permitted arm subtree, and processes each skeleton frame once. Free climbing is a different owner/phase with its own ordinary hand interactions. Camera entry alignment is epoch-scoped and tag-dependent; checkpoint/relink/recenter clear stale baselines.\n\nPATTERN: scripts own story choreography; VR adaptation owns only explicitly granted camera/arm/control dimensions. Represent that as policy + owner identity + phase + lifecycle token, not a global map-name check. Use animation progress for pose handoff; keep native attachment objects and interaction objects from drawing duplicates. On controller loss, body replacement, phase transition or checkpoint restore, revert or rebase once, rather than catching up through a huge pose delta.\n\nLIMITS: this is selected mission-specific bilateral arms and camera policy. The code explicitly says scripted ice-pick arm IK does not implement climbing force/contact/locomotion; that is another adapter. Do not extrapolate it into generic full-body motion capture.";
CODE_AUDITS["pattern_overlord_collision_approved_physical_climbing"] = "VERIFIED FROM SOURCE/DOCS: `ladder_scene.cpp` extracts bounded/incremental LOD0 indexed geometry from static or supported single-root script models and caches actual horizontal mesh edges; it doesn't fabricate rungs from bounds. Candidate and held contact points must still hit current `SURF_FLAG_LADDER` faces and pass visibility checks. `ladder_native.cpp` wraps the native detector and only suppresses native automatic ladder mode for an eligible player's physical-ladder branch. `ladder_runtime.cpp` uses a script-owned invisible non-solid carrier and native link/ground-reference operations. `free_climb.hpp` handles retained goals and two-hand averaging; `climb_collision.hpp` bounds/slide-sweeps the full player capsule. Server phase does gameplay traces/physics; renderer only previews the already bounded current pull segment.\n\nPATTERN: separate geometry discovery from contact admission and from movement authority. A nearby mesh edge is only a candidate; the native surface bit, occlusion, current entity/model generation and hand lease must also pass. The gameplay owner computes a collision-approved absolute body position; don't add delayed player deltas on a carrier that has already moved. Two hands average shared movement, and releasing a grip rebases remaining goals. Blocked/grounded motion is consumed rather than queued into a launch. Render prediction must never issue server traces or mutate physics.\n\nLIMITS: only known static/single-root forms admitted; animated/multi-model/unverified scaled meshes fall back to the native ladder path. Documentation records remaining headset fit, jitter/upper-rail and representative mission acceptance work.";
CODE_AUDITS["pattern_overlord_vehicle_adapter_with_independent_head_heading"] = "VERIFIED FROM SOURCE/DOCS: `docs/vr-vehicles.md` and `gameplay/vehicles/` document specific `af_chase` Zodiac and `cliffhanger` snowmobile driver adapters. Admission requires the living linked player, `player.vehicle` matching its linked parent and the expected `zodiac_player`/`snowmobile_player` animation identity; passengers, boarding/end cinematics, death and unlink are excluded. Head rotation is independent of native drive yaw. The physical sticks' steering/throttle vectors are summed and length-clamped before radial deadzone mapping; view-turn is suspended while driving. Snowmobile Grip acquires the corresponding native animated handle only within 12 cm; the common hand arbiter excludes conflicting weapon/support/reload use. The driver pistol uses native `tag_flash`/native magic-bullet execution.\n\nPATTERN: vehicle adaptation is an adapter around a verified native vehicle state, not a general camera teleport or separate vehicle physics implementation. Track camera/heading, hand/handle pose and native steering as independent coordinate/ownership streams. Require native animation and linkage identity so a similar-looking passenger or transition cannot accidentally enter driver VR state.\n\nLIMITS: only those explicit campaign vehicles are documented; don't claim generic car/aircraft/boat support.";
CODE_AUDITS["pattern_overlord_native_menu_capture_ray_mapping"] = "VERIFIED FROM SOURCE/DOCS: `native_menu.cpp`, `menu_overlay.cpp`, `menu_surface.hpp`, native HUD capture, `openxr_menu.cpp` and D3D11 helpers retain native LUI/menu stack, text, mask/cursor and navigation/confirmation semantics. OpenVR uses curved frontend surfaces and flatter in-game panels; OpenXR uses quad/cylinder layers. The fitted in-game output may use 1920x1080 presentation canvas, but its geometry tracks native content extent and transparently padded pixels are not interactive. Ray hits are mapped back to the original desktop layout. The input adapter delivers absolute native pointer/key transitions without moving the Windows cursor; real desktop activity deliberately hands back ownership, while idle native mouse polling cannot steal the VR ray. Layer resize, tracker loss, owner/menu stack changes and binding changes invalidate image/pointer state independently and require neutral re-arming.\n\nPATTERN: reuse the game's own UI renderer and event/navigation model. Spatialize the rendered surface and adapt pointer mapping, not every button/widget. Keep image readiness separate from input readiness, and never allow an invalid/stale/missing image to accept a click. Preserve native stacking/backdrops/briefing hold confirmation and desktop handoff semantics. Render blur/curvature in the VR presentation path without rewriting the source menu layout.\n\nLIMITS: captured menu/HUD routes cover known native streams; they don't imply every game draw surface or debug UI is universally captured. WARP tests and counters do not prove optical alignment in a headset.";
CODE_AUDITS["pattern_overlord_fail_closed_hook_and_renderer_census"] = "VERIFIED FROM SOURCE: `main.cpp` performs supported-binary/version checks and creates a known patched binary copy for the loader. Native hook adapters use `utils::hook_validation::verify_masked_bytes` for expected call-site/wrapper bytes. Renderer stereo admission includes execution-context census evidence; an unknown D3D11 context or opaque command list that cannot be accounted for can block production stereo. OpenVR texture admission checks resource device, generation, dimensions, format, usage/flags and lifetime. Weapon adapters similarly verify shot/spread/trace entry bytes before `fire_owned` becomes eligible. Diagnostics preserve rejection/status reasons rather than crashing through unknown object state.\n\nPATTERN: treat every signature/offset/ABI, D3D texture, bone topology, weapon profile and native entity identity as an explicit capability contract. Perform preflight validation, install atomically where possible, and keep the native/fallback path when the invariant is not established. A byte match is necessary, not proof of all object state; pair it with runtime state/pipeline checks. Keep the exact build and validation evidence in diagnostics.\n\nLIMITS: this protection is version-specific and cannot make an unsupported game binary compatible. Fail-closed gates may leave tracking live while stereo stays disabled, which is better than claiming an invalid pair.";
CODE_AUDITS["pattern_overlord_weapon_recoil_on_physical_receiver"] = "VERIFIED FROM SOURCE/DOCS: `weapon_recoil_tuning.hpp` centralizes weapon family aliases/scales and type guards; recoil documentation/source records shot-time posture, support-grip ownership and recoil state. A confirmed native shot produces upward weapon pitch. The receiver, firing wrist/fingers and support hand via forearm IK move as a coherent assembly; raw controllers and HMD remain unchanged. Native pitch velocity endpoints may be descending or span zero, so both are handled; extreme/non-finite data is rejected. Base posture strengths are standing 3x, crouched 2x, prone 1x; eligible unsupported standing/crouching weapons receive a 4x penalty under default `vr_recoilPenalty=long`; prone suspends that penalty. Stored pitch decays exponentially with a 0.22 s time constant and caps at 55 degrees.\n\nPATTERN: trigger recoil from accepted shots, not input presses; record it at the shot timestamp; apply it to the physical weapon pose with receiver/hand coupling; allow tracked aim to become the recovery target. Separate posture and support-grip policy from base native recoil lookup. Validate out-of-range values and put per-family adjustments in a table, not in all fire hooks.\n\nLIMITS: current model uses hip pitch values and does not simulate horizontal recoil, the per-shot random sample, full ADS interpolation, or native acceleration/reduced-kick sequences. The tuning has device/weapon acceptance requirements.";
CODE_AUDITS["pattern_overlord_context_gated_locomotion_native_physics"] = "VERIFIED FROM SOURCE/DOCS: `controller_component.cpp` translates left-stick direction into native usercmd axes relative to horizontal HMD heading, right stick into configurable smooth/snap yaw, and button actions into native sprint/jump/stance/bind routes. It gates movement/turn/fire according to scripted camera/scene permissions, turret/vehicle/climbing state and focus/tracking. Smooth turn doesn't reset temporal history every command; discontinuous snap/camera cuts do. `roomscale_origin.hpp` compensates world space around the current HMD; it doesn't implement alternative game collision or velocity. Ladder carrier/free-climb and specific vehicle adapters use separate native ownership, so ordinary movement does not run concurrently with their special control loops.\n\nPATTERN: add intent at the earliest correct native command boundary, then let the game's movement/grounding/collision code perform the move. Decompose movement ownership by axis/action and scene phase; don't have camera, locomotion and vehicle code each write native yaw. Clear/rebase history on genuine discontinuities and neutral-arm after context changes. Special adapters should be explicit and fall back to native mode for unsupported asset geometry.\n\nLIMITS: no general full-body physical locomotion or arbitrary climb-any-surface guarantee follows from the current ladder/Cliffhanger adapters.";
CODE_AUDITS["pattern_overlord_native_authority_with_generation_ledger"] = "VERIFIED FROM SOURCE/DOCS: weapon carry uses native inventory/world ownership and typed holster/body slots; ammo is centralized through `native_ammunition`; reload item and clip/mechanical ledger code tracks physical representations separately from the native weapon/entity. Reused entity indices or a model swap do not establish the same item identity by themselves. World pickup/drop still delegates native entity/physics/notifies and the mod reconciles held/reload ledger by generation/revision. Native bullet, collision, ladder surface, story script and vehicle link operations are likewise preserved as game-owned authority boundaries.\n\nPATTERN: don't let the VR layer become a competing inventory or damage engine. Maintain a compact mapping `(native identity, generation/revision) -> VR-only mechanical/presentation state`; validate it when reacquiring, and reconcile if external game code changes weapon/inventory/mission state. Separate commit operations from cosmetic item motion. A commit that can trigger scripts is a one-way boundary; after it starts, blindly refunding state can duplicate side effects.\n\nLIMITS: a generation ledger is only as good as the identity and lifecycle witnesses. Unreviewed attachment, checkpoint or save/load transitions must be tested; persistence of magazines with individual remaining-round counts is explicitly a non-goal.";


// L4D2VR focused implementation-methodology entries (source audit, 2026-10-10).
CODE_AUDITS["pattern_l4d2vr_signature_gated_native_bootstrap"] = "VERIFIED SOURCE: `dllmain.cpp`, `game.cpp/h`, `hooks.cpp/h`, `offsets.h`, `sigscanner.h`. Native Windows x86 D3D9 proxy/in-process architecture; initialization is dispatched off DllMain; engine modules/interfaces are discovered and offsets are validated against expected byte signatures. Launch checks include `-insecure`.\n\nIMPLEMENTATION RECIPE: minimal loader-lock work → controlled initialization → module/interface readiness → centralized per-build offsets → signature validation → install hooks only after all checks pass. On any mismatch, fail closed and report the exact hook. Test delayed module load, missing interface, mismatched bytes and duplicate initialization.\n\nLIMITS: binary-specific offsets/signatures are not portable and must be revalidated per executable.";
CODE_AUDITS["pattern_l4d2vr_render_pass_classification"] = "VERIFIED SOURCE: `hooks/hooks_render.inl` declares `HooksNekoPostPass` values `MainEye`, `Scope`, `RearMirror`; probe state tracks pass/eye/sequence/takeover. D3D9 surface, sampler and temporal-state diagnostics are pass-gated, including a main-eye restriction.\n\nIMPLEMENTATION RECIPE: pass-tag render callbacks; bind diagnostics to pass + eye + frame sequence; gate modifications by intended pass; restore device state and release temporary resources on all exits. Test scope/rear-mirror/eye pass ordering.\n\nLIMITS: This is D3D9 render interception and diagnostics, not proof of custom OpenXR projection layers or compositor timing.";
CODE_AUDITS["pattern_l4d2vr_roomscale_anchor_camera_delta"] = "VERIFIED SOURCE: `vr/vr_roomscale_prediction.inl` defines `VR::GetAimRenderCameraDelta`, queues server roomscale movement with paired visual delta, replaces pending requests while cancelling paired visual displacement, and applies queued visual corrections.\n\nIMPLEMENTATION RECIPE: model tracking-to-world movement and render compensation as one transaction; replace/cancel them together; rebase on recenter, respawn and discontinuity. Test physical movement + stick movement, collision, reset and spectator transitions.\n\nLIMITS: project-specific roomscale semantics; not a general guarantee of collision-free physical motion.";
CODE_AUDITS["pattern_l4d2vr_usercmd_input_boundary"] = "VERIFIED SOURCE: `vr/vr_process_input.inl` polls semantic action state and states movement is handled through `Hooks::dCreateMove` / `CUserCmd`; `hooks/hooks_createmove.inl` includes spectator-to-live reset/recenter and combat/throwable input state.\n\nIMPLEMENTATION RECIPE: semantic actions → native command boundary; distinguish pressed/held/released; reset edge state on focus/context changes; retain native prediction/collision/server rules. Test simultaneous inputs and transition states.\n\nLIMITS: exact command semantics depend on L4D2 and server mode.";
CODE_AUDITS["pattern_l4d2vr_action_manifest_device_bindings"] = "VERIFIED SOURCE: `SteamVRActionManifest/action_manifest.json` plus separate Knuckles, Oculus Touch and Vive Cosmos binding files; `vr/vr_process_input.inl` consumes action state.\n\nIMPLEMENTATION RECIPE: central action vocabulary + per-device binding manifests; gameplay reads semantic actions, not physical button indices; validate unbound actions and pressed/held behavior.\n\nLIMITS: supplied assets evidence SteamVR action bindings, not OpenXR action-set support.";
CODE_AUDITS["pattern_l4d2vr_thread_boundary_tracking_commands"] = "VERIFIED SOURCE: comments in `vr/vr_object_pull.inl` distinguish tracking on render/input path from entity access consumed by `CreateMove`; explicit `ObjectPullTrackingSample` and trace-result structures exist. `vr_roomscale_prediction.inl` queues world movement and visual correction.\n\nIMPLEMENTATION RECIPE: publish validated pose/action samples across thread boundaries; reacquire/revalidate engine entities on their owning thread; discard stale generation/sequence after map/player/hand changes. Stress frame/tick skew and entity destruction.\n\nLIMITS: selected paths demonstrate separation, not blanket thread-safety of the whole mod.";
CODE_AUDITS["pattern_l4d2vr_guarded_engine_memory_reads"] = "VERIFIED SOURCE: `vr/vr_aiming.inl` documents transient entity/netvar memory when called from `Present()` and defines guarded scalar reads and safer entity-list accessors. `hooks/hooks_combat_network.inl` also defines guarded pointer/scalar helpers.\n\nIMPLEMENTATION RECIPE: prefer stable engine interfaces; centralize unavoidable offset reads; validate pointer, range and entity identity; return explicit failure; defer mutation to safe callbacks. Test entity deletion and concurrent updates.\n\nLIMITS: guarded reads do not make stale objects valid; layouts remain build-specific.";
CODE_AUDITS["pattern_l4d2vr_world_pose_local_wire_reconstruction"] = "VERIFIED SOURCE: `hooks/hooks_world_pose.inl` comments state player-yaw-local samples are resolved against current `ModelRenderInfo_t`; `vr_pose_protocol.h` contains wire-only packed tracked-pose structures and quantization constants.\n\nIMPLEMENTATION RECIPE: send compact local-space samples without SDK pointers; validate schema and age; resolve against current player frame; reject interpolation across teleport/identity changes.\n\nLIMITS: source supports the coordinate-frame pattern; do not overstate full avatar replication or interpolation behavior without call-site proof.";
CODE_AUDITS["pattern_l4d2vr_visual_upper_body_pose_overlay"] = "VERIFIED SOURCE: `hooks/hooks_world_pose.inl` documents a visual head/upper-body/dual-arm solve layered over final model setup, distinguishes viewmodel arms from world-model arm chain, and defines arm/finger layout/rest-chain caches.\n\nIMPLEMENTATION RECIPE: let native animation run first; apply tracked targets to selected clavicle/upper-arm/forearm/hand bones; cache bone mapping; use rest-pose fallback; keep visual pose separate from collision/hitboxes. Test survivor model variants and packet loss.\n\nLIMITS: no evidence here for tracked legs or complete full-body IK.";
CODE_AUDITS["pattern_l4d2vr_d3d9_custom_hand_rendering"] = "VERIFIED SOURCE: `vr_hands/vr_hand_renderer_d3d9.cpp` compiles D3D9 shaders, creates textures/mesh resources, defines bone constants and stencil handling; `vr_hand_system.cpp` has distinct scene/viewmodel aspect calculations and `ReprojectScenePointToViewmodelLayer`.\n\nIMPLEMENTATION RECIPE: isolate asset/skeleton from GPU resource lifecycle; recreate resources on device reset; treat world and viewmodel hand layers as separate projection/depth policies; restore D3D state on all exits. Test aspect changes, near clipping, occlusion and reset.\n\nLIMITS: D3D9-specific custom rendering; not runtime-provided OpenXR hands.";
CODE_AUDITS["pattern_l4d2vr_manifest_driven_hand_assets"] = "VERIFIED SOURCE: `vr_hands/` separates asset loader, manifest, skeleton runtime, viewmodel pose, D3D9 renderer, VR bridge and top-level hand system. `VR_HANDS_SETUP.md` documents pinned third-party dependencies.\n\nIMPLEMENTATION RECIPE: validate manifest and skeleton at load time; normalize bone mapping once; evaluate pose separately from draw; adapt weapon-bound hands to viewmodel coordinates; provide rest-pose fallback.\n\nLIMITS: module names establish architecture boundaries, not support for every arbitrary hand asset or runtime skeletal tracking.";
CODE_AUDITS["pattern_l4d2vr_two_hand_aim_basis"] = "VERIFIED SOURCE: `vr/vr_tracking.inl` defines `VR::ResolvePavlovTwoHandedAimBasis` with hand-delta, vector normalization and source-units-per-meter inputs; `vr/vr_aiming.inl` guards reads used in aim-related render paths.\n\nIMPLEMENTATION RECIPE: keep grip pose, support-hand target, weapon forward, muzzle transform and projectile direction distinct; reject degenerate/non-finite hand vectors; construct an orthonormal basis then apply weapon offsets. Validate actual call sites before assuming all weapons use this routine.\n\nLIMITS: helper existence does not prove universal weapon integration, recoil or shot-spread behavior.";
CODE_AUDITS["pattern_l4d2vr_throw_velocity_history"] = "VERIFIED SOURCE: `hooks/hooks_throwables.inl` includes pose-history recording, `ManualThrowEstimateReleaseVelocity`, bounded tick-window inputs, peak-velocity blend, finite-vector checks, speed clamping, expected weapon/kind checks and pending/reset state.\n\nIMPLEMENTATION RECIPE: sample stable-frame poses; estimate release speed from bounded history; reject discontinuities; clamp; transfer ownership to native throwable exactly once; clear pending state. Test stationary drop, locomotion, snap turn and duplicate release.\n\nLIMITS: not a generic melee sweep or arbitrary physics grab.";
CODE_AUDITS["pattern_l4d2vr_object_pull_validated_trace"] = "VERIFIED SOURCE: `vr/vr_object_pull.inl` defines tracking samples, trace results, client entity origin/bounds readers and ray/AABB intersection helpers; comments separate render/input tracking from `CreateMove` entity consumption.\n\nIMPLEMENTATION RECIPE: broad-phase candidate filter → game-supported trace/eligibility check → gameplay-thread entity revalidation → native interaction. Keep candidate visuals distinct from accepted action. Test moving/deleted targets and thin geometry.\n\nLIMITS: not all entities are necessarily eligible and this does not establish a universal spring-grab solver.";
CODE_AUDITS["pattern_l4d2vr_wire_only_pose_protocol_server_relay"] = "VERIFIED SOURCE: `vr_pose_protocol.h` explicitly defines wire-only structures shared by client relay and optional server plugin without Source SDK types; `l4d2vr_pose_server.cpp` contains plugin callbacks and per-client protocol, sequence, decode-time and acknowledgement state.\n\nIMPLEMENTATION RECIPE: fixed-width/versioned schema independent of engine SDK; validate lengths/version/features/sequence; bound per-slot retry state; separate visual pose from authoritative gameplay. Test truncation, mismatch, reconnect, slot reuse and lost acknowledgements.\n\nLIMITS: presence of sequence/ack state does not establish a complete interpolation or anti-cheat system.";
CODE_AUDITS["pattern_l4d2vr_native_engine_authority_vr_intent"] = "VERIFIED SOURCE: `vr_process_input.inl`, `hooks_createmove.inl`, `hooks_throwables.inl`, `vr_object_pull.inl` and `hooks_world_pose.inl` separate semantic input, native command handling, interaction paths and remote visual pose.\n\nIMPLEMENTATION RECIPE: semantic action → validated spatial intent → native game command/entity operation → feedback/presentation. Keep ammo/damage/collision/inventory authoritative in the game and distinguish cosmetic replicated pose from gameplay state.\n\nLIMITS: selected features have server-mode constraints; this does not mean every interaction is equally supported in every configuration.";


// Additional L4D2VR timing and HUD methodology entries (source audit, 2026-10-10).
CODE_AUDITS["pattern_l4d2vr_queued_pose_waiter_timing"] = "VERIFIED SOURCE: `vr/vr_lifecycle_pose_hud.inl`: `PoseWaiterThreadMain` calls SteamVR `WaitGetPoses` in queued mode; `ReadPoseWaiterSnapshot` reads an atomic sequence-protected pose array; `UpdatePosesAndActions` selects queued/nonqueued acquisition, prediction fallback and SteamVR action update. Queued mode avoids blocking the main thread while the waiter publishes; the fallback uses `GetDeviceToAbsoluteTrackingPose` and bounds the predicted horizon.\n\nIMPLEMENTATION RECIPE: isolate runtime wait/pacing when required by the engine queue; publish coherent pose snapshots; tag consumed snapshots with sequence/frame tokens; provide a nonblocking startup fallback; instrument success/error rates. Test queue modes, startup, tracking loss and runtime shutdown.\n\nLIMITS: SteamVR-specific. A detached worker must be coordinated with runtime lifetime; this does not prove OpenXR late latching or a general predicted-display-time architecture.";
CODE_AUDITS["pattern_l4d2vr_cpu_hud_surface_rendering"] = "VERIFIED SOURCE: `vr/vr_lifecycle_init.inl` defines RGBA `HudSurface` and clipped `FillRect`, `Clear`, `DrawRect`, plus a compact 5×7 glyph renderer. Comments document a GDI UTF-8 fallback for player names so non-Latin names can appear on the HUD.\n\nIMPLEMENTATION RECIPE: make surface dimensions/stride explicit, clip every primitive, separate layout from texture/presentation, and route arbitrary localized strings to a suitable text backend. Test buffer bounds, UTF-8 names and scale.\n\nLIMITS: these helpers do not alone prove a specific compositor layer or controller-driven UI interaction.";
CODE_AUDITS["l4d2vr_source_audited"] = "VERIFIED FROM SUPPLIED SOURCE TREE: Native x86 Windows / Source Engine / D3D9 integration through `dllmain.cpp`, `game.cpp/h`, `hooks.cpp/h`, and signature-validated offsets. Rendering hooks explicitly classify main-eye, scope and rear-mirror passes in `hooks/hooks_render.inl`. SteamVR pose acquisition has a queued-mode waiter thread and sequence-protected snapshot in `vr/vr_lifecycle_pose_hud.inl`; actions are translated at `CUserCmd` in `hooks/hooks_createmove.inl`. Camera/roomscale correction is paired in `vr/vr_roomscale_prediction.inl`; custom D3D9 hands are implemented in `vr_hands/`; multiplayer pose schema is wire-only in `vr_pose_protocol.h`, with optional server plugin `l4d2vr_pose_server.cpp`.\n\nLIMITS: build-specific offsets/signatures; SteamVR evidence is not OpenXR support; no source-backed claim here of full-body leg IK, arbitrary swept melee, or a generic physics-grab system. See the 18 focused `pattern_l4d2vr_*` entries for subsystem implementation recipes and validation cases.";



const DISCOVERY_PATTERN_FAMILIES = [
  {title:'Rendering & frame timing', features:['stereoRendering','frameTiming','cameraTracking'], desc:'Per-eye views, projection, compositor timing, pose ownership and camera injection.'},
  {title:'Input & tracked hands', features:['input','handsControls'], desc:'Semantic actions, controller poses, hand transforms, device abstraction and animation ownership.'},
  {title:'Body & IK', features:['bodyIK'], desc:'Head/hand targets, shoulders, elbows, torso, crouch, body yaw and full-body reconstruction.'},
  {title:'Weapons & melee', features:['weaponAiming','meleeCombat'], desc:'Tracked muzzle authority, support-hand solving, recoil, reload, throwing and physical hit intent.'},
  {title:'Physical interaction', features:['physicalInteraction','gestureInteraction','haptics'], desc:'Grabs, collision, body zones, gestures, physics handoff and tactile feedback.'},
  {title:'UI & spatial interfaces', features:['uiProjection'], desc:'World-space menus, controller rays, HUD projection, scopes, reticules and native widget reuse.'},
  {title:'Locomotion & vehicles', features:['locomotion','vehicles'], desc:'Roomscale, smooth movement, turning, climbing, grounding and vehicle-specific ownership.'},
  {title:'Architecture & multiplayer', features:['architecture','multiplayer'], desc:'Bootstrap/hooking, engine boundaries, replicated poses, protocol design and authority separation.'}
];
function compactText(v,n=150){ const s=(v||'').replace(/\s+/g,' ').trim(); return s.length>n?s.slice(0,n-1).trimEnd()+'…':s; }
function renderDiscoverySections(){
  const familyRoot=document.getElementById('patternFamilyGrid');
  if(familyRoot){
    familyRoot.innerHTML=DISCOVERY_PATTERN_FAMILIES.map(f=>{
      const count=DB.filter(e=>e.type==='pattern' && f.features.some(k=>cachedEntrySubsystems(e).includes(k))).length;
      const chips=f.features.map(k=>`<button type="button" data-explore-preset data-type="pattern" data-feature="${escapeAttr(k)}">${escapeHtml(featureShortLabel(k))}</button>`).join('');
      return `<article class="knowledge-card"><span class="knowledge-kicker">${count.toLocaleString()} source-backed patterns</span><h3>${escapeHtml(f.title)}</h3><p>${escapeHtml(f.desc)}</p><div class="family-links">${chips}</div></article>`;
    }).join('');
  }
  const modsRoot=document.getElementById('featuredModsGrid');
  if(modsRoot){
    const preferred=[
      ['Dead Island 2 VR','Dead Island 2'],['CyberpunkVR Port','Cyberpunk 2077'],['L4D2VR','Left 4 Dead 2'],
      ['Skate 3 VR','Skate 3'],['HaloCEVR','Halo: Combat Evolved'],['LCVR','Lethal Company']
    ];
    modsRoot.innerHTML=preferred.map(([label,q])=>{
      const hits=DB.filter(e=>cachedEntrySearchText(e).includes(q.toLowerCase()));
      const caseStudy=hits.find(e=>e.type==='case_study') || hits[0];
      const pcount=hits.filter(e=>e.type==='pattern').length;
      if(!caseStudy) return '';
      return `<article class="project-card" tabindex="0" role="button" data-explore-preset data-query="${escapeAttr(q)}"><span class="project-kicker">${pcount.toLocaleString()} extracted patterns</span><h3>${escapeHtml(label)}</h3><div class="project-engine">${escapeHtml(caseStudy.engineFamily||'')}</div><p>${escapeHtml(compactText(caseStudy.summary,170))}</p><span class="project-count">${hits.length.toLocaleString()} related registry references →</span></article>`;
    }).join('');
  }
  const enginesRoot=document.getElementById('engineOverviewGrid');
  if(enginesRoot){
    const cats=Array.from(new Set(DB.map(e=>engineCategory(e.engineFamily)).filter(Boolean))).map(cat=>{
      const entries=DB.filter(e=>engineCategory(e.engineFamily)===cat); return {cat,entries,patterns:entries.filter(e=>e.type==='pattern').length,cases:entries.filter(e=>e.type==='case_study').length};
    }).sort((a,b)=>b.entries.length-a.entries.length);
    enginesRoot.innerHTML=cats.map(x=>`<article class="engine-card" tabindex="0" role="button" data-explore-preset data-engine="${escapeAttr(x.cat)}"><span class="engine-kicker">${x.entries.length.toLocaleString()} references</span><h3>${escapeHtml(x.cat)}</h3><p>${x.patterns.toLocaleString()} methodology patterns · ${x.cases.toLocaleString()} case studies</p><span class="engine-count">Open this engine collection →</span></article>`).join('');
  }
}

function updateSiteStats(){
  if(!DB) return;
  const games = new Set(DB.map(e=>(e.game||'').trim()).filter(Boolean));
  const patterns = DB.filter(e=>e.type==='pattern').length;
  const set=(id,val)=>{ const el=document.getElementById(id); if(el) el.textContent=String(val); };
  set('statReferences', DB.length.toLocaleString());
  set('statProjects', games.size.toLocaleString());
  set('statPatterns', patterns.toLocaleString());
  set('statSubsystems', Object.keys(FEATURE_DEFS).length);
}

const originalRender = render;
render = function(){
  originalRender();
  updateSiteStats();
  renderDiscoverySections();
  syncFilterStateToURL();
};

document.addEventListener('keydown', ev=>{
  if((ev.key==='Enter' || ev.key===' ') && ev.target?.matches?.('[role=\"button\"][data-explore-preset]')){ ev.preventDefault(); openExplorePreset(ev.target); return; }
  if(ev.key==='/' && !ev.metaKey && !ev.ctrlKey && !ev.altKey){
    const active=document.activeElement;
    const typing=active && ['INPUT','TEXTAREA','SELECT'].includes(active.tagName);
    if(!typing){ ev.preventDefault(); document.getElementById('searchInput')?.focus(); }
  }
  if(ev.key==='Escape' && document.activeElement===document.getElementById('searchInput')){
    document.getElementById('searchInput').blur();
  }
});

const backToTop=document.getElementById('backToTop');
window.addEventListener('scroll',()=>{ if(backToTop) backToTop.classList.toggle('visible',window.scrollY>700); },{passive:true});
backToTop?.addEventListener('click',()=>window.scrollTo({top:0,behavior:'smooth'}));


document.querySelectorAll('[data-registry-query]').forEach(link=>{
  link.addEventListener('click',()=>{
    const q=link.dataset.registryQuery || '';
    filters.query=q; resetResultPage();
    const input=document.getElementById('searchInput');
    if(input) input.value=q;
    if(DB) render();
  });
});

readFilterStateFromURL();
loadDB();


// Persistent browser-local notepad.
(() => {
  const NOTES_KEY='vregistry_personal_notes_v1';
  const panel=document.getElementById('notesPanel');
  const toggle=document.getElementById('notesToggle');
  const closeBtn=document.getElementById('notesClose');
  const scrim=document.getElementById('notesScrim');
  const text=document.getElementById('notesText');
  const status=document.getElementById('notesStatus');
  const count=document.getElementById('notesCount');
  const clearBtn=document.getElementById('notesClear');
  const copyBtn=document.getElementById('notesCopy');
  if(!panel || !toggle || !text) return;

  let saveTimer=null;
  let lastFocus=null;

  const updateCount=()=>{ if(count) count.textContent=`${text.value.length.toLocaleString()} characters`; };
  const setStatus=(label,saved=false)=>{
    if(!status) return;
    status.textContent=label;
    status.classList.toggle('saved',saved);
  };
  const saveNotes=()=>{
    try{
      localStorage.setItem(NOTES_KEY,text.value);
      setStatus('Saved',true);
    }catch(err){
      console.warn('VRegistry notes could not be saved',err);
      setStatus('Save unavailable',false);
    }
  };
  const scheduleSave=()=>{
    setStatus('Saving…',false);
    clearTimeout(saveTimer);
    saveTimer=setTimeout(saveNotes,350);
  };
  const openNotes=()=>{
    lastFocus=document.activeElement;
    panel.classList.add('open');
    panel.setAttribute('aria-hidden','false');
    toggle.setAttribute('aria-expanded','true');
    if(scrim){ scrim.hidden=false; requestAnimationFrame(()=>scrim.classList.add('open')); }
    setTimeout(()=>text.focus(),40);
  };
  const closeNotes=()=>{
    saveNotes();
    panel.classList.remove('open');
    panel.setAttribute('aria-hidden','true');
    toggle.setAttribute('aria-expanded','false');
    if(scrim){ scrim.classList.remove('open'); setTimeout(()=>{ if(!panel.classList.contains('open')) scrim.hidden=true; },180); }
    if(lastFocus && typeof lastFocus.focus==='function') lastFocus.focus(); else toggle.focus();
  };

  try{ text.value=localStorage.getItem(NOTES_KEY) || ''; }catch(_){ text.value=''; }
  updateCount();

  toggle.addEventListener('click',()=> panel.classList.contains('open') ? closeNotes() : openNotes());
  closeBtn?.addEventListener('click',closeNotes);
  scrim?.addEventListener('click',closeNotes);
  text.addEventListener('input',()=>{ updateCount(); scheduleSave(); });
  text.addEventListener('blur',saveNotes);

  clearBtn?.addEventListener('click',()=>{
    if(!text.value || confirm('Clear all notes saved in this browser?')){
      text.value=''; updateCount(); saveNotes(); text.focus();
    }
  });
  copyBtn?.addEventListener('click',async()=>{
    try{
      await navigator.clipboard.writeText(text.value);
      setStatus('Copied',true);
      setTimeout(()=>setStatus('Saved',true),900);
    }catch(_){
      text.select();
      try{ document.execCommand('copy'); setStatus('Copied',true); }
      catch(__){ setStatus('Copy failed',false); }
      setTimeout(()=>setStatus('Saved',true),900);
    }
  });
  document.addEventListener('keydown',ev=>{
    if((ev.ctrlKey || ev.metaKey) && ev.key.toLowerCase()==='s' && panel.classList.contains('open')){
      ev.preventDefault(); saveNotes();
    }
    if(ev.key==='Escape' && panel.classList.contains('open')){
      ev.preventDefault(); closeNotes();
    }
  });
})();

